!function(){"use strict";window.__bookText={wars_demons:{id:"wars_demons",title:"حروب الشياطين",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1rEOeeeiVHXZtaT12cQtKr6STTb5JmAJR/view",file:"حروب_الشياطين.pdf",pageOffset:1,review:{status:"needs-review",note:"نُقل الكتاب كله (من ص٨ إلى ص١١٨ بالترقيم المطبوع، أي المتن بفصوله الخمسة بلا الغلاف والفهرس) بقراءة صفحات الكتاب الممسوحة بالنظر وبنفس إملاء الطباعة (بما فيها أخطاؤها الطباعية)؛ يحتاج مطابقة نهائية مع الأصل. عناوين الفصول الرابع والخامس قُرئت من صفحات عنوان مطبوعة بخط مزخرف."},chapters:[{title:"الفصل الأول: طبيعة حروب الشياطين",from:7,to:13},{title:"الفصل الثاني: صفات الشيطان في حروبه",from:14,to:31},{title:"الفصل الثالث: حيل الشيطان",from:32,to:89},{title:"الفصل الرابع: كيفية الإنتصار على حروب الشياطين",from:90,to:113},{title:"الفصل الخامس: فوائد الحروب الروحية",from:114,to:117}],transcribed:[7,117],pages:{7:["الحروب الروحية سمح بها الله لفائدتنا ... ووراءها أكاليل . وعلى رأى أحد القديسين الذى قال :",{h:"لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب ."},"فهى من جهة الله إختبار لحرية إرادتنا ، وإعطاؤنا الفرصة التى نستحق بها خيرات الملكوت ، إذا انتصرنا... أما من جهة الشيطان ، فمن طبيعته أن يقاوم ملكوت الله ، ويحارب الساعين إليه . وهو يحارب الله فى شخص أولاده . ويشتكى عليهم كما حدث فى قصة أيوب الصديق (أى ١ ، ٢) . وهو يحسد السالكين فى حياة البر ، لكى لا ينالوا البركة الإلهية التى حُرم هو منها .",{h:"وحروب الشياطين هى ضد الكل ، لم ينجُ منها أحد ."},"ونحن حينما نتكلم عن هذه الحروب ، إنما نقصد الحرب التى يثيرها الشيطان وكل جنوده وأعوانه .","منذ أيام آدم وحواء وإبنها قايين ، والشيطان قائم يحارب ، يحاول بكل جهده أن يلقى البشرية تحت حكم الموت الأبدى . وقد أسقط أنبياء ورسلاً ، وأشخاصاً حلّ عليهم روح الرب مثل داود وشمشون اللذين تابا ، ومثل شاول الملك الذى رفضه الرب ، وفارقه روح الله « وبغته روح ردىء من قبل الرب » (١صم ١٦ : ١٤) .",{h:"فلا تظنوا أن حروب الشياطين هى للمبتدئين فقط أو للخطاة ."},"كلا ، فهو يحارب الكل ، مهما كانوا نامين فى النعمة ، بل يحارب هؤلاء بالأكثر . لذلك على كل إنسان أن يحترس ، وأن لا يظن بأنه قد ارتفع فوق مستوى حروب معينة . ولنتذكر أن معلمنا داود النبى حورب بخطية زنا وسقط فيها ، مع أنه كان قد حلّ عليه روح الرب وصار مسيحاً له... إن الشيطان يريد أية فريسة .","وقد وصفه القديس بطرس الرسول بعبارة خطيرة قال فيها :","« إبليس خصمكم كأسد زائر ، يجول ملتمساً من يبتلعه هو » (١بط ٥ : ٨) ."],8:["وهو دائم الجولان لصيد فرائسه . ولما سأله الرب (فى قصة أيوب) « من أين جئت ؟ » أجاب فى صراحة « من الجولان فى الأرض ومن التمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . وطبعاً الغرض من هذا الجولان هو البحث عن أية فريسة يسقطها...",{h:"والشيطان لا ييأس ، مهما كان الذى يحاربه قوياً ."},"بل قيل عن الخطية إنها « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) . والشيطان لم يتورع عن محاربة حتى رسل المسيح الإثنى عشر. وقد قال الرب فى ذلك للقديس بطرس الرسول « هوذا الشيطان طلبكم لكى يغربلكم كالحنطة . ولكنى طلبت من أجلك لكى لا يفنى إيمانك » (لو ٢٢ : ٣١ ، ٣٢) . ولنتذكر أن إيليا النبى العظيم الذى أصعده الله إلى السماء ، قال عنه القديس يعقوب الرسول « إيليا كان إنساناً تحت الآلام مثلنا » (يع ٥ : ١٧) .","بل إن الشيطان تجرأ أن يجرب السيد المسيح نفسه .","فقدم له ثلاث تجارب على الجبل (متى ٤) . ولم يثنه عن ذلك كل الذى كان يعرفه عن المسيح . ولم تثنه الإعلانات الإلهية التى سبقت ذلك وقت العماد (متى ٣ : ١٣ - ١٧) . بل حاربه طوال الأربعين يوماً (مر ١ : ١٣ ، لو ٤ : ٢) .","وقيل عن السيد المسيح إنه « كان مجرباً فى كل شىء مثلنا ، بلا خطية » (عب ٤ : ١٥) . وإنه « فيما هو قد تألم مجرباً يقدر أن يعين المجربين » (عب ٢ : ١٨) .","حقاً إن تجارب المسيح من الشيطان عزاء لنا فى كل تجاربنا... إن حلّت بك تجربة فلا تتضايق ، إن المسيح قد جرب من قبلك ، وكما انتصر المسيح سوف تنتصر أنت أيضاً .",{h:"إن حروب الشياطين موجهة ضد الله نفسه وضد ملكوته ، وضد هياكله المقدسة التى هى نحن ."},"فهو يريد أن يقاوم هذا الملكوت بكافة الطرق . ويفرح إن أمكنه أن يسقط « حتى المختارين أيضاً » (متى ٢٤ : ٢٤) .","وإن كانت ملائكة السماء تفرح بخاطىء واحد يتوب (لو ١٥ : ١٠) ، فلا شك أن الشياطين تفرح ببار واحد إذا سقط ، بل تفرح بسقوط أى أحد يخضع لهم .","والقديس بولس الرسول ، يشرح هذه الحروب الروحية فيقول :"],9:["« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس . فإن مصارعتنا ليست مع دم ولحم ، بل مع الرؤساء مع السلاطين ... مع أجناد الشر الروحية فى السماويات ... » (أف ٦ : ١١ ، ١٢) .","وشرح كيف أن هذه الحروب الروحية تحتاج إلى أسلحة روحية لمقاومتها ، ذكرها الرسول فى نفس الأصحاح بالتفصيل... ولابد لها من معونة الله ، الذى قال « بدونى لا تقدرون أن تفعلوا شيئاً » (يو ١٥ : ٥) . وفى هذه الحرب الروحية ما أجمل أن نتذكر قول داود النبى « الحرب للرب » (١صم ١٧ : ٤٧) .",{h:"والحروب الروحية حروب دائمة . قد تتنوع ، ولكن لا تنتهى ."},"طالما أنت فى الجسد ، فأنت معرض لهذه الحروب ، التى تظل معك حتى الموت . ولذلك قال القديس بطرس الرسول « سيروا زمان غربتكم بخوف » (١بط ١ : ١٧) . ولا يقصد بالخوف ، الرعب من الشياطين... إنما الخوف الذى يدعو إلى الحرص والتدقيق .","بالنسبة إلى الفرد ، الحرب تستمر حتى الموت . وبالنسبة إلى العالم ، تستمر مدى الدهر ، إلى نهاية العالم . حتى أن الشيطان حينما يُحل من سجنه ، يخرج ليضل الأمم (رؤ ٢٠ : ٧ ، ٨) . وفى نهاية الأيام سيكون هناك ارتداد عن الإيمان (١تى ٤ : ١) ، « وستأتى أزمنة صعبة » (٢تى ٣ : ١) . وقبل مجىء المسيح سيكون الإرتداد العام (٢تس ٢ : ٣) . وسيبذل الشيطان كل جهده ، وسينزل إلى الأرض « وبه غضب عظيم ، عالماً أن له زماناً قليلاً بعد » (رؤ ١٢ : ١٢) .",{h:"والحرب الدائمة التى للشيطان قد تشتد فى الأوقات المقدسة ."},"فالشيطان يتضايق جداً ، حينما نبدأ فى أى عمل روحى . ويسعى بكل الحيل لئلا تفلت الفريسة من يده . فنحن نبدأ العمل الروحى ، ويبدأ هو معنا حروبه وحيله ومعطلاته الكثيرة .",{h:"فنحن نبدأ العمل الروحى ، وهو يبدأ المقاومة ."},"لأنه لا يستريح لأية صلة لنا مع الله . يظن أن هذه تهدد ملكه بالضياع . ومن العبارات الجميلة فى بستان الرهبان : إنه عندما يدق جرس الصلاة فى نصف الليل ، فإنه لا يوقظ الرهبان فقط للصلاة و إنما أيضاً يوقظ الشياطين لكى يحاربوا الرهبان"],10:["ويمنعوهم عن الصلاة... ولذلك قال القديس مارأوغريس :",{h:"إذا بدأت الصلاة الطاهرة ، فاستعد لكل ما يأتى عليك ."},"إننا إذا بدأنا فى الوسائط الروحية أياً كانت ، سواء فى عمل الصلاة ، أو التأمل ، أو التسبيح ، أو القراءات الروحية ، أو المطانيات... فإن الشيطان لا يقف مكتوف اليدين أو متفرجاً ، إنما يعمل هو أيضاً عمله ، وله أنواع حروب يحارب بها . وما أصدق قول الكتاب فى سفر يشوع بن سيراخ :",{h:"يا إبنى ، إن تقدمت لخدمة ربك ، فهيىء نفسك لجميع التجارب ."},"وهذه الآية نقولها ضمن فصل نتلوه فى سيامة الراهب الجديد . كما إنها إحدى قراءات الساعة الثالثة من يوم الثلاثاء من البصخة المقدسة . فالذين يستعدون لقتال الشيطان ، من الطبيعى أن يستعد الشيطان أيضاً لقتالهم . لذلك لا تتعجبوا للحروب التى تصاحب العمل الروحى... وحذار أن تجعلكم هذه الحروب تتراجعون... بل اثبتوا فى قوة ، مهما نالكم من تعب ، متذكرين قول القديس بولس الرسول « كونوا راسخين ، غير متزعزعين ، مكثرين فى عمل الرب كل حين ، عالمين أن تعبكم ليس باطلاً فى الرب » (١كو ١٥ : ٥٨) .",{h:"نحن نبدأ الجهاد ، وهو يبدأ الحرب . نبدأ الروحيات ، فيبدأ المقاومة ."},"الشيطان مثلاً يتضايق من الصوم ، لأنك فيه تريد أن تقمع جسدك وتستعبده (١كو ٩ : ٢٧) ، لكى ترتفع روحك وتلتقى بالله... والشيطان لا يقبل هذا . كما أنه يتضايق من الصوم الكبير بصفة خاصة ، لأن الناس يسلكون فيه بنسك شديد ، كما أن هذا الصوم يذكّر الشيطان بصوم السيد المسيح وكيف قهر الشيطان فيه (متى ٤) . لذلك يجاهد الشيطان أن يعرقل هذا الصوم ، أو أن يثير فيه مشاكل ، حتى ينشغل الناس بالمشاكل ، ويتركوا العمل الروحى .","ولهذا فالبعض يربطون بين هذا الصوم ، والمشاكل والتجارب .",{h:"ولا شك أن العمل الروحى يثير حسد الشياطين ..."},"إن الشيطان يحسد الإنسان الروحى على صلته بالله ، التى حُرم هو منها . ويحسده لأنه هو إنسان ترابى مرتبط بجسد ، يحاول أن يجعل روحه تسمو وتعلو ، بينما الشيطان وهو روح (متى ١٢ : ٤٥) بعيد عن الله ، وروحه روح نجسة (مر ١ : ٢٧) !","ومنذ البدء حسد الشيطان أبوينا آدم وحواء وأوقعها فى الخطية وفى حكم الموت ."],11:["وهكذا نقول فى صلوات القداس الإلهى « والموت الذى دخل إلى العالم بحسد إبليس » .",{h:"والشيطان لا يحسد إلا الناجحين فى عملهم الروحى ."},"يحسد المقتربين إلى الله ، والذين لهم دالة عنده . ويحسد التائبين فى حرارة التوبة ، والعابدين وهم فى عمق الصلة . ويحسد المتضعين والودعاء والأنقياء . ويحارب كل هؤلاء . أما الخاضعون له وللخطية ، والفاترون فى حياتهم الروحية . فلماذا يحاربهم ؟! يكفيهم ما هم فيه . أو إنه يضعهم تحت المراقبة ، أو يورطهم فى حالة أسوأ .",{h:"وهنا نذكر بعض أنواع من الحروب الروحية ."},"ونذكر هنا ثلاثة أنواع رئيسية وهى :","أ ـ حالة إنسان يحاربه الشيطان حرباً خفيفة أو ثقيلة .","ب ـ إنسان تحاربه شهواته من داخل . ربما الشيطان قد وضع نقطة البدء ، ثم ترك هذه الفريسة المسكينة يحاربها فسادها الداخلى ، أو تحاربها عاداتها المتوطنة فيها ، المسيطرة عليها . هناك إنسان يحارب من جسده ومن غرائزه ، وآخر يحارب من نفسه أو من فكره .","ج ـ أما الحالة الثالثة فهى لإنسان يحاربه إخوة كذبة ، أو أناس أشرار ، أو بيئة شريرة تحيط به ، ويمكن أن نسميهم جميعاً « أعوان الشياطين » و « كل جنده » ...","ولهذا تعلمنا الكنيسة أن نصلى فى آخر صلاة الشكر ونقول : كل حسد ، وكل تجربة ، وكل فعل الشيطان ، ومؤامرة الناس الأشرار ، وقيام الأعداء الخفيين والظاهرين... إنزعها عنا وعن سائر شعبك... » .",{h:"وهناك نوع يمكن أن نسميه إمتحاناً أو إختباراً ، وليس حرباً ."},"وكمثال لهذا يقول الكتاب « وحدث ... أن الله إمتحن إبراهيم . وقال له ... خذ إبنك وحيدك الذى تحبه إسحق ... وأصعده ... محرقة ... » (تك ٢٢ : ١ ، ٢) . وهنا لم يكن الله يحارب أبانا إبراهيم ، حاشا... بل كان يمتحن قلبه ليرى عمق محبته له وعمق طاعته... ونجح أبونا إبراهيم فى هذا الإختبار...",{h:"القديس والخاطىء كلاهما معرضان للحرب . ولكن ما الفرق بينها ؟"}],12:["الفرق الأساسى هو أن القديس له حرب من الخارج فقط . أما داخله فإنه نقى ، لا يتفق مع الحرب الخارجية بل يرفضها ويقاوم بكل قوته لكى ينتصر عليها .","أما عن الخاطىء أو الشرير فقد تكون الحرب بالنسبة إليه مزدوجة ، من الخارج ومن الداخل معاً . تحاربه إغراءات الشيطان من الخارج ، وتحاربه شهواته من داخل قلبه وفكره . لذلك هو يستسلم لحرب الشيطان ، ويفتح له أبوابه الداخلية . ويقبل أفكاره ومقترحاته مرحباً بها . وإن قاوم ـ لبقية ضمير فيه ـ فإنها تكون مقاومة هزيلة لا تستمر طويلاً ، ولا تكون جادة فى صد أفكار العدو الخارجى .","وحروب القديسين تظهر فيها قوتهم وانتصارهم . أما الخطاة فينهزمون ...",{h:"وقد يسمح الله أحياناً بانهزام القديسين ، مؤقتاً ، لفائدتهم ..."},"فالإنسان المنتصر على طول الخط ، ربما تحاربه الكبرياء ، ويظن فى نفسه أنه شىء !! لذلك سمح الله أحياناً أن ينهزم القديسون ، لكى تنسحق قلوبهم من الداخل ، ويعيشوا فى اتضاع . ولكى يعرفوا قوة العدو وقسوته فى الحروب ، فيشفقوا على أخوتهم المحاربين . وكما قال القديس بولس الرسول :",{h:"« أذكروا المقيدين كأنكم مقيدون معهم . و ( اذكروا ) المذلين كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) ."},"إن الإنسان الذى لم يجرب بحروب الشياطين ، ربما يدين الذين يسقطون أو يحتقرهم ، بعكس الذى قاسى وتعب ، فإنه يحن عليهم ويشفق ، ويصلى لأجل خلاصهم . وكما قال الرسول « عالمين أن نفس هذه الآلام تجرى على أخوتكم الذين فى العالم » (١بط ٥ : ٩) ... حقاً ما أرهب قول الكتاب فى سفر الرؤيا عن الوحش :",{h:"« وأعطى أن يصنع حرباً مع القديسين ويغلبهم » (رؤ ١٣ : ٧) ."},"بل ما أرهب أيضاً ما قيل بعد ذلك « وأعطى سلطاناً على كل قبيلة ولسان وأمة . فسيسجد له جميع الساكنين على الأرض... » (رؤ ١٣ : ٧ ، ٨) . ولكن لئلا ييأس البعض من ذلك ، ذكر أن هؤلاء الساجدين هم : الذين ليست أسماؤهم مكتوبة منذ تأسيس العالم فى سفر الحياة... أى أبناء الهلاك... ومع ذلك هم عدد كبير بلا شك يدل على عنف حرب الشيطان وجنوده... ومما يعزينا فى ذلك أيضاً ، أن الوحش هو والشيطان مُطرحان فى بحيرة النار والكبريت (رؤ ٢٠ : ١٠)..."],13:[{h:"ولكننا ذكرنا كل هذا ، لكى يكون لدينا حرص ."},"مادام عدونا بهذه الوحشية ، فلنستمع إذن إلى قول الرسول « أنظروا كيف تسلكون بتدقيق ، لا كجهلاء بل كحكماء ، مفتدين الوقت لأن الأيام شريرة » (أف ٥ : ١٥ ، ١٦) . إنتصارات الشيطان لا تدفعنا إلى الخوف ، بل إلى الحرص والتدقيق . وأيضاً تدفعنا إلى عدم الإعتماد على أنفسنا ، وإنما :",{h:"فى حروبنا نلتصق بالرب ، لأن من عنده المعونة والنصرة ."},"هو الذى يحارب الشيطان فينا ، وهو الذى يغلب العالم فينا . أليس هو القائل « ثقوا ، أنا قد غلبت العالم » (يو ١٥ : ٣٣) . نعم غلب العالم فى حرب الشيطان معه . ويغلب العالم الآن وكل أوان ، فى حربه معنا . وكذلك :",{h:"« شكراً لله ، الذى يقودنا فى موكب نصرته » (٢كو ٢ : ١٤) ."},"إنه انتصر على الشيطان فى طبيعتنا البشرية . فقدّس هذه الطبيعة وباركها ، وأعطاها روح النصرة . وهكذا نقول له فى القداس الغريغورى « باركت طبيعتى فيك » ... لقد انتصر الشيطان من قبل ، على هذه الطبيعة البشرية . ولكن السيد المسيح أعاد إلى هذه الطبيعة البشرية صورتها الإلهية ، وهيبتها فى نظر الشياطين ، حينما هزم الشيطان فيها .",{h:"فلم يعد الشيطان يرى أن هذه الطبيعة هى لعبته ، ينتصر عليها متى يشاء... وإذ انهزم أمامها ، بدأ يخشاها..."},"وبهذا أيضاً أنقذنا من روح الفشل ، وأعطانا قوة من عنده فى حروب الشياطين لنا . وأصبح لنا الرجاء كل حين ، أن المسيح يغلب الشيطان فينا ، حينما « يحل المسيح بالإيمان فى قلوبنا » (أف ٣ : ١٧) .","وبسبب هذا نحن لا نتضايق من حروب الشياطين ، مادامت يد الرب تكون معنا فيها ، ويحارب عنا وينصرنا...",{h:"الله لا يمنع عنا حروب الشياطين ، إنما ينصرنا فيها ."},"هو الذى يحارب عنا ، وهو الذى يغلب الشياطين . وبعد ذلك يكللنا ، لأننا سلمناه إرادتنا أثناء حربه عنا ضد الشياطين .","هذه مقدمة بسيطة ننتقل بعدها إلى الحديث عن الشيطان وحيله..."],14:[{h:"الفصل الثانى"},{h:"صفات الشيطان فى حروبه"}],15:[{h:"ينبغى أن نعرف صفات عدونا ، وأسلوبه فى القتال ، لنعرف كيف نحاربه ."},"فما هى صفات الشيطان ؟ وكيف يحارب ؟ وهل له أسلوب ثابت ، أم أنه يتغير فى أساليبه حسب تغير الحالة ؟ هذا ما نريد أن نفحصه ، حتى نستطيع أن نواجهه . وكما قال بولس الرسول « لئلا يطمع فينا الشيطان . لأننا لا نجهل أفكاره » (٢كو ٢ : ١١) .","ونستطيع أن نعرف مما رواه لنا الكتاب عن الشيطان أنه :",{h:"١ ـ صاحب قتال لا يهدأ"},"صار عمله منذ سقوطه هو المقاتلة والمحاربة . فهو دائماً مقاتل fighter حتى قبل إسقاطه لأبوينا الأولين آدم وحواء ، إستطاع أن يُسقط مجموعات من ملائكة السماء ، تبعوه وصاروا من جنده من طغمات كثيرة .",{h:"ومن ذلك الحين أصبحت هوايته إسقاط الآخرين ."},"صار يقاتل الكل . وكما أسقط طغمات ملائكية من الكاروبيم والسلاطين والرؤساء والقوات... كذلك رأيناه يقاتل أنبياء الله ورسله ومسحاءه ، ويقاتل المتوحدين والسواح والرهبان وكل محبى الله ، وكل من يسمع أنه فى خير ، أو فى برّ .","وقد سمى المعاند والمقاوم ، لأنه دائماً يقاوم ملكوت الله و يعاند مشيئته . كما سمى أيضاً التنين ، والحية القديمة ، وإبليس ، والشيطان (رؤ ١٢ : ٩) ، وقبل الصليب كان يسمى رئيس هذا العالم (يو ١٤ : ٣٠) .",{h:"وهو فى قتاله لا يهدأ مطلقاً ولا يملّ ولا يستريح ."},"دائماً « يجول كأسد يزأر » (١بط ٥ : ٨) . وقد قال للرب مرتين فى قصة أيوب إنه مشغول « بالجولان فى الأرض والتمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . إنه ساهر"],16:["باستمرار يرقب حالة ضحاياه ، ويلقى بذاره فى كل مكان . وحيثما يزرع الرب حنطة ، يأتى هو « ويزرع زواناً وسط الحنطة ، فيما الناس نيام » (متى ١٣ : ٢٥) .",{h:"وليس البشر فقط ، بل حتى الملائكة يحاربهم ."},"فقد وقف ضد الملاك ميخائيل يحاججه من جهة جسد موسى النبى (يه ٩) . ووقف ضد أحد الأرباب الذى عمل على أن ينقذ منه يهوشع الكاهن (زك ٣ : ١ ، ٢) . كذلك وقف واحداً وعشرين يوماً ضد الملاك الذى أرسله الرب لدانيال النبى ، لولا تدخل رئيس الملائكة ميخائيل لإعانته (دا ١٠ : ١٢ ، ١٣) . بل ما أعجب قول الإعلان الإلهى فى سفر الرؤيا :","وحدثت حرب فى السماء : ميخائيل وملائكته حاربوا التنين ... وملائكته (رؤ ١٢ : ٧) . إنه يحارب فى الأرض وفى السماء ، مع أن كل حروبه تنتهى أخيراً إلى هلاكه وهزيمته ولكنه لا يستطيع أن يبطل الحرب ، لأنها صارت جزءاً من طبيعته .","ومن صفات الشيطان أيضاً أنه قوى .",{h:"٢ ـ قوى"},"لأنه أحد الملائكة « المقتدرين قوة » حسبما وصفهم المرتل (مز ١٠٣ : ٢٠) .",{h:"هو كملاك فقد طهارته ، لكن لم يفقد طبيعته القوية ."},"لذلك وصفه الرسول بأنه « أسد زائر » (١بط ٥ : ٨) . وهكذا نراه فى سفر أيوب إستطاع أن « يضرب به بقرح ردىء من باطن قدمه إلى هامته » (أى ٢ : ٧) ، كما إستطاع أن يثير ريحاً شديدة صدمت زوايا بيت أيوب ، فسقط على الغلمان فماتوا (أى ١ : ١٩)... وهناك دلائل روحية كثيرة على قوته ، منها :",{h:"إنه استطاع أن يضل العالم كله أيام الطوفان ."},"ولم تنجُ من ضلاله سوى أسرة واحدة هى أسرة أبينا نوح (تك ٦) . ورأى الله أن الحل الوحيد لتطهير الأرض من الفساد ، هو إبادة كل نفس حية على وجه الأرض .",{h:"ونفس الوضع نقوله عن مدينة سادوم ."},"فلم يجد الله فيها عشرة من الأبرار ، حتى يرحم المدينة من أجل العشرة (تك ١٨ : ٣٢) . ولم يوجد فيها سوى أسرة لوط فقط (أربعة أشخاص) . هلكت من بينهم إمرأة"],17:["لوط خارج المدينة . وأخطأت البنتان بعد خروجها من سادوم . ولوط نفسه قيل عنه حينما كان فى سادوم إنه « كان بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه البارة بالأفعال الأثيمة » (٢بط ٢ : ٨) .",{h:"وقوة الشيطان تظهر فى إلقائه العالم كله فى الوثنية ."},"كيف استطاع أن يلقى العالم كله فى الوثنية فى العهد القديم ، ماعدا شعباً واحداً ؟! هذا أمر خطير . بل حتى هذا الشعب الواحد وقع فى عبادة الأصنام هو أيضاً ، حينما كان موسى النبى على الجبل ، إذ صنعوا لأنفسهم عجلاً ذهبياً ، وقدموا له الذبائح . وقالوا « هذه آلهتك يا إسرائيل التى أصعدتك من أرض مصر » (خر ٣٢ : ١ ـ ٦) .","وفى أيام إيليا النبى فى عهد آخاب الملك ، كان فى شعب الله ٤٥٠ نبياً للبعل ، و ٤٠٠ نبياً للسوارى أى ثمانمائة وخمسون نبياً كاذباً كانوا يأكلون على مائدة الملكة إيزابل (١مل ١٨ : ١٩) . وحدث أن كثيراً من ملوك يهوذا وإسرائيل وقعوا فى عبادة الأصنام « وجعلوا إسرائيل يخطىء » كما تروى لنا أسفار الملوك وأخبار الأيام .",{h:"ومن قوة الشيطان إسقاطه لسليمان الحكيم فى عبادة الأصنام ."},"سليمان أحكم أهل الأرض ، الذى أخذ الحكمة من الله نفسه (١مل ٣ : ١٢) ، الذى تراءى له الله مرتين (١مل ٣ : ٥ ، ٩ : ٢) . يقول عنه الكتاب « وكان فى زمان شيخوخة سليمان ، أن نساءه أملن قلبه وراء آلهة أخرى ... فذهب سليمان وراء عشتاروت إلهة الصيدونيين وملكوم رجس العمونيين » (١مل ١١ : ٤ ـ ٨) .","حقاً إنها لمأساة عجيبة وخطيرة ، ترينا مدى قوة الشيطان .",{h:"ومن دلائل قوة الشيطان ما سيفعله فى آخر الأيام ."},"وذلك عندما « يُحل من سجنه » ، ويخرج ليضل الأمم الذين فى أربع زوايا الأرض (رؤ ٢٠ : ٧) . بل يضل لو أمكن المختارين أيضاً عن طريق من يرسلهم من مسحاء كذبة وأنبياء كذبة ، يعطون آيات عظيمة وعجائب (متى ٢٤ : ٢٤) . ومن خطورة عمله العنيف فى تلك الفترة الصعبة قول الرب عنها :",{h:"ولو لم تقصّر تلك الأيام ، لم يخلص جسد » (متى ٢٤ : ٢٢) ، « ولكن لأجل المختارين تقصر تلك الأيام » . وفى تلك الأيام سيرسل الشيطان أيضاً من عنده ضد"}],18:["المسيح ، إنسان الخطية المقاوم والمرتفع على كل ما يدعى إلهاً « الذى مجيئه بعمل الشيطان ، بكل قوة و بآيات وعجائب كاذبة ، وبكل خديعة الإثم فى الهالكين » (٢تس ٢ : ٩ ، ١٠) .",{h:"ومن نتائج قوة الشيطان هذه ، يحدث الإرتداد العام ."},"وذلك قبيل مجىء المسيح (٢تس ٢ : ٣) . ولكن نشكر الله الذى سيقصر تلك الأيام الصعبة . وسيبيد هذا الأثيم (ضد المسيح) بنفخة فه ، ويبطله بظهور مجيئه (٢تس ٢ : ٨) ... إلى هذا الحد وصلت قوة الشيطان .",{h:"ومن أمثلة قوة الشيطان أيضاً :"},"إنه استطاع أن يتكلم على فم رسول عظيم كبطرس ، فانتهره الرب قائلاً « إذهب عنى يا شيطان . أنت معثرة لى » (متى ١٦ : ٢٢ ، ٢٣) .","ومن أمثلة ذلك أيضاً أنه غربل الإثنى عشر رسولاً . وقد طلب الرب من أجل بطرس لكى لا يفنى إيمانه (لو ٢٢ : ٢١ ، ٣٢) .","ومن أمثلة قوته أنه أسقط جبابرة مثل داود وشمشون ، وأهلك نبياً كبلعام ، وضيع تلميذاً من تلاميذ بولس كديماس ... « وكل قتلاه أقوياء » (أم ٧ : ٢٦) . حقاً كما قال داود النبى « كيف سقط الجبابرة ، و بادت آلات الحرب » (٢صم ١ : ٢٧) .",{h:"ومن أمثلة قوته أيضاً صرعه لأناس كثيرين ."},"هؤلاء الذين احتاجوا أن يخرج الشيطان منهم ، وقيل إنه كانت عليهم أرواح نجسة . وعنهم قال الرب لتلاميذه « إخرجوا شياطين » (متى ١٠ : ٨) . وكان على واحد من المرضى فرقة من الشياطين « لجئون » (مر ٥ : ٩) ، « ولم يقدر أحد أن يذلله » . وبعض هذه الشياطين لم يقدر تلاميذ الرب وقتذاك على إخراجها . فقال لهم الرب « هذا الجنس لا يمكن أن يخرج بشىء إلا بالصلاة والصوم » (مر ٩ : ٢٩) .",{h:"ولعله بسبب قوة الشيطان ، قيده الله ألف سنة ."},"« وطرحه فى الهاوية ، وأغلق عليه وختم عليه ، لكى لا يضل الأمم فى ما بعد ، حتى تتم الألف سنة . وبعد ذلك لا بد أن يُحلّ زماناً يسيراً » (رؤ ٢٠ : ٢ ، ٣) .",{h:"ولكن ليس معنى الحديث عن قوة الشيطان ، أن تخافوا منه !! كلا ."}],19:[{h:"فإن كان الشيطان قوياً ، فالله أقوى منه ..."},"وليس فقط أن الله أخضعه لنا ، بل إن كثيراً من الآباء قد غلبوه ، وكان يخاف منهم . وسنتحدث عن هذه النقطة فى حينها بمشيئة الرب .","نقطة أخرى مهمة فى صفات الشيطان كمحارب لنا ، وهى أنه :",{h:"٣ ـ خبير بالحروب وبنا"},"تصوروا الشيطان يحارب الإنسان منذ أكثر من سبعة آلاف سنة ، منذ آدم ... أية خبرة تكون له فى حربه مع البشرية . لا شك أنه أقدر مخلوق على فهم النفس البشرية وطريقة محاربتها . لقد درس النفس البشرية جيداً ، ويعرف نواحى القوة والضعف فيها . و يعرف الأسلوب الذى يمكنه أن يحاربها به .",{h:"أكبر عالم نفسانى ، وأكبر محلل نفسانى ، هو الشيطان ..."},"علم النفس عنده ، ليس مجرد نظريات ، إنما هو خبرات ، على المستوى العملى والعلمى أيضاً ، وبنطاق واسع جداً ، شمل البشرية كلها . لذلك هو يعرف متى يحارب ، وكيف يحارب ؟ ومتى ينتظر ؟ ومن أى الأبواب يدخل إلى الفكر أو إلى القلب ... ؟","من صفات الشيطان الأخرى التى تظهر فى حروبه أنه :",{h:"٤ ـ ذكى وصاحب حيلة"},"لقب الشيطان بأنه « الحية القديمة » (رؤ ٢٠ : ٢ ، ١٢ : ٩) . وقال الكتاب عن الحية إنها كانت « أحيل حيوانات البرية » (تك ٣ : ١) . إنه ذكى وحكيم فى الشر . وقد قال الكتاب « كونوا حكماء كالحيات » (متى ١٠ : ١٦) . وحكمة الشيطان كلها خبث ومكر وحيلة ...","ومن مظاهر ذكاء الشيطان أنه قد يغير خطته وأساليبه لتوافق الظروف . ومن حيله الصعبة : الكذب والخداع والأضاليل ، يسبكها بطريقة ذكية لا يشعر بها الإنسان المحارب ، أو أنه يقدم الخطية فى أسلوب فضيلة ... الخ . ما أكثر حيل الشيطان . إننا سنفرد"],20:["لها فصلاً خاصاً فى هذا الكتاب ، قد يكون الفصل الأساسى فيه .","ومن الصفات البارزة فى حروب الشيطان أنه :",{h:"٥ ـ كذاب"},"لقد كذب على أبوينا آدم وحواء حينما قال لها « لن تموتا » وكذلك فى قوله لها « تصيران مثل الله ... » (تك ٣ : ٤ ، ٥) . وصفة كذاب بارزة فى الشيطان ، لذلك قال عنه السيد الرب إنه « كذاب وأبو الكذاب » (يو ٨ : ٤٤) . قال هذا لكى لا نصدق كل ما يقوله الشيطان ، ولا ننخدع به . وليس الكذب عند الشيطان هو فقط ما يقوله من كلمات ، وإنما هناك ما هو أخطر بكثير من كل هذا :",{h:"هناك من يرسلهم من أنبياء كذبة ومسحاء كذبة ..."},"ولقد حذرنا الرب من كل هؤلاء ، فقال « إن قال لكم أحد هوذا المسيح هنا أو هناك فلا تصدقوا . لأنه سيقوم مسحاء كذبة وأنبياء كذبة ، و يعطون آيات عظيمة وعجائب حتى يضلوا لو أمكن المختارين أيضاً » (متى ٢٤ : ٢٣ ، ٢٤) . وطبعاً سيمطون تلك الآيات والعجائب من الشيطان ، كما قيل عن المقاوم ضد المسيح « الذى مجيئه بعمل الشيطان بكل قوة وبآيات وعجائب كاذبة » (٢تس ٢ : ٩) .",{h:"ومن أمثلة ذلك تكلم الشيطان من أفواه الأنبياء الكذبة :"},"قوله عن إغواء آخاب الملك ليهلك « أنا أغويه ... وأكون روح كذب فى أفواه جميع أنبيائه » (١مل ٢٢ : ٢٢) . فكما أن الروح القدس هو الناطق فى أفواه الأنبياء القديسين ، كذلك الشيطان هو الناطق فى أفواه الأنبياء الكذبة .",{h:"كذلك يعلن الشيطان كذبه فى الأحلام والرؤى الكاذبة ..."},"وما أكثر الحروب التى تعرض لها الآباء الرهبان ، ووردت فى بستان الرهبان ، عن هذه الأحلام والرؤى الكاذبة . ومن أمثلتها ظهور الشيطان لأب راهب وقوله له « أنا الملاك غبر يال ، أرسلنى الرب إليك » فأجابه الراهب فى اتضاع « إننى إنسان خاطىء ، لا أستحق أن يظهر لى ملاك . فلعلك أرسلت إلى غيرى وأخطأت الطريق » . وظهر كذب الشيطان ، فمضى واختفى عنه ."],21:["أو كمثال آخر قصة الشيطان الذى ظهر لراهب وقال له « أنا المسيح ، فاسجد لى » . فقال الراهب فى قلبه « أنا فى كل يوم أسجد لسيدى المسيح . فلماذا يطلب هذا منى السجود » . وهكذا كشف حيلة وكذب الشيطان ، وانتهره فمضى .","وما أكثر الأحلام الكاذبة التى يضل بها الناس ظانين أنها من الله ! وقد قال القديس بولس الرسول عن الرؤى الكاذبة التى من الشيطان :","« لأن الشيطان نفسه يغيّر شكله إلى شبه ملاك نور » (٢كو ١١ : ١٤) .","وفى قصة الأنبا غاليون السائح ظهرت له الشياطين بهيئة آباء سواح يريدون ضمه إليهم . ولم يكتشف أنهم شياطين ، إلا بعد أن أتاهوه فى البرية ، ثم سخروا به وتركوه هازئين به ، إلا أن رحمة الرب أدركته من أجل نسكه ، و ببساطة قلبه ، وماضى تعبه ...",{h:"وكذب الشيطان يظهر أيضاً فى أقوال السحرة والعرافين وأمثالهم ."},"ولذلك أوصى الرب قائلاً « لا تتعلم أن تفعل مثل رجس أولئك الأمم . لا يوجد فيك من يجيز إبنه أو إبنته فى النار ، ولا من يعرف عرافه ... ولا ساحر ، ولا من يرق رقية ، ولا من يسأل جاناً أو تابعة ، ولا من يستشير الموتى . لأن كل من يفعل ذلك مكروه عند الرب . و بسبب هذه الأرجاس ، الرب إلهك طاردهم من أمامك » (تث ١٨ : ٩ ـ ١٢) . ولعل هذه الآية تكشف لنا شيئاً آخر هو :",{h:"كذب الشيطان فى استشارة الموتى ، أو فى ( تحضير الأرواح ) ."},"فقد ينطق فى أمثال هذه الجلسات ، مدعياً أنه روح فلان من الناس . ويقول للحاضرين بعض معلومات تخدعهم مما يعرفه عن أخبار ذلك الشخص أو أسرته . فإذا صدقوه ، يبدأ بالتدريج يقول لهم ما يضلهم ... وكل هذا من كذب وادعاء الشيطان ليضل الناس ...",{h:"ولعل من كذبه أيضاً ، ما يقوله على أفواه المنجمين ومدعى معرفة الغيب ..."},"سواء عن طريق التنجيم ، أو قراءة الكف ، أو ضرب الرمل ، أو قراءة فنجان القهوة ، أو معرفة البخت والطالع بأنواع وطرق شتى ...","وواضح لاهوتياً أنه لا يعرف الغيب سوى الله وحده . فمن يدعى معرفة الغيب ، لا يكون صادقاً فيما يدعيه ..."],22:[{h:"وإغراءات الشيطان كلها ألوان من الكذب ..."},"حيث يصور للإنسان سعادة تأتيه من وراء الخطية ، سواء فى لذة أو سلطة أو مكسب أو جاه أو مجد ... وبعد أن يسقط الشخص يجد أن كل إغراءات الشيطان هى سراب زائل ، وأنها أشياء زائفة ، كما صور لحواء وآدم أنها سيصيران مثل الله ... وكما صور لسليمان أنه سيسعد بكثرة ألوان المتعة والترف التى تحيط به ، فوجد أن الكل باطل وقبض الريح (جا ٢) .","ولكن هذا أسلوب الشيطان دائماً ، يزخرف طريق الخطية ، و يضفى عليه أوصافاً من الجمال تغرى من يسقط فى حبائله . وتكون كل زخارفه أكاذيب يخفى بها بشاعة الخطية ونتائجها السيئة ...",{h:"أيضاً أحلام اليقظة التى يقدمها لضحاياه ، كلها أكاذيب ..."},"ولكنه يقدمها لهم كنوع من اللذة تخدرهم عن العمل الإيجابى النافع ، فيعيشون بهذه الأحلام فى خيال غير واقعى ، يبنون قصوراً من رمال ، وأمجاداً وأفراحاً ومتعاً . ثم يستيقظون فلا يجدون شيئاً . و يكون الشيطان بهذا الكذب قد أضاع وقتهم ، وعطلهم عن العمل المجدى ، وأراحهم راحة كاذبة .",{h:"ومن أكاذيب الشيطان إيهامه المنتحر أن الموت سيريحه من متاعبه ."},"و يظل يركز على هذه النقطة : إنه لا فائدة من هذه الحياة ، ولا حل لمشاكله . والحل الوحيد هو الموت ، حيث يتخلص من كل تعبه و يستريح . وإذ يصدقه المنتحر و يقتل نفسه ، لا يجد هذه الراحة ، بل يجد نفسه فى الجحيم ، فى تعب وألم لا نجاة منه ، ولا تقاس به كل متاعب الدنيا . و يجد أن الموت ليس هو نهاية لحياته المتعبة ، بل هو بداية لحياة أكثر تعباً . و يكون الشيطان بهذا الكذب قد خدعه وضلله وأضاعه ...",{h:"ونقريباً غالبية الخطايا ، يضع الشيطان وراءها أكذوبة من أكاذيبه ."},"فهو يوحى للسارق بأن لا أحد سوف يرى أو يكتشف سرقته ، وكذلك يوحى للمهرب وللمرتشى وللغشاش . والشيطان فى كل هذا يكذب ، لأنه حتى إن لم ير البشر ، فالله يرى وكل شىء مكشوف أمامه . وهو يوحى للقاتل بأن المقتول يستحق القتل ، وحياته خطأ يجب تصحيحه ، أو أن القتل غسل للعار الذى يلوث شرفه ، أو أن قتله يريح نفس قريب له قد مات ..."],23:["بل لعل الإلحاد هو أكبر أكذوبة قدمها الشيطان للبشرية . وقد كذب على الوجوديين حينما صور لهم أن وجود الله يعطل وجودهم ، كما كذب على الماركسيين إذ صور لهم أن الله يعيش فى برج عالٍ ولا يهتم بالمجتمع الإنسانى ، بل يترك فيه الظالم يظلم ، والغنى يستعبد الفقير... !!","من صفات الشيطان أيضاً فى حروبه أنه :",{h:"٦ ـ لحوح"},"أى أنه كثير الإلحاح جداً ، لا يملّ . وربما الفكر الواحد يظل يعرضه مرات ومرات . ومهما رفضه الناس ، يستمر أيضاً فى عرضه .",{h:"ربما من كثرة الضغط المستمر والإلحاح ، يستسلم الإنسان له ويخضع ."},"لقد قيل فى بستان الرهبان إن الشيطان ظل يحارب راهباً بخطية واحدة مدى خمسين عاماً ، لا يهدأ ، ولا ييأس ، ولا يملّ ...","وحتى فى حربه مع السيد المسيح ، لم يهدأ بعد فشله فى التجربة الأولى والثانية والثالثة . ولما انتهره الرب ومضى قال القديس لوقا الإنجيلى عن ذلك « ولما أكمل إبليس كل تجربة ، فارقه إلى حين » (لو ٤ : ١٣) . وعبارة « إلى حين » تعنى أنه رجع إلى تجربته مرة أخرى أو مراراً عديدة .",{h:"الشيطان لا ييأس من الفشل أبداً ، ولا يخجل ، بل يعود !"},"لما فشل فى التجربة الأولى مع أيوب ، رجع مرة أخرى يطلب تجربته بأسلوب أصعب ... ولما فشل مع السيد المسيح فى كل التجارب ، أتاه وهو على الصليب يقول له « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{h:"والشيطان فى إلحاحه على إسقاط الناس لا يعترف بعقبات ."},"لا يهمه أن آدم وحواء خلقا على صورة الله ومثاله (تك ١) .","ولا يهمه أن داود مسيح الرب ، ولا أن سليمان هو أحكم أهل الأرض كلها ، ولا أن بطرس رسول متحمس جداً للمسيح . ولا يهمه أن يهوشع هو الكاهن العظيم (زك ٣) ، ولا أن هارون هو رئيس الكهنة (خر ٣٢) . ولا أن شمشون هو نذير الرب « وأن روح الرب"],24:["يحركه » (قض ١٣) ... لا يهمه مراكز الناس ولا روحياتهم ... بل يضرب ضربته ، وليحدث بعد ذلك ما يحدث ... إن كان قد تجرأ أن يجرب المسيح له المجد ، فهل يهتم بالبشر ؟!",{h:"إنه يلقى سمومه كل حين على كل أحد . وربما الذى لا يهلك بها اليوم ، قد يهلك بها غداً ، أو بعد سنة ، أو بعد عشرين ... !"},"إن الشيطان مثابر ، نشيط ، لحوح ، دائب على العمل ، لا يثبط الفشل همته . ولا ييأس من علو قدر الناس فى الروحيات . هو ماض فى خطته لتحطيم الملكوت ، ولكى يضل حتى المختارين أيضاً ... والذى لا يستطيع أن يدنس جسده ، فعلى الأقل يدنس فكره . والذى لا يقبل طعنه فى روحياته ، على الأقل يلطمه بشوكة فى الجسد (٢كو ١٢ : ٧) . وإن لم يستطع أن يسقط أولاد الله ، فعلى الأقل يشتكى عليهم . لذلك قيل إنه :",{h:"٧ ـ المشتكى"},"وقد قال عنه سفر الرؤيا إنه « المشتكى على أخوتنا ، الذى كان يشتكى عليهم أمام إلهنا نهاراً وليلاً » (رؤ ١٢ : ١٠) .",{h:"إنه يشتكى على القديسين ، مدعياً أنه لم يأخذ فرصته لمحاربتهم ! ... أو أن فرصته التى أخذها قبلاً ، لم تكن كافية !"},"وقد وقف فى القديم يشتكى على أيوب أمام الله ، مدعياً أنه لم يأخذ فرصة لمحاربته . وقال لله « أليس إنك سيجت حوله ... باركت أعمال يديه ... ولكن إبسط الآن يدك ومس كل ماله ، فإنه فى وجهك يجدف عليك » (أى ١ : ١٠ ، ١١) .","ومع أن الله واجه الشيطان بقسوته وظلمه فى شكواه ، وقال له عن أيوب « إلى الآن هو متمسك بكماله . وقد هيجتنى عليه لأبتلعه بلا سبب » (أى ٢ : ٣) ، إلا أن الشيطان استمر فى شكواه للمرة الثانية ، وطلب فرصة أوسع ، وأخذ سماحاً لضرب أيوب فى جسده بقرح ردىء (أى ٢ : ٧) ...","عجيب أن الشيطان يفعل كل ما يريد ، و يظل يشكو !","وهو يشكو على الرغم من مواهبه العديدة ، فهو :"],25:[{h:"٨ ـ كثير المواهب"},"إنه كثير القدرات إلى حد بعيد . يعرف أشياء كثيرة و يتقنها .",{h:"فالمواهب التى منحت له وهو ملاك ، لم يسحبها الله منه ..."},"معرفته واسعة جداً فى كل مجال . حتى آيات الكتاب المقدس ، يعرفها جيداً ويحارب بها ، وكأنه من اللاهوتيين . وفى التجربة على الجبل ، إستخدم الكتاب المقدس بطريقته الخاصة (متى ٤ : ٦) . بل إنه هو صاحب جميع البدع والهرطقات ، وهو الذى وضع أفكارها فى أذهان المراطقة ، وقدم لهم مفاهيم خاطئة لآيات الكتاب . وصدق القديس أثناسيوس الرسول حينما قال : إن عدونا ليس هو الأريوسيين ، إنما هو الشيطان .","والشيطان يعرف الشعر . بل إن كثيراً من الشعراء يتحدثون عن شيطان الشعر ، وأنه ملهمهم أفكارهم ... لذلك ليس غريباً إن قال أحد علماء الأرواح ، إنه استحضر روح شاعر مشهور وسمع منه قصيدة بنفس أسلوبه ... ليس غريباً أن يكون الشيطان قد تدخل ، وأملى الوسيط شعراً بنفس الأسلوب !",{h:"والشيطان يعرف الموسيق والفن والنحت والرسم والأغانى ."},"ويمكنه أن يلهم المشتغلين بالملاهى كل ما يحتاجونه فى فنونهم لإغراء الناس وإسقاطهم ، أو إبعادهم بها عن عملهم الروحى .",{h:"والشيطان من علماء النفس البارزين ، بل هو فى مقدمتهم جميعاً ، بسبب خبرته العملية . وهذه الخبرة تساعده فى حروبه . كما أن حروبه أيضاً تزيد من خبرته ومن علمه . وكما أنه من علماء النفس ، هو أيضاً من علماء الأرواح ، لأنه روح ، يعرف ما للروح أكثر مما يعرف البشر ."},{h:"غير أن علم الشيطان يسير وفق أغراضه ."},"فالعلم الخالص شىء ، واستخدام هذا العلم لتحقيق غرض هو شىء آخر . وغرض الشيطان معروف وهو مقاومة الله وملكوته . لذلك هو يستخدم كل معارفه لتحقيق هذا الهدف الشيطانى .","ومن صفات الشيطان فى حروبه مع الإنسان ، أنه :"],26:[{h:"٩ ـ قاس"},"إنه يعمل بكل قسوة ، بلا رحمة . وقسوته واضحة جداً فى قصة أيوب الصديق . كما أنه جرّ كثيرين إلى الهلاك وأضاعهم ، كالذين هلكوا بالطوفان ، وبنار سادوم ، والذين ابتلعتهم الأرض أحياء (عد ١٦) .","وقسوته واضحة فى الذين يصرعهم ، و يصبحون فى حالة جنون بسببه . ومثال ذلك مجنون كورة الجدريين الذى « كان فيه شياطين ... وكان لا يلبس ثوباً ، ولا يقيم فى بيت بل فى القبور ... وقد ربط بسلاسل وقيود محروساً . وكان يقطع الربط و يساق من الشيطان إلى البرارى » (لو ٨ : ٢٦ ـ ٢٩) ، « وكان يصيح ويجرح نفسه بالحجارة » (مر ٥ : ٥) . وأمثلة هذا المصروع كثيرون ...",{h:"وتظهر قسوته كذلك فى محارباته للقديسين ، وفى المناظر المخيفة ."},"ففى حربه مع القديس أنطونيوس الكبير كان يظهر له فى مناظر مفزعة جداً ، وأحياناً فى هيئة وحوش مخيفة تصيح حوله بأصوات مرعبة . وفى إحدى المرات ضرب القديس بضربات شديدة مؤلمة للغاية ، وتركه بين حى وميت ... والذى يقرأ سيرة القديس قرياقوس السائح ، يجد أمثلة أخرى تشبه هذا النوع أو أشد ...",{h:"وهو قاس فيما يثيره على العالم من حروب وويلات وجرائم ."},"ومعروف جداً نتائج كل هذه ... ولكن الشيطان يفرح بكل ويلات العالم ، ويحسب ذلك انتصاراً له ، إلى جوار تحطيمه للنفوس وللعقول ، وبثه للخصومات وأسباب الإنشقاق والتمزق . فهو عامل تخريب لا يهدأ ، بكل عنف . وهو سعيد بتخريبه .","صدقونى ، إننا لو قرأنا عن قسوة الشيطان فى حروبه المفزعة للقديسين ، نقول عن أنفسنا إننا لم نُحارب أبداً من الشيطان . فحروبنا الحالية شىء تافه إلى جوار حروبهم ... والعجيب أنه فى كل قسوة الشيطان ، يتظاهر بالعطف أحياناً ، ولكنه :",{h:"١٠ ـ خبيث فى تظاهره بالعطف"},"عبارات العطف عنده وسيلة ماكرة لإسقاط الناس ..."],27:["فهو (يعطف) عليك حينما تصوم ، و يدعوك إلى الأكل ، من أجل صحتك ! محذراً إياك من المرض ومن الضعف ! و يقول لك إحذر من أن تقتل جسدك ، فهو وزنة تمجد بها الله . وقد قال الرسول « إنه لم يبغض أحد جسده قط بل يقوته و يربيه » (أف ٥ : ٢٩) .","وهو يعطف عليك حينما تنشط روحياً ، وتسهر فى الصلاة والقراءة والمطانيات ، و يدعوك فى عطف إلى النوم من أجل راحتك .",{h:"وهو (عطوف) يخشى عليك من (التطرف) فيدعوك إلى الإقلال من الجهاد ."},"وفى عمق عملك الروحى ، يقول لك : لا داعى لكل هذا ، فإن الآباء يعلموننا أن الطريق الوسطى خلصت كثيرين ... وهكذا يقول لك : إحترس من التطرف ، لئلا الشيطان يضربك ضربة يمين وهى أقسى ، ولئلا تقع فى المجد الباطل وهو شر الرذائل كلها . بل يقول لك : لا شك أن تطرفك هذا فى الجهاد هو من عمل الشيطان ، وهو لا يقصد بك خيراً ! فاستمع لقول الكتاب « لا تكن باراً بزيادة ... لماذا تخرب نفسك ؟ » (جا ٧ : ١٦) .",{h:"والشيطان (العطوف) يشفق عليك من البكاء على خطاياك ..."},"يقول لك : لماذا تبكى وتحيا فى الكآبة . ليس هذا هو طريق الله ... أليس أن خطاياك قد غُفرت ، ومحاها الرب بدمه ؟! لماذا تبكى عليها إذن ؟! أتريد أن تظل فى البكاء حتى تتلف أعصابك ونفسيتك ، وحتى تنكشف أمام الناس ؟! أليس أن الكتاب يقول « إفرحوا فى الرب كل حين » (فى ٤ : ٤) ... و يظل بك حتى تفقد إنسحاق القلب ، وتفقد دموع التوبة ، وتفتر حرارتك ... وإذ تفعل هذا ، تسهل عليك الخطية وربما تعود إليها . وطبعاً ينسيك قول الكتاب « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) .",{h:"والشيطان (العطوف) يبرر لك أخطاءك ، حتى لا تتعبك ضميرك ."},"إنه يمنع عنك التبكيت ، حرصاً على مشاعرك ! وإشفاقاً عليك من الحزن ومن اليأس ! ولذلك فى كل أخطائك يقدم لك العديد من الأعذار ومن التبريرات ، و ينصحك قائلاً : لا تقل على كل شىء إنه خطأ ، ولا تبالغ فى تبكيت نفسك ، لئلا يقودك هذا إلى الوسوسة .... حقاً إن هذا خطأ ، ولكنك لم تكن تقصد ، ونيتك طيبة ، وهى تشفع لك . والله ينظر إلى النيات .... وهذا خطأ ، ولكن ماذا كان بإمكانك أن تفعل ؟! الظروف"],28:["كانت ضاغطة . وصدقنى لو أنا فى موضعك ما كنت أستطيع أن أفعل غير هذا . والله لا يطلب منك فوق طاقتك . لذلك لا تكتئب ...","وبتبرير أخطائك ، تجعل ضميرك واسعاً يبلع الجمل ، و يبعدك عن التوبة وعن الحرص والتدقيق ، وعن الأمانة فى القليل ...","إن (العطف) عند الشيطان ليس حباً ، إنما وسيلة للإسقاط . فاحترس منه ، ولا تسمع له . وكن حازماً مع نفسك . واسلك بتدقيق ... وتأكد أن الشيطان فى كل حروبه معك يكون غير مخلص . كل نصائحه غير مخلصة ، حتى لو كانت بمظهر الخير . إنه لا يريد سوى ضياعك .","من صفات الشيطان أيضاً أنه حسود .",{h:"١١ ـ حسود"},"قلبه لا يستريح مطلقاً أن يرى إنساناً ناجحاً ، أو إنساناً باراً ، فيعمل كل ما يستطيعه لإسقاط هذا وذاك .",{h:"وفى حسده يضرب ضرباته بلا رحمة ..."},"لقد حسد يوسف الصديق على ما رآه من رؤى ، فنقل الحسد إلى قلوب أخوة يوسف حتى باعوه كعبد . ثم حسده على نجاحه وثقة فوطيفار به ، فدبر له حيلة ألقاه بها فى السجن كفاعل إثم ...","وحسد العالم على إيمانه بالله ، فألقاه فى الوثنية ، وفى تعدد الآلهة وفى الإلحاد . ودبر لذلك كل صنوف الفكر والفلسفة ، وأيضاً العبادات البدائية . وصدق المزمور حينما قال « لأن كل آلهة الأمم شياطين » (مز ٩٦ : ٥) .",{h:"والشيطان يحسد المعرفة والحكمة ، ويحسد العفة ، ويحسد الإتضاع ..."},"لذلك فهو ينشر فى العالم الجهل والزنا والكبرياء ، بكل ما عنده من حق . لقد حوّل سليمان عن حكمته وأسقطه . وألقى فى العالم كثيراً من المعارف الخاطئة ، حتى « قال الجاهل فى قلبه ليس إله » (مز ١٤ : ١) . وأصبح الزنا من الحروب الخطيرة"],29:["التى تحارب العالم كله . كما صارت الكبرياء حرباً يقع فيها من لم يقع فى باقى الخطايا ومن يقع فيها أيضاً .",{h:"إن حسد الشيطان هو حسد مدمّر ، وليس مجرد مشاعر ."},"فهو إذ يحسد ، يضرب بكل قوة . كما حسد أيوب على كماله ، فضربه بكل قسوة ، واشتكاه أمام الله . وكما حسد سكان البرارى على زهدهم ونسكهم فأثار ضدهم أعنف الحروب . وكما حسد أوريجانوس أعلم أهل عصره وأستاذ اللاهوت الأول فى عصره ، فألقاه فى كثير من البدع حرمته من أجلها الكنيسة ، حتى قيل عنه « أيها البرج العالى ، كيف سقطت ؟! » ...",{h:"لذلك فى كل ما تعمله من بر ، توقع حسد الشياطين ."},"وتوقع أنهم لا يبقونك مطلقاً فى برك ، بل يحاولون إسقاطك بشتى السبل . فإن ضربوك ضربة فى يوم روحى عميق ، لا تيأس بل قل : هذا ما كنت أتوقعه . ولكنى أطلب من رحمة الله أن تعيننى حتى لا أسقط ثانية .",{h:"وإن منحك الله موهبة ، فنوقع أيضاً حسد الشياطين ."},"فهم إما أن يحاولوا إسقاطك فى الكبرياء ، أو استخدام الموهبة فى غير موضعها . وبهذا يكونون قد أضاعوا هدفها الروحى ونفعها لك ولغيرك ...","من صفات الشيطان الأخرى أنه :",{h:"١٢ ـ نهاز للفرص"},"الشيطان يحاول أن يستغل الفرص ، ليلقى فيها تجاربه . كما استغل جوع السيد المسيح بعد صوم أربعين يوماً ، لكى يجربه بتجربة الخبز .","وكما انتهز فرصة خوف بطرس ليلقيه فى إنكار المسيح .","وانتهز أيضاً فرصة تمسك اليهود بالسبت ليجعلهم ينكرون معجزات للمسيح لم يعملها أحد من قبل ، بل يتهمونه بالخطية (يو ٩ ، ١١) .","من صفات الشيطان أيضاً أنه :"],30:[{h:"١٣ ـ غير مخلص وغير أمين"},"قلنا قبلاً إن الشيطان قد يأخذ موقف الشفوق على صحتك ، سواء من جهة الصوم أو السهر ، أو تعب الجسد جملةً . و ينصحك فى ذلك بالراحة الجسدية ، حرصاً على سلامة صحتك ... !",{h:"ولكنه ليس أميناً حقاً من جهة إهتمامه بصحة جسدك ."},"إنه ينصحك بالراحة ، ويمنعك من السهر ، إن كان سهرك فى الصلاة أو التأمل ، أو القراءة الروحية ، أو فى ليالى الصلاة . ولكنك إن سهرت فى اللهو أو فى وسائل الترفيه المتنوعة ، فلا يحدثك عن مضار السهر خوفاً على صحتك !",{h:"وإن تعبت فى أمور العالم الباطلة ، لا ينصحك بالراحة ..."},"إن تعبك فى جمع المال ، وفى الجرى وراء السهر والجاه ، وفى السعى وراء ملاذك ومتعك ، وفى تنظيم الحفلات الصاخبة ، وفى اللعب والرياضة ، وفى كافة الأنشطة العالمية ... كل هذا لا يثير إشفاقه عليك ، ولا يدعوك فيه إلى الراحة ... !","إنما ينصحك بالراحة ، إن كان تعبك فى أى عمل روحى . جهادك الروحى فقط هو الذى يثير إشفاقه عليك وعلى صحتك ؟",{h:"لذلك إن دعاك إلى الراحة وقت جهادك الروحى ، فلا تطعه ."},"إنها فى حقيقتها دعوة منه إلى الكسل والتراخى ... أما أولاد الله ، فكانوا يفرحون بالتعب ، بل و يفتخرون به (١كو ١٥ : ١٠) . وكما قال القديس بولس الرسول « فى الأتعاب أكثر ... فى تعب وكد . فى أسهار مراراً كثيرة » (٢كو ١١ : ٢٣ ، ٢٧) . وقال أيضاً « كل واحد سيأخذ أجرته بحسب تعبه » (١كو ٣ : ٨) .",{h:"إن عرفت هذا ، إتعب من أجل الله ، على قدر طاقتك ."},"واعلم أن نصيحة الشيطان لك بالراحة ، نصيحة غير مخلصة ، وغير أمينة ، وغير صادقة . لقد تعب القديس الأنبا بولا الطموهى فى النسك ، إلى أن ظهر له ربنا يسوع المسيح وقال له « كفاك تعباً يا حبيبى بولا » . فرد عليه القديس « وماذا يكون تعبى هذا ، إلى جوار كل تعبك يارب لأجل خلاصنا ؟! » ."],31:[{h:"خير لك أن تتعب ههنا على الأرض ، لتنال أكاليل الجهاد ."},"من أن تستريح ههنا على الأرض ، وتتعب هناك فى الأبدية ...","واعلم أن تعبك هنا ليس منسياً أمام الله ، لأنه « ليس بظالم حتى ينسى تعب المحبة » (عب ٦ : ١٠) . وكل تعب تتعبه ههنا ، مكنوز لك هناك فى الأبدية .",{h:"ليس ههنا مكان الراحة . إنما هنا مكان الجهاد والتعب ."},"لذلك حينما يموت إنسان ، يقولون إنه تنيح أى استراح ...","فالشيطان ليس أميناً فى دعوتك إلى الراحة . إنه يخدعك ...",{h:"إنه يحدثك عن الصحة وقت النسك ، وليس وقت الفساد !"},"إن صمت ، يلبس الشيطان ملابس الأطباء ، و يلقى محاضرة مستفيضة عن أهمية البروتين الحيوانى والأحماض الأمينية الأساسية . و يظهر إهتمامه بجسدك وسلامته .","ولكنه لا يتحدث عن سلامة جسدك إذا داومت على التدخين أو المسكرات ، أو الشهوات الشبابية الضارة بالصحة . إنه ليس مخلصاً فى دعوتك إلى الصحة .",{h:"لذلك إن حاربك براحة الجسد وصحته ، فقل : ليس هذا وقته ."},{h:"إن كانت حرب الراحة من الشيطان ، فإن حرب الكسل أشد ."},"إننا حينما نتعب بالجسد ، نشعر براحة نفسية . والعكس صحيح .","حينما نكمل واجباتنا نشعر براحة وفرح ، مهما تعبنا بالجسد . وانتصارنا على جسدنا فى الصوم والسهر والمطانيات والعفة ، يعطينا راحة لا توصف ."],32:[{h:"الفصل الثالث"},{h:"حيل الشيطان"},"« نجنا من حيل المضاد ... » ،","« وإبطل سائر فخاخه المنصوبة لنا » .","( تحليل صلاة الغروب )"],33:["ما أكثر حيل الشياطين ! إنها لا تنتهى . إن لم تصلح حيلة منها ، يستبدلها بغيرها ، وبثانية وثالثة ... إلى أن يصل إلى غرضه . وليست هناك خطة واحدة أمامه لتوصّله . بل هو يتخذ لكل وضع ما يراه مناسباً ، دون أن يتقيد بشىء ...","على أنه من أشهر خططه الواضحة المتكررة ، بضعة أساليب صارت معروفة ومحفوظة ، نذكر من بينها ما يأتى ...",{h:"١ ـ خطية تلبس ثوب الفضيلة"},{h:"ما أسهل أن يقدم لك الشيطان بعض الخطايا بأسماء غير أسمائها ، بأسلوب يسهل قبوله . بحيث تلبس الخطايا ثياب فضائل ..."},"وكما قال السيد الرب « يأتونكم فى ثياب الحملان وهم ذئاب خاطفة » (متى ٧ : ١٥) .","فالتهكم على الناس والإستهزاء بهم ، يقدمه على اعتبار أنه لطف وظرف ، ومحبة ودالة ، وخفة روح ، ومحاولة للترفيه ... !","والدهاء يسميه باسم الذكاء ... !","و يقدم لك القسوة فى معاملة أولادك أو إخوتك الصغار ، باسم التأديب والتربية والتقويم . ويجعل ضميرك يوبخك إن لم تؤدبهم .","والتزين غير اللائق والتبرج ، يقدمها لك باسم الأناقة والنظافة .",{h:"إن الشيطان لا يقدم الخطية مكشوفة ، لئلا يرفضها الإنسان ."},"بل يقدمها باسم آخر ، وهى هى ، ولا فارق ...","يقول إننى سأدخل مع ( فلان ) فى حرب مسميات ، وأسقطه فيما أريد ، ربما دون أن يشعر ... أو قد يشعر ولكن ضميره لا يبكته ."],34:["لو أننى قدمت له الرياء بهذا الإسم المنفر ، فلن يقبله . إذن ماذا أفعل ؟ سأجعله مثل القبور المبيضة من الخارج (متى ٢٣) ، بحيث يكون فى الداخل شيئاً ، وفى مظهره الخارجى عكس ذلك تماماً . ولكننى سأدعو الرياء باسم مقبول : أسميه عدم إعثار الآخرين ، أو أسميه القدوة الحسنة .","ليس من ( الحكمة ) أن يسمى الشيطان الخطية خطية ، فيكشف حينئذ أوراقه ، ولا يصل إلى هدفه !","يقول السيد الرب فى حديثه مع تلاميذه :",{h:"تأتى ساعة ... يظن فيها كل من يقتلكم ، أنه يقدم خدمة ( قرباناً ) لله !! (يو ١٦ : ٢) ."},"ويقيناً أن الشيطان قدم خطية القتل إلى هؤلاء ، باسم « الغيرة المقدسة » أو « الدفاع عن الدين » أو « الجهاد المقدس » أو « تطهير الأرض من الخطاة » . وربما كان هذا هو شعور الكتبة والفريسيين وشيوخ الشعب ، فى تقديمهم السيد المسيح للصلب .","إن الذين انتهروا الأطفال ومنعوهم من الذهاب إلى المسيح (لو ١٨ : ١٥) ، ما كانت هذه قسوة فى نظرهم ، أو عدم إهتمام بالصغار . إنما لبس هذا التصرف ثياب الحملان ، وتسمى باسم فضيلة ، ربما إسمها « حفظ النظام » أو « حفظ كرامة المعلم الصالح » .",{h:"والكذب يمكن أن يقدمه الشيطان تحت إسم « الحكمة » !"},"يقدمه كنوع من حسن التصرف ، أو إنقاذ المواقف . والطبيب قد يكذب على المريض مرات عديدة ، و يسميها أمام ضميره « حفظ معنويات المريض » ، وحمايته من الإنهيار ، لكى يشفى .","والبعض يسمى بعض أنواع الكذب باسم « الكذب الأبيض » . وربما يسميه فى أول أبريل باسم : الدعابة أو الفكاهة والتندر ، أو أى إسم مشابه .",{h:"وبهذا الشكل ، ما أسهل على الشيطان أن يسمى الرقص فناً !"},"و يسمى الصور العارية والماجنة فناً أيضاً . وكذلك التماثيل التى من نفس النوع . و يدخل تحت هذا الإسم كل ما فى السينا والمسرح من التمثيل مهما كان خاطئاً ... وكل"],35:["ما فى الغناء والموسيق ، مهما كان معثراً أو مثيراً ...","وتحت إسم الفن يخفى الشيطان مجموعة كبيرة من الخطايا والعثرات ، لا تستحق هذا الإسم الجميل !",{h:"إلباس الخطية ثوب الفضيلة ، هو حيلة ماكرة من حيل الشيطان ."},"أتراه يدعو البخل بخلاً ؟! ما كان أحد إذن يقبله . إنما الشيطان قد يسميه « حسن تدبير للمال » أو « حفظ المال لحاجة المستقبل » أو يسميه « عدم التبذير » أو « عدم الإسراف » . وإذا أراد الشيطان أن يمنع غنياً من أن يدفع للفقراء ، يقول له : ليس من الخير أن تعوّدهم الشحاذة ، أو أن تعودهم التشرد والتواكل . إن عدم إعطائهم هو حكمة ، وعين الحكمة ، لكى يبحثوا عن عمل ، ولكى يأكلوا من عرق جبينهم حسب وصية الرب الإله (تك ٣ : ١٩) .",{h:"إعطاء الخطية إسم فضيلة ، يجعل الناس يستمرون فيها ..."},"فليس فقط من جهة الماضى ، لا يتبكت الإنسان من ضميره . وإنما أيضاً من جهة المستقبل يستمر الخاطىء فيما هو فيه ، بهذا الخداع من الشيطان .",{h:"أتراه كان يطلق إسم هرطقة على أفكار أريوس ومقدونيوس وسابيليوس وأمثالهم ؟!"},"كلا ، بل كان يقنعهم أن هرطقاتهم هى الدفاع عن الإيمان السليم !! وكان يزوّدهم بالتفسير الخاطىء لآيات الكتاب ، لكى يقبلوا أفكاره ، ولكى يقنعوا أيضاً غيرهم بها ...","إحترس إذن من المسميات الخاطئة ، ولا تسمح للشيطان بأن يخدعك . فإن الخطية هى الخطية مهما اختفت وراء إسم آخر ...","كذلك إحترس من حرب أخرى يلجأ إليها الشيطان ، وهى :",{h:"٢ ـ تحطيم فضيلة لاكتساب غيرها"},"إن الشيطان يتضايق من فضائلك الثابتة التى صارت وكأنها من طبيعتك . لذلك يحاول أن يحطمها بكل حيلة . وليس أسهل من أن يقدم لك فضيلة أخرى جديدة ، إن"],36:["لم تسلك فيها بإفراز ـ لقلة الخبرة ـ تضيع الفضيلة الأولى الثابتة . ومثال ذلك :",{h:"أ ـ إنسان يحيا فى وداعة وهدوء وسكون وسلام قلبى ودماثة خلق ..."},"يريد الشيطان أن يفقده كل ما فيه من رقة ، ومن كلمة طيبة ، ومن تواضع قلب . فماذا يفعل ؟ إنه لا يستطيع طبعاً أن يذم له الوداعة ، أو أن يقول له : أترك طبعك هذا المحبوب من الكل ... ولكنه يصل إلى ذلك عن طريق الإحلال ... يقدم له فضيلة بديلة ، دون أن يقول له إنها بديلة ... وكيف ؟",{h:"يشرح له أولاً أهمية الآية القائلة « غيرة بيتك أكلتنى » ."},"وكيف أن داود المشهور بالوداعة (مز ١٣٢ : ١) هو الذى قالها . وكيف أن التلاميذ تذكروها حينما صنع السيد المسيح الوديع « سوطاً من حبال ، وطرد الباعة من الهيكل ، وطرد الغنم والبقر ، وكبّ دراهم الصيارف وقلب موائدهم » (يو ٢ : ١٥ ، ١٧) . وقال لهم مكتوب : بيتى بيت الصلاة يدعى ، وأنتم جعلتموه مغارة لصوص » (متى ٢١ : ١٣) .",{h:"ويدعوه إلى محاربة الأخطاء ، ويزوده بكل الآيات اللازمة ."},"يقول له إن السيد المسيح وبّخ الكتبة والفريسيين بشدة ، وقال لهم فى أصحاح كامل « ويل لكم أيها الكتبة والفريسيون المراءون » (متى ٢٣) ، وواجههم بكل أخطائهم . وقال لهم « أيها القادة العميان » أكثر من مرة . وقال لهم « إنكم تشبهون القبور المبيضة من الخارج » . وقال « هوذا بيتكم يترك لكم خراباً » (متى ٢٣ : ٣٨) . ويوحنا المعمدان قال موبخاً قادة اليهود فى أيامه « يا أولاد الأفاعى . من أراكم أن تهربوا من الغضب الآتى ... » (متى ٣ : ٧) .","ثم يقول له : إسمع قول القديس بولس الرسول . إنه أمر :",{h:"يأمرك قائلاً « وبّخ . إنتهر . عظ » (٢تى ٤ : ٢) ."},"ولا يكمل له الآية « بكل أناة وتعليم » . ولا يقول له إنها موجهة إلى القديس تيموثاوس الأسقف (أسقف أفسس) ، وليس لكل أحد . ولا يشرح له كيف كان القديس بولس نفسه يوبخ . وكيف قال لكهنة أفسس « ... لم أفتر أن أنذر بدموع كل أحد » (أع ٢٠ : ١٧ ، ٣١) ... وهكذا يلح عليه أن يوبخ وينتهر ...",{h:"كأنه المسيح أو المعمدان ، أو القديس بولس ، أو تيموثاوس الأسقف ."}],37:["ويقتنع هذا « الضحية » المسكين . ويظل يوبخ الكل ، وهو لا يعرف الطريقة الروحية للتوبيخ . ولا من يوبخ من ؟ ولا بأى سلطان يفعل هو هذا ؟ وفى توبيخه يقع فى إدانة الآخرين ، وفى الغضب ، وفى القسوة ، وفى التشهير ، وتسوّد صور الناس فى نظره ، وربما بهذا الأسلوب يبعد الكثيرين عن الكنيسة ... و يتحول إلى قنبلة متفجرة ، تقذف شظاياها فى كل اتجاه ... !",{h:"وهكذا يفقد وداعته ورقته ودمائته ، ويكره الناس ويكرهونه ."},"ثم ما يلبث أن يتعب من هذا الأسلوب الذى لا يتفق مع طباعه ، ويحاول أن يعود إلى حاله الأول . ولكنه لا يجد قلبه نفس القلب ، ولا فكره نفس الفكر . بل يرى أنه قد فقد بساطته ونقاوة قلبه وفكره ، كما فقد حسن علاقاته مع الآخرين ، وفقد أمثولته الصالحة التى كان يستفيد بها غيره .",{h:"لقد أطمعه الشيطان فى فضيلة لا يعرفها ، وأفقده فضيلته الأولى ."},"فما احتفظ بالأولى ، وماكسب الثانية . وصار فى بلبلة !","وهو يسمح له بممارسة الثانية ، لأنها غير راسخة فيه ، ولا تتعب الشيطان الذى يستطيع أن يزعزعه عنها بسهولة .","من أجل هذا ، كان آباؤنا ينصحون أولادهم بقولهم : إن أية فضيلة يقدمها لك الشياطين ، و يقصدون بها أن يهدموا فضيلة أخرى عندك ، أرفضها وقل لهم :",{h:"هذه الفضيلة جيدة . ولكننى من أجل الله لا أريدها ."},"حقاً ، إن عمل الله لا يهدم بعضه بعضاً . وكل إنسان له شخصيته التى قد تختلف عن غيره . وقد لا يناسبه ما يناسب غيره . وليس كل أحد له سلطان أن يرتب وينظم ، وأن يوبخ وينتهر ، وأن يحكم ويدين . ومن يعطه الله هذا السلطان ، لابد سيمنحه أيضاً كيف يستخدمه حسناً ، دون أن يخطىء ...","وليس كل إنسان يستطيع أن يقول « ويل لى إن كنت لا أبشر » . فقد قال هذه العبارة القديس بولس الرسول الذى قال فى شرح ذلك « إذ الضرورة موضوعة علىّ » وأيضاً « قد استؤمنت على وكالة » (١كو ٩ : ١٦ ، ١٧) . وأنت ، ما هى الضرورة الموضوعة عليك ؟! ومن الذى استأمنك على وكالة ، كما استؤمن القديس بولس من فم المسيح نفسه . وكما أخذ المعمدان رسالته فى بشرى الملاك لأبيه (لو ١ :"],38:["١٥ ـ ١٧) . وكما أخذ القديس تيموثاوس مسئوليته بوضع اليد (٢تى ١ : ٦) .","مثال آخر للفضيلة الجديدة ، المقصود بها إضاعة فضيلة أخرى :",{h:"ب ـ إنسان يعيش فى نقاوة القلب ، بعيداً عن العثرات الجسدية :"},"يعيش محترساً تماماً ، لا يقرأ قراءات تعثره ، ولا ينظر إلى أية مناظر تعثره ، ولا يختلط بأية خلطة معثرة ، ولا يستمع إلى أية أحاديث معثرة . وهكذا يحتفظ بأفكاره نقية ، لا تُدخل إلى قلبه أى شىء غير طاهر ...","هذا الإنسان الطاهر ، يريد الشيطان أن يحاربه . ولا يستطيع أن يقدم له عثرة مكشوفة ، لأنه سيرفضها حتماً . فماذا تراه يفعل ؟",{h:"يفتح أمامه الباب ليكون مرشداً روحياً ، يقود الشباب للطهارة ."},"إذ كيف يعيش فى الطهارة وحده ، و يترك أولئك المساكين يسقطون كل يوم ، ولا يقدم لهم مشورة صالحة تنقذهم مما هم فيه ؟! و يقول له إستمع إلى قول الرسول « من رد خاطئاً عن ضلال طريقه ، يخلص نفساً من الموت ، و يستر كثرة من الخطايا » (يع ٥ : ٢٠) . ويظل به يقنعه لكى يقبل هذه الخدمة الروحية الحيوية ، حتى يقتنع ، ويقبل أن يرشد الذين يأتون إليه ... ثم تأتى بعد هذا الخطوة الثانية ، وهى :",{h:"لكى يكون إرشاده عملياً ، لا بد أن يستمع إلى مشاكلهم وأخطائهم ."},"و يظل هؤلاء يضعون فى أذنيه أخبارهم وقصص سقوطهم . وقد يقولون كل شىء بالتفاصيل . وربما يكون فى ما يحكونه ما يعثر ... و يستمع ( المرشد ) الطاهر إلى كل ما كان يبعد عن سماعه ، و يعرف ما كان لا يحب مطلقاً أن يعرفه . وما كان يحاول أن يبعد عنه ، أصبح الآن ينصبّ فى أذنيه ، بكامل رضاه ... وكل واحد يقدم صورة جديدة ، أو صوراً عديدة من الخطأ .",{h:"وعن طريق الإرشاد ، يجد صاحبنا عقله وقد امتلأ بصور دنسة !"},"وأصبح يعرف أشياء صارت تشوه طهارة تفكيره ، وتدنسه بأخبار وقصص « ذكرها أيضاً قبيح » (أف ٥ : ١٢) ... وحتى إن لم تعثره وتغرس فيه إنفعالات خاطئة ، فعلى الأقل ستنجس فكره . وكأنه قد قطف أثماراً غريبة من شجرة معرفة الخير والشر ...",{h:"فإن حاول أن يبتعد ، يقال له : ما ذنب هؤلاء الشبان ؟"}],39:["وقد يكونون قد تعلقوا به ، واستراحوا إلى إرشاده . وربما يتعبون ضميره بأنه إن تخلى عنهم سيرجعون إلى خطاياهم مرة أخرى . وقد يلحون عليه فى أن يظل يسندهم حتى يقفوا على أرجلهم ... وهكذا يحدث له ما حدث للوط البار ، إذ قيل عنه « إذ كان البار بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه الباره بالأفعال الأثيمة » (١بط ٢ : ٨) . وهذا الأخ قد يكون بالسمع فقط وليس بالنظر . وربما ما يسمعه يضع فى ذهنه صوراً لم ينظرها من قبل ، وكأنه نظرها فعلاً ...",{h:"وما أدرانا ، ربما هذا الأخ المرشد ، يسقط ، ولو بالفكر والقلب !"},"كان يمكن من أول القصة أن يحيلهم إلى أب اعتراف ويريح نفسه . ولكن الشيطان ورّطه ، أو قذف به فى أول الطريق ، فقبل ذلك بسلامة نية ، دون أن يعرف كيف يتطور به هذا الموضوع .","وقد ينجح أخيراً فى تحويل هؤلاء إلى آباء اعتراف . ولكن بعد أن يكون فكره هو قد صار مخزناً لقصص كثيرة وأخبار ، ضيعت نقاوته الأولى ، وأدخلت فى ذهنه معلومات جديدة عليه ، ينطبق عليها قول الحكيم « الذى يزيد علماً ، يزيد حزناً » (جا ١ : ١٨) .",{h:"ج ـ وقد تأتى حيلة الشيطان فى الإرشاد بصورة أخرى ، يقدم فيها لا أخباراً تدنس القلب ، بل شكوكاً تتعب العقل"},"إذ يكون القلب فى بساطة الإيمان ، وتكون القراءات كلها روحية تعمّق صلته بالله . و يأتى إليه من يطلبون معونته وارشاده فى شكوك تتعبهم . وتتوالى هذه الشكوك من هنا وهناك ، لكى تجد لها حلاً . و يبدأ إيمان هذا ( المرشد ) يتحول شيئاً فشيئاً من القلب إلى الفكر والبحث العلمى ... وقليلون من يحتفظون بالإثنين معاً ... ويجد الشكوك تتكاثر عليه . وليست له موهبة الرد على الشكوك ...",{h:"وينبغى أن نعرف أنه ليس كل أحد على مستوى الإرشاد ."},"الذين لهم هذه الموهبة ، لا يصيبهم ضرر سواء فى المشاكل الروحية وسماع الخطايا الجسدية ، أو فى المشاكل العقائدية وسماع الشكوك .","ولكن حيلة الشيطان الماكرة فى هذا الأمر أنه :",{h:"يقدم الإرشاد للذين ليست لهم الموهبة ، ويصيبهم منه ضرر ."}],40:["و يقدمه بأسلوب ضاغط ، يشعرهم به أنه ضرورة ملحة ، وأنه واجب مقدس وأن « من يعرف أن يعمل حسناً ولا يفعل ، فتلك خطية له » (يع ٤ : ١٧) . وما أسهل على القلب المتضع أن يقول فى انسحاق « ولكننى هنا لا أعرف » ، « أنا الذى لم أستطع أن أرشد نفسى ، كيف يمكننى أن أرشد آخرين ؟! » ...",{h:"والشيطان قد يقدم عملاً روحياً ، ليزيل به تأثر عمل روحى آخر ."},"فإن رأى إنساناً قد صلّى صلاة روحية عميقة ، وانسكب فى تأملات حارة أمام الله ، قد يرسل إليه إنساناً يطلب عمل المصالحة بين متخاصمين . لكنها إذا جلس وسط هؤلاء المتخاصمين ، بكل ما فى تصفية الجو من ضوضاء أو شوشرة أو شجار أو عتاب قاس ، تزول آثار الصلاة والتأملات . و يعود هذا المصلى إلى بيته ، وليس فى ذهنه سوى ما سمعه من مناقشات حامية ، ربما تجعل عقله يسرح إذا صلّى . وتحتاج أمثال هذه المواقف إلى إدماج الصلاة فيها ، وإلى تمهيدات روحية بعدها قبل الوقوف أمام الله للصلاة ...",{h:"وقد يرى الشيطان أن صلاتك حافلة بالتأملات ، فيريد تشتيتها :"},"فماذا يفعل ؟ يقول لك وأنت تصلى « إن هذا التأمل عجيب جداً وعميق ، وإن سمعه آخرون سيستفيدون منه . فلئلا تنساه ، قم الآن واكتبه . وهكذا يكون قد أخرجك من الصلاة إلى الكتابة ، وقطع وقفتك المتخشعة ـ أمام الله ، لكى تجلس وتكتب ، مهتماً بالآخرين أكثر من اهتمامك بالوقوف فى حضرة الله ...","وفى كل ما يجذبك إليه الشيطان من فضائل أخرى ، يكون هدفه :",{h:"يفقدك ما عندك ، مغرياً إياك بفضائل أخرى ليست معك ."},"أو هو يفقدك الثابت الذى فى يدك ، من أجل وعود فى أشياء قد لا تتم . أو قد يسمح لك ببعضها لكى يسحبه منك فيما بعد ...",{h:"٣ ـ إستخدام الفضائل فى غير موضعها"},"يقول الكتاب « لكل أمر تحت السموات وقت » (جا ٣ : ١) . فإذا استخدمت الفضائل فى غير وقتها وفى غير موضعها ، ربما تأتى بنتيجة عكسية ، ولا تخدم الغرض الروحى . وهذا بعض ما يقدمه الشيطان ضمن حيله الكثيرة ."],41:[{h:"فى وقت التوبة ، حينما يلزم الإنسحاق ، يقدّم فضيلة الفرح ."},"و يورد كل الآيات الخاصة بالفرح ، حتى يضيع الندم والإنسحاق والدموع ، كل هذه الأمور اللازمة لحفظ التوبة . وفى نفس الوقت يخفى الآيات الأخرى مثل « طوبى للحزانى الآن ، لأنهم يتعزون » (متى ٥ : ٤) .",{h:"وفى منهجه هذا ، يستخدم طريقة الآية الواحدة ..."},"وقد رفض السيد المسيح هذا المنهج . فعندما قال له الشيطان على الجبل « ... لأنه مكتوب ... » أجابه الرب « مكتوب أيضاً ... » (متى ٤ : ٦ ، ٧) . وهكذا أرانا أن منهج الآية الواحدة الذى يستخدمه الشيطان ، لا يمكن أن يوصل إلى حقيقة روحية سليمة ، طالما هناك آيات أخرى توضح الموضوع .",{h:"وقد يستخدم الشيطان آيات كثيرة فى اتجاه واحد يخدم غرضه ."},"إنه يذكر الآيات الخاصة بالرحمة ، حينما يلزم الحزم وتلزم العقوبة . و يذكر الآيات الخاصة بالعقوبة حينما يلزم العفو والحنو والرحمة .","ويحاول أن يقنع الإنسان بالصمت ، و يورد نصوصاً عديدة من الكتاب ، مستخدماً إياها فى الوقت الذى يجب فيه الكلام . كذلك يورد آيات عن فائدة الكلام وأهميته ، فى الوقت الذى يحسن فيه الصمت ...",{h:"كذلك يورد للإنسان آيات لا تناسبه ، وهى خاصة بغيره ."},"فهناك آيات خاصة بالرسل ورجال الكهنوت ، لا تنطبق على العلمانيين ، يقدمها لشخص عادى كما لو كانت تخصه هو ... مثل قول المسيح لتلاميذه الإثنى عشر « لا تدعوا لكم أباً على الأرض ... » (متى ٢٣ : ٩) .","ومثال ذلك أيضاً ذلك الشخص العنيف الذى كلما كان يرى شخصاً مخطئاً ، كان ينهال عليه ضرباً !! وذلك لأن الشيطان وضع فى أذنيه الآية التى تقول « فى أوقات الغدوات كنت أقتل جميع خطاة الأرض ، لأبيد من مدينة الرب جميع فاعلى الإثم » (مز ١٠١ : ٨) . من حيل الشيطان أيضاً فى محاربة البشر :"],42:[{h:"٤ ـ التشكيك"},"إن الشيطان يزرع الشكوك فى كل مجال من مجالات الحياة . لأن الإنسان فى حالة الشك يكون ضعيفاً يمكن للشيطان أن ينتصر عليه .",{h:"فهو مثلاً يغرس الشك من جهة التوبة ."},"سواء من جهة إمكانية التوبة ، أو من جهة قبول الله لها .","فهو يصور للإنسان أنه ليس من السهل عليه أن يتخلص من هذه الخطايا ، التى صارت طبيعة فيه ، أو عادة من عاداته ، أو صارت محبوبة لديه لا يمكنه مطلقاً الإستغناء عنها . وإذ يغرس فيه الشك الكامل فى قدرته ، يخفى عنه تماماً معونة الله ، أو يشككه فيها أيضاً ، كما قال داود النبى « كثيرون قاموا علىّ . كثيرون يقولون لنفسى : ليس له خلاص بإلهه ... » (مز ٣) .","أما إن صمم الإنسان على التوبة ، فإنه يشككه فى قبول الله لتوبته : إما لأنها أتت بعد فوات الفرصة ، أو لأنها توبة غير حقيقية ، أو لأن خطاياه بشعة من الصعب مغفرتها ! وتحتاج إلى عقوبات فوق احتماله !",{h:"وكل هدف الشيطان هو إلقاء التائب فى اليأس ."},"لكى تخور عزيمته ، ويبقى فى الخطية حيث هو ...","وكذلك يشككه الشيطان فى رحمة الله ، و يورد له آيات لا تحصى عن عدل الله ، وعن عقوباته . وربما تكون عقوبات عن خطايا أقل من خطاياه هو بكثير .","وشكوك الشيطان قد تدخل فى الحياة الشخصية أيضاً .",{h:"فهو يغرس الشك فى أيها أفضل : البتولية أم الزواج ."},"وأى طريق منها يختاره الإنسان يشككه فيه كذلك .","فإن اختار البتولية يشككه فى إمكانية الحياة فيها ، وكيف أنها صعبة جداً ، وهى فقط « للذين أعطى لهم » (متى ١٩ : ١١) ، « وكل واحد له موهبته الخاصة من الله » (١كو ٧ : ٧) . فما أدراك أن هذه موهبتك ؟! و يشرح له السقطات التى وقع فيها القديسون . و يقول له : هل أنت أفضل من داود ومن شمشون ، وكلاهما حل روح الرب عليه ؟!"],43:["وإن اختار الزواج ، يقول له : لقد فقدت إكليل البتولية . و يضع أمامه قول القديس بولس الرسول « غير المتزوج يهتم فيما للرب كيف يرضى الرب . أما المتزوج فيهتم فيما للعالم كيف يرضى إمرأته » (١كو ٧ : ٣٢ ، ٣٣) ، « ومن لا يزوج يفعل أحسن » (١كو ٧ : ٣٨) .","وهكذا يتركه فى بلبلة لا يعرف أى الطريقين يختار ... !",{h:"وهو يغرس الشكوك أيضاً فى موضوع الوحدة والخدمة ."},"إن اختار الإنسان طريق الوحدة ، يشرح له أمجاد الخدمة ، وكيف أنها طريق الرسل وأبطال الإيمان ، وأن « الذين ردوا كثيرين إلى البريفسيون كالكواكب إلى أبد الدهور » (دا ١٢ : ٣) ، وأنه « لا يوقدون سراجاً و يضعونه تحت المكيال ، بل على المنارة ، فيضىء لكل من فى البيت . فليضىء نوركم هكذا قدام الناس ... » (متى ٥ : ١٥ ، ١٦) .","وإن اختار الإنسان طريق الخدمة ، يقول له الشيطان : لقد فقدت طريق الملائكة الأرضيين ، وحياة السكون والهدوء التى يتفرغ فيها الإنسان لله وحده . أما أنت فقد اخترت طريق مرثا التى وبخها الرب بقوله « أنتِ تهتمين وتضطربين لأجل أمور كثيرة ولكن الحاجة إلى واحد » . ولم تختر طريق مريم التى جلست عند قدمى المسيح ، واختارت النصيب الصالح (يو ١٠ : ٤١ ، ٤٢) . و يذكره بالرؤيا التى ظهر فيها أن أرسانيوس المتوحد كان أفضل من موسى الأسود محب الأخوة وخادمهم .","وهكذا يستمر الشيطان فى غرس الشكوك . وكما قال يوحنا الدرجى : الراهب الذى يعيش فى الوحدة ، يحاربه الشيطان بمحبة الأخوة وخدمتهم . والراهب الذى يخدم الأخوة فى المجمع ، يحاربه الشيطان بمحبة الوحدة وحياة السكون والصلاة والتأمل .",{h:"والشيطان يغرس الشكوك فى العلاقات الإجتماعية كلها ."},"فهو يغرس الشكوك بين الزوج وزوجته ، وبين الصديق وصديقه ، وبين الشركاء فى العمل ، وبين الرئيس ومرؤسيه . يشكك فى محبة الواحد للآخر ، أو فى إخلاص وأمانة الواحد للآخر . بل يشككك فى كل تصرفات الناس ، وفى نياتهم ومقاصدهم . وكل ذلك لكى يزعزع صلات الناس ببعضهم البعض ، ويحولها إلى إنقسامات ونزاعات ، و يضيع الحب الذى هو عماد الحياة الروحية والإجتماعية كلها ..."],44:["حتى الأمور التى يمكن أن تمر ببساطة ، يعقدها الشيطان بشكوكه العديدة ، وقد يخلق منها مشاكل عويصة ... !",{h:"وهو يشكك أيضاً فى الإيمان ذاته وفى العقائد ."},"وكل البدع والهرطقات التى قاست منها البشرية هى من صنع الشيطان ومن أفكاره ، وكذلك كل المذاهب المتعددة وما بينها من صراعات . والإلحاد أيضاً هو من صنع الشيطان ...",{h:"والشيطان أيضاً يشكك فى إمكانية الحياة مع الله ."},"و يشرح أن الحياة الروحية صعبة وغير ممكنة . فمن من الناس يستطيع أن يسير فى الطريق الكرب ، أو أن يدخل من الباب الضيق (متى ٧ : ١٣ ، ١٤) . ومن يستطيع أن يصل إلى حياة الكمال التى يطلبها الرب منا (متى ٥ : ٤٨) . ومن يستطيع أن ينجو من حروب الشياطين ؟!","وفى كل ذلك يخفى عمل النعمة وعمل الروح القدس فى خلاص الإنسان ، ويخفى معونات الله الكثيرة !!",{h:"والشيطان قد يغرس فى القلب شكوكاً حول أب الإعتراف ."},"فيشككك فى مدى إهتمام أب الإعتراف بالمعترف ، ومدى محبته له ، ومدى كتمانه لأسراره ، و يشككك فى إرشاداته وصحتها وصلاحيتها للنمو الروحى . يشككك فى معرفته ، وأيضاً فى روحانيته . وهو يريد بكافة الطرق أن يبعد ضحيته عن أب الإعتراف ، الذى يكشف له حروب الشياطين وحيلهم ومكرهم . و يبقى المسكين بلا مرشد فيصبح فريسة سهلة للشياطين .","إنه يشككه فى أب الإعتراف ، لكى يخالفه ، أو يتركه ، أو أن يخفى عنه تدابيره . وكلها وسائل خاطئة . وقد يشككه أيضاً فى سر الإعتراف ذاته . و يقول له : لماذا تعترف على إنسان مثلك ؟!",{h:"وقد يشككه فى الفضيلة ذاتها ..."},"فيقول له مثلاً ما لزوم الإتضاع والوداعة ؟ إنها يضعفان شخصيتك ! وما معنى أن تترك حقك ، ولا تأخذه بالقوة ، حتى يتلاعب بك غيرك ... ؟ وهكذا مع باقى الفضائل .","أما أنت فلا تقبل الشكوك . وكلما أتاك شك ، قل : هذا من عمل الشيطان ..."],45:[{h:"ولا تقبل الشك داخلك ، ولا تستعمله ، ولا تدعه يستمر ..."},"إن كنت كفؤاً لمناقشته ، ناقشه واثبت زيفه ، واطرحه خارجاً . وإلا ، أطلب من الله أن يرفعه عنك . وتذكر قول الكتاب « كونوا راسخين ، غير متزعزعين » (١كو ١٥ : ٥٨) .","وأرجو بنعمة الله أن أحدثك عن الشكوك فى مناسبة أخرى ، بنطاق أوسع ، حينما نتحدث عن الحروب الروحية ، واحدة فواحدة بالتفاصيل .","سلاح آخر من أسلحة الشيطان فى حروبه ، هو :",{h:"٥ ـ حرب اليأس"},"اليأس حرب يلجأ إليها الشيطان بعد مقدمات طويلة تمهيدية ...","* وربما تكون هذه المقدمات سقطات متتالية يوقع فيها ضحيته ، بلا هوادة ، حتى يصرخ أخيراً ويقول لا فائدة فى . من المستحيل أن أخلص طالما أنا هكذا ... !","* وقد تكون هذه المقدمات إيحاءات يغرسها فى نفسه باستمرار ، باسم التواضع ! يقول فيها لنفسه كل يوم « أنا ضعيف وعاجز ، وكلى خطية » ... ولكن بدلاً من أن يوصله إلى الإتضاع ، يقوده إلى صغر النفس ، والشعور بأنه لن يقوم ثانية ...","* وربما تكون مقدمة حرب اليأس ، هى سقطة كبيرة (مثل سقطة يهوذا) يشعره الشيطان بعدها بأنه لا مغفرة ! أو قد لا تكون السقطة بهذه الدرجة ، ولكن ...",{h:"من عادة الشيطان أن يضخم فى الأخطاء ليوقع صاحبها فى اليأس ."},"والشيطان ماكر جداً فى هذه الناحية . فهو قبل السقوط يسهّل موضوع الخطية جداً ، حتى لتبدو شيئاً عادياً ، و يضع لها مبررات ... أما بعد الخطية ، إما أن يستمر فى سياسة التهوين لكى تتكرر ، وإما أن يدخل فى أسلوب التهويل ليوقع صاحبها فى اليأس . و يقول له : هل من المعقول أن يغفر الله خطية مثل هذه ؟",{h:"وربما يشعر الخاطىء أنه وقع فى التجديف على الروح القدس !"},"وهكذا لا تكون له مغفرة إلى الأبد (مر ٣ : ٢٩) . وطبعاً لا تكون لتلك الخطية أية علاقة بالتجديف على الروح القدس . فالتجديف على الروح هو طرد الروح القدس"],46:["من القلب ، طرداً كاملاً دائماً مدى الحياة . وهكذا لا تكون للإنسان توبة ، وبالتالى لا مغفرة . لأن المغفرة مرتبطة بالتوبة ، والتوبة مرتبطة بعمل الروح فى القلب .",{h:"وقد يجره إلى اليأس ، بإشعاره أنه لن يتوب ... !"},"يقول له : « هل من المعقول أنك ستترك الخطية ؟! مستحيل . لقد صارت تجرى فى دمك . عزيمتك إنتهت ، وإرادتك إنحلت . بل حتى مجرد الرغبة فى التوبة أصبحت غير موجودة عندك ... كم مرة حاولت أن تتوب ، وفشلت ؟! كم مرة إعترفت بخطاياك ، ورجعت إليها وربما بدرجة أسوأ ؟ ... » وهكذا يحطم معنوياته إلى أن يستسلم له ، و يتوقف عن المقاومة .","يقول له : إنك قد صرت بكليتك فى يدىّ . أنقلك من هذه اليد إلى الأخرى ، بكل سهولة ، كما أشاء . فلا داعى إذن لصراع فاشل لا تكسب منه شيئاً .",{h:"وطبعاً كل هذه تخاويف لا أساس لها ، وتهديدات زائفة ..."},"فإن الله قادر أن يمنح الإنسان التوبة ، مهما كانت حالته سيئة . والتاريخ يحكى لنا الحالات السيئة جداً التى كانت فيها مريم القبطية ، وبيلاجيه ، وأغسطينوس ، وموسى الأسود . ومع ذلك تابوا . وليس هذا فقط بل صاروا قديسين ...","ومع ذلك فكلما سقط الإنسان ، يحاول الشيطان إلقاءه فى اليأس .",{h:"ويقنعه بأن هذا سقوط دائم أبدى ! وليس سقوطاً طارئاً ."},"فما أجمل كلمة العزاء فى سفر ميخا النبى « لا تشمتى بى يا عدوتى . ( فإنى ) إذا سقطت أقوم » (مى ٧ : ٨) . والكتاب يقول إن « الصديق يسقط سبع مرات و يقوم » (أم ٢٤ : ١٦) . ومع هذا السقوط الكثير ، سماه الكتاب صديقاً ...",{h:"ومن وسائل الشيطان فى اليأس ، ضربه لنا فى أوقات روحية ."},"وهذه من حيله المشهورة ، حتى باتت معروفة للكثيرين . ومثال ذلك :","تكون فى سهرة روحية طول الليل فى الكنيسة ، فى بدء عام جديد ، وكلك رغبة وتصميم أن تبدأ حسناً بعام مبارك مقدس . وتحضر السهرة والقداس وتتناول . ثم تخرج لكى يرسل لك الشيطان إنساناً متعباً جداً يعكر دمك و يشيرك ، ويجعلك تغضب وتخطىء . وحينئذ يضربك الشيطان باليأس ، فتقول : أبعد كل هذا أسقط ! إذن لا فائدة ."],47:[{h:"كلا ، لا تيأس . فهذه هى حيله المعروفة ."},"قل كما قال النبى « إنى إن سقطت أقوم » ...","واعرف أن الشيطان لا يهدأ فى حربه . فى أول كل عام جديد ، وفى كل يوم روحى ، وبعد كل صلاة روحية ، وفى بداية كل صوم ، وبعد كل تناول ... توقّع منه ضربة لإسقاطك فإن فعل ، قل له إلعب لعبة أخرى ، فقد صارت ألاعيبك هذه مكشوفة ...","صدقونى إن الحروب فى المناسبات الروحية ، لا تحصى ... وقد تكون هذه الحروب مجرد حسد من الشيطان لعملك الروحى أو لنجاحك .",{h:"ومن وسائل اليأس ، أن الشيطان يغرى الإنسان بمستويات أعلى منه ."},"يضربه ضربات يمينية ، ويقنعه بمستويات روحية لا يستطيع الوصول إليها ، ويشجعه على ذلك بكل قوة . فإن نصحه أب اعترافه بالتدرج حتى يصل ، وأراد أن يقلل من هذا المستوى ، يشككه فى أب اعترافه ومستواه الروحى .","وما أسهل أن يسلك الإنسان يومين أو ثلاثة أو أكثر فى درجة عالية ، على غير أساس ، ثم لا يستطيع أن يستمر ، و يفشل . وهنا يبدأ الشيطان أن يعيّره و يلقيه فى اليأس ، و يقول له : إنك لا تصلح للطريق الروحى ! طبيعتك لا تتفق مع الحياة الروحية السليمة . و يستمر فى تحطيم نفسيته ... بينما لو تدرج ، كما نصحه أب الإعتراف ، لاستطاع أن يصل إلى هذا المستوى الذى أراده الشيطان أن يبدأ به .",{h:"لقد استطاع الشيطان أن يقنع الكتبة والفريسيين بأن يسلكوا بأسلوبه ."},"فكانوا فى إرشادهم الروحى « يحزمون أحمالاً ثقيلة عسرة الحمل ، و يضعونها على أكتاف الناس . وهم لا يريدون أن يحركوها بأصبعهم » (متى ٢٣ : ٤) . وهذه الأحمال الثقيلة تدفع أحياناً إلى اليأس ، إذ قد يقول حاملها : من يقدر على هذا ؟ من يستطيع أن يخلص ؟!",{h:"أما الرسل القديسون فلم يفعلوا هكذا ، بل رأوا فى قبول الأمم « أن لا يثقّل على الراجعين إلى الله من الأمم » (أع ١٥ : ١٩) ، وأرسلوا إليهم قائلين « لا نضع عليكم ثقلاً أكثر ، غير هذه الأشياء الواجبة » (أع ١٥ : ٢٨) . وقد قال القديس بولس الرسول « سقيتكم لبناً لا طعاماً ، لأنكم لم تكونوا بعد تستطيعون » (١كو ٣ : ٢) ."}],48:[{h:"لذلك إن أغراك الشيطان بما فوق مستواك ، فلا تقبل ."},"قل له : إذهب عنى يا شيطان ، فإن لى مرشدى الروحى الذى أسمع له . أما أنت فلا تقصد بى خيراً . ولك طرقك بلا نظام ، ولا توصل .","يروى عن القديس الأنبا أنطونيوس أن الشيطان أيقظه ذات ليلة لكى يصلى ، فلم يقبل القديس نصيحته . وقال له : أنا أصلى حينما أريد ، ومنك لا أسمع ...","إن الشيطان يرفع الإنسان لكى يسقطه . وإن سقط يدفعه إلى اليأس فى شماتة . وحرب اليأس هامة بالنسبة إلى الشيطان ...",{h:"فالإنسان حينما ييأس ، تتحطم روحه المعنوية ، ويفقد ثقته بنفسه ، وثقته بالله ، وثقته بإمكانية الحياة الروحية ، ويستسلم للسقوط ..."},"وهذا هو عين ما يريده الشيطان . لكيلا تقاومه فريسته ، فتهلك . وكأنه يقول لهذا الإنسان اليائس المستسلم له : إنك لن تفلت من يدى . أنت ذاهب إلى جهنم لا محالة . فلا فائدة . ولذلك نصيحتى لك أن تتمتع بالدنيا بضمة أيام ، بدلاً من أن تخسرها دنيا وآخره ... !",{h:"يقنعه الشيطان بصعوبة الحياة الروحية ، وبأنه ضعيف وطبيعته فاسدة ! كما يقنعه بأنه لن يفلت من يده ، ولا من العدل الإلهى ..."},"هذه هى أكبر أسلحة الشيطان فى حرب اليأس . والرد على كل ذلك بسيط . وهو أننا لا نحارب بإرادتنا الطبيعية ، لأن الحرب للرب (١صم ١٧ : ٤٧) ، وهو الذى يقودنا فى موكب نصرته (٢كو ٢ : ١٤) . وإن كنا نحن لا نستطيع ، بسبب ضعفنا وفسادنا وصعوبة الطريق ، فإننا نستطيع كل شىء فى المسيح الذى يقوينا (فى ٤ : ١٣) . يسندنا عمل النعمة ، وقوة الروح القدس العامل فينا ، وملائكة مرسلون لمعونتنا (عب ١ : ١٤) . وتسندنا شفاعة القديسين فينا ...","أما الشيطان فلا سلطان له علينا ، ولا نعبأ بتهديده ، وما أجمل قول الرسول « قاوموا إبليس فيهرب منكم » (يع ٤ : ٧) . أما العدل الإلهى فقد وفاه الرب على الصليب ، وقد قدّم لنا فى حبه خلاصاً هذا مقداره (عب ٢ : ٣) . ونحن « إن اعترفنا بخطايانا ، فهو أمين وعادل ، حتى يغفر لنا خطايانا ، و يطهرنا من كل إثم » (١يو ١ : ٩) . و يغسلنا فنبيض أكثر من الثلج (مز ٥٠) . وهو الذى قال لنا « إن كانت"],49:["خطاياكم كالقرمز ، تبيض كالثلج ... » (إش ١ : ١٨) .",{h:"إن حرب الشيطان هى اليأس ، بالطرق التى وحدنا عليها ."},{h:"أما الكتاب فإنه يشجعنا . ويجعل الرجاء من الفضائل الكبرى (١كو ١٣ : ١٣) ."},"وكثيرة هى وعود الله لنا وللكنيسة : إن أبواب الجحيم لن تقوى عليها (متى ١٦ : ١٨) . وإننا « بقوة الله محروسون » (١بط ١ : ٥) . وأنه قد نقشنا على كفه (إش ٤٩ : ١٦) . والكتاب يقول إن « الله لم يعطنا روح الفشل ، بل روح القوة ... » (٢تى ١ : ٧) . ولذلك نصحنا الرسول أكثر من مرة بأننا « لا نفشل » (٢كو ٤ : ١٦ ، غل ٦ : ٩) .",{h:"إن كنت ماشياً فى الطريق الروحى ، ووقعت ، لا تظن أنك لا تعرف المشى ، وتيأس ! بل قم وأكمل المسير ..."},"إن الشيطان يحسد خطواتك ويريد أن يعرقلها . فلا تدفعك عراقيله إلى اليأس . بل على العكس ، قم بقوة أكثر . واعرف أنه لولا نجاحك فى العمل الروحى ، ما كان الشيطان يحاربك ! حقاً ، لماذا يتعب الشيطان نفسه فى محاربة الساقطين ؟! إنه يتصدى بالحرى للقائمين ، وللذين يخاف جهادهم ضده .","إستمع إذن إلى قول الرسول « كونوا راسخين غير متزعزعين » (١كو ١٥ : ٥٨) .",{h:"كن قوى القلب بالله ، ولا تيأس ..."},"لا تيأس مهما كانت حروب الشيطان قوية .","ولا تيأس مهما سقطت ، ومهما نسيت الوصية ، ومهما فشل التدريب .","لا تيأس إذا كانت البداءة التى بدأت بها بداءة ضعيفة ، أو بداءة ساقطة ، أو بداءة ضائعة .","قل لنفسك : كل هذه مجرد حروب ، وأنا سأثبت فى الله .",{h:"سأسير نحو الله ، وإن كنت أجرّ رجلىّ جراً إليه ..."},"مهما سقطت مائة مرة فى الطريق ، سأقوم وأكمل طريق ...","ولن أقبل اليأس مطلقاً . إنه من عمل الشيطان .","ننتقل إلى حيلة أخرى من حيل الشيطان وهى أن :"],50:[{h:"٦ ـ الشيطان يغير خططه"},{h:"إن الشيطان لا يصر على خط معين فى محاربته للإنسان . إنما ما أسهل أن يغيّر خطه وخططه ، إن كان ذلك يوصله إلى إسقاط من يريد ."},"وسنضرب لذلك بعض أمثلة :","أ ـ شاب كان يحاربه الشيطان بالزنا حرباً عنيفة ويتعبه فيها ويسقطه أحياناً . فبدأ هذا الشاب فى حياة توبة ، وأصبح يحترس من هذه الخطية بالذات إحتراساً شديداً : يبعد عن كل أسبابها . ويسد كل الأبواب التى تأتى منها الخطية ، سواء كانت من القراءات أو السماعات أو اللقاءات . وفى نفس الوقت يقوى نفسه من الداخل بكل الوسائط الروحية ، و يصلى إلى الله بدموع لكى ينقذه ...","فماذا يفعل الشيطان إزاء هذا الحرص الشديد من خطية الزنا ؟",{h:"يقول : أتركه الآن ، لا أحاربه بهذه الخطية فترة طويلة ، حتى يظن أنه انتصر عليها تماماً ، فلا يحترس من جهتها . ولنحارب حالياً بخطية أخرى ..."},"و يتركه سنة أو إثنتين أو ثلاثاً ، بلا حروب فى هذه الخطية ، بلا عثرات ، بلا أفكار . و يلقيه مثلاً فى خطية كالكبرياء ...","يرى المسكين أنه نجا من الزنا ، فيفرح . و يغريه الشيطان بمستوى عال فى الصوم ، فى القراءة ، ثم فى الخدمة ، وفيما هو مستريح الفكر من الخطية ، ومستريح فى منهجه الروحى ، يدعوه الشيطان إلى تطبيق هذا المستوى على غيره . و يريه أنهم مقصرون ، وأنه فاقهم بمراحل ، فيوقعه فى الكبرياء . ويدعوه الى توبيخهم وتبكيتهم وإدانتهم : أبوك لا يصلى . أمك لا تصوم . إخوتك لا يتناولون . أسرتك لا تقرأ الكتاب . إذهب وبّخهم ، وبشدة ...","ويمتد نطاق التوبيخ واحتقار الآخرين ، وشتيمة واحتقار هؤلاء وأولئك ، لأنهم بعيدون عن الله ، مع تعالى القلب بما وصل إليه . وفيما هو يحاول أن يخلع الزوان ، يصير هو نفسه زواناً . إذ أصبح باسم الحق يشتم ، ويحتد ، ويدين ، ويحتقر ، ويتعالى على غيره ، ويسبح فى الغرور والكبرياء ، يقول كالفريسى « أشكرك يارب إنى لست مثل سائر الناس ... » (لو ١٨ : ١١) ."],51:["وتسأل الشيطان عن خطية الزنا التى أراح منها هذا الشاب ؟",{h:"فيجيب : الذى يهلك بالكبرياء ، كالذى يهلك بالزنا . كلاهما هالك ."},"أليس أن الذى يموت بالسلّ ، كالذى يموت بالسرطان ، كالذى يموت فى عملية جراحية ؟ كله موت ... والنهاية واحدة ... « تعدد الأسباب ، والموت واحد » ...","أما حرب الزنا التى يظن هذا الشاب أنه قد نجا منها ، ففى الحقيقة أن لها يوماً تعود فيه إليه ، حينما يقل إحتراسه من جهتها ، و يقل حرصه واجتهاده فى مقاومتها . حينئذ نضربه الضربة فلا يفيق منها . وتسأله كيف ؟ فيقول :","فى الفترة التى استراح فيها الشاب من حرب الزنا ، ظن أنها فارقته بلا عودة ، ولم يعد لها وجود فى حياته ، وأنها من الخطايا التى تحارب المبتدئين فقط . ولا يعقل أن تحارب المستويات العليا التى وصل إليها ! بل إن كثيرين أصبحوا يسترشدون به فى مقاومة هذه الخطية .","وهكذا أصبح يسمع تفاصيل عن هذه الخطية ما كان يسمح لنفسه أن يسمعها من قبل . وبعض أمور خافية عن معرفته ، صار يقرأ لها كتباً فى هذا الموضوع المعثر ، ليرد على أسئلة سائليه ، وما كان يقرأ هذه القراءات مطلقاً فى فترة حرصه واحتراسه !","وهكذا امتلأ ذهنه بأفكار صارت تترك فى نفسه مشاعر وتأثيرات ، تنمو بمرور الوقت وهو لا يدرى . إلى جوار أنه بسبب الكبرياء وإدانة الآخرين ، بدأت النعمة تتخلى عنه . وهنا أتت الساعة التى يضربه فيها الشيطان بهذه الخطية بالذات . و يسهل عليه إسقاطه . وتكون خطة الشيطان قد نجحت على الرغم من تغييرها فى الطريق ...",{h:"وهنا يقول الشيطان : إننى أرحته زمناً من هذه الخطية ، لكى لا يستعد لها . وحينما لا يستعد لها ، لا يدقق . وفى عدم تدقيقه يتساهل مع الخطية وأفكارى . وفى هذا التراخى وتساهله معى ، أضربه بالخطية التى استراح منها سنوات ، فيسقط بسهولة ."},"هذا هو الشيطان ... ! قد لا يحاربك الآن بخطية معينة ، ليس محبة منه لك ، إنما لأنه يجهز لك فخاً من نوع آخر .","ب ـ مثال آخر : إنسان آخر ساقط فى خطية الغضب ، وخطية الإدانة ، وخطايا السب والكلام الجارح . بدأ يستيقظ لنفسه ، ويدخل بقوة فى تداريب صمت ،"],52:["ليتخلص من خطايا اللسان جملة . فماذا يفعل الشيطان ؟",{h:"يقول : لا مانع من أن نغير الخطة . وبدلاً من محاربته بخطايا اللسان والغضب ، نحاربه بخطية الغرور مثلاً ..."},"بحيث يقتنع تماماً ، أنه لا يوجد إنسان أفضل منه . وكيف ذلك ؟ نريحه من خطايا اللسان تماماً ، فلا نحاربه بها الآن مطلقاً . وننصحه بشىء من النمو الفجائى فى العمل الروحى ، بلون من المغالاة ، ولا نحاربه فى ذلك .","و يظن أن لا يوجد مثله ، فيسلك فى الغرور . وربما يختلف مع أب اعترافه الذى لا يوافقه على تطرفه وغروره ، فلا يأبه . و يصبح فى وضع لا يخضع فيه لأحد ، ولا يطيع أحداً ، ولا يستشير أحداً ، ولا يحترم أحداً .","والغرور يسقطه ويهلكه ، بدون السقوط فى خطايا اللسان .","ومع ذلك فالغرور سيجعله يصطدم بالآخرين . ولا بد سيقع فى خطايا اللسان ، حتى بدون شيطان ! فكم بالأولى إذا حاربه الشيطان بها ...",{h:"إن الشيطان يعدّل خطته باستمرار . ينظر إلى حالة الإنسان ، ويختار له السقطة التى تناسبه . إنه يعرف متى يحارب ، وكيف يحارب ، وبأى نوع ... ؟"},"والذى لا يسقط بهذه الطريقة يسقط بغيرها .","والذى لا يسقط فى هذه الخطية الآن ، مصيره أن يسقط فيها هى بذاتها ، فيما بعد ، والفخاخ كثيرة ، موجودة ومنصوبة .","ج ـ مثال ثالث فى كيف يغيّر الشيطان خططه :","بدأ الصوم الكبير . وكان الشيطان فى العام الماضى يقاتل شاباً بترك الصوم ، فلم تنفع معه كل المحاربات :","* قال له ليشككه فى الصوم : ما معنى أن تصوم عن الأطعمة الحيوانية ؟! صم بالأحرى عن الخطية ، وحارب الحيوان الذى فى داخلك ... لأنه ما فائدة الصوم بدون طهارة ونقاوة ؟! ألا يكون صومك غير مقبول ؟!","ـ فأجاب الشاب : بل أنا أنفذ قول الكتاب « إفعلوا هذه ، ولا تتركوا تلك » (متى ٢٣ : ٢٣) . فأحاول أن أصوم الصومين معاً . أصوّم جسدى عن الطعام ، وأصوّم نفسى عن شهوة الخطية « أقمع جسدى وأستعبده » (١كو ٩ : ٢٧) بمنعه عن الأطعمة"],53:["الشهية ، وأتعود بذلك قهر النفس فلا تخطىء .","* قال الشيطان : ولكنك ضعيف ، وصحتك لا تحتمل الصوم . ولا بد تحتاج إلى البروتين الحيوانى لتعيش ، وبخاصة وأنت فى فترة نمو","ـ فأجابه الشاب بقول الرب « ليس بالخبز وحده يحيا الإنسان » (متى ٤ : ٤) . وتذكّر أن آدم وحواء كانا يعيشان على الثمار والبقول ، ثم عشب الأرض (تك ١ : ٢٩ ، ٣ : ١٨) . ولم يقل الكتاب إنها مرضا لنقص البروتين الحيوانى ! ...","* قال الشيطان : لا مانع إذن من أن تصوم . ولكن لا داعى لأن تصوم الصوم كله من أوله ، فهذا كثير . وأيضاً لا تضغط على نفسك فى الصوم ، لئلا يحاربك الشيطان بالمجد الباطل ! وأنت تعرف حروب الشياطين ، وخطورة ضربات اليمين .","ـ أجاب الشاب : لا أريد أن أتهاون . فالرب يدعونا إلى الكمال (متى ٥ : ٤٨) . ومهما صمت ، ماذا يكون صومى إذا قورن بأصوام القديسين ؟! إنه لا شىء ...","وصام الشاب . وحل الصوم هذا العام ، والشاب فى تصميمه .",{h:"ورأى الشيطان أن محاولة منع هذا الشاب عن الصوم ستكون محاولة عقيمة . لذلك بدأ يغيّر خطته إلى العكس ."},"* فقال للشاب : ما أفيد الصوم ! إن عمق فائدته تأتى من طول فترة الإنقطاع . ومن رأيى أن تنقطع كل يوم إلى الغروب من بدء الصوم .","ولكن لا بد أن تستشير أب اعترافك وتأخذ موافقته (وكان يعلم يقيناً أن أب الإعتراف لن يوافق) ... وهنا نصب له فخاً .","ولم يوافق أب الإعتراف ، ودعا الشاب إلى التدرج ...","* وهنا تدخل الشيطان ليقول : إن أب اعترافك هذا ، لا خبرة له بالصوم . وهو بإرشاده يعطل حياتك الروحية . و بطريقته هذه لا يمكن أن تنمو ، ولا أن تذوق حلاوة الصوم . بل أخشى عليك إذا ضغطت الظروف ، أن ينصحك يوماً بأن تفطر فى أسبوع الآلام !! والأفضل أن تغير أب اعترافك . ومن الممكن فى أمور الصوم وأمثالها ، أن لا تستشير أب الإعتراف ! أترك هذه الأمور أصرّفها معك بنفسى !","وهكذا غيّر الشيطان خطته ، من تشكيك فى الصوم ، إلى تشكيك فى أب"],54:["الإعتراف . ليس المهم عنده نوع الحرب ، إنما أن يسقط من يحاربه .","وبتحويل الشاب عن أب اعترافه ، جعله يسلك حسب هواه بلا مرشد ، مع كبرياء فى القلب يظن بها أنه أفضل من مرشده ، مع إدانة لهذا المرشد . وكل هذه وسائل تجره فى طريق السقوط إلى أسفل .","د ـ مثال رابع : شيطان المجد الباطل :","إنه شيطان يغيّر أسلوبه باستمرار ، ليطابق أى حال يراه ...",{h:"وصف بأنه شيطان مكوّر ، أى كالكرة يتقلب فى أى وضع ."},"وهو فى ذلك غير المكعب الذى لا بد أن يستقر على قاعدة معينة . أما المكور فحيثما تقلبه أو توجهه ، يتحرك ، على كل وجه ، كالكرة .","إن كنت جالساً إلى المائدة ولم تأكل ، يقول لك « يعجبنى نسكك هذا ، إنك لا تأكل كسائر الموجودين . وإن أكلت مثلهم تماماً ، يقول لك « هكذا القديسون : يتظاهرون بالأكل وهم صائمون ، لكى يخفوا فضائلهم » .",{h:"إن تكلمت ، يقول : إنه كلام الحكمة ، موضع إعجاب السامعين ..."},{h:"وإن صمتّ ، يقول : الصمت فضيلة القديسين مثل القديس أرسانيوس !"},"فكن حكيماً مع هذا الشيطان . ولا تصدقه فيما يقوله ، ولا تتأثر بكلامه وأحكامه . وإن حاربك بمديح نفسك لنفسك ، تذكّر خطاياك وضعفاتك ، وبكّت ذاتك عليها . أو تذكر ما ينقصك فى حياة البر ، حتى تقيم توازناً مع ما تسمعه من مديح ...",{h:"وعموماً ـ بالنسبة إلى أى شيطان ـ إذا غيّر خططه معك ، يمكن أن تغيّر أنت أيضاً خطتك معه ."},"ومثال ذلك ، القديس يوحنا القصير : كان الشياطين يمدحونه على ما وصل إليه من فضيلة ، حتى أن الإسقيط كله كان يطلب منه كلمة منفعة . فيجيبهم : ومن أنا المسكين ؟ ألعلى وصلت إلى ما وصل إليه الأنبا أنطونيوس أو الأنبا بوا ؟! إننى كل خطية . فإن قالوا له : حقاً إنك خاطىء وستهلك ، يجيبهم : وأين ذهبت محبة الله ورحمته ؟!","فكان الشياطين يقولون له « لقد حيرتنا . إن رفعناك إتضعت . وإن وضعناك إرتفعت » ... فكن أنت هكذا فى تعاملك مع الشياطين ."],55:["إن مدحوك ، تذكر خطاياك . وإن أراحوك من محارباتهم ، قل : لعلهم يعدّون لى ، فخاً لا أعرفه . فليرحم الرب ضعفى ...","بل أذكر أنك لم تصل إلى المستوى الذى يحاربك فيه الشيطان . مثل ذلك الأخ الذى شكا للقديس الأنبا بيشوى محاربة الشيطان له . فظهر الشيطان للقديس ، وقال له : من هو هذا الأخ لأحاربه ؟ أنا لم أسمع بعد بأنه قد ترهب !","إن حرب الشياطين الحقيقية حرب شديدة . وربما غالبيتنا لم يتعرضوا لها . والحروب التى تعرض لها القديسون كانت عنيفة ، لا يسمح الله أن نكابدها نحن .","إن شيطان المجد الباطل ، يقدم حرباً أساسها المديح . ولكن هناك طريقة عكسية لهذه تماماً يحارب بها الشيطان أحياناً ، وهى : حرب الكآبة ...",{h:"٧ ـ الكآبة"},"هى نوع من المبالغة الشديدة يحارب بها الشيطان التائبين ، أو الشاعرين بخطاياهم ، أو المنسحقين بقلوبهم ، لكى يجرهم إلى الضياع ...","يختار لهم الشيطان من بين كل آيات الكتاب المقدس آية واحدة يضمها أمامهم باستمرار وهى « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) . و يقول لهم إن الكتاب لم يذكر مطلقاً أن المسيح قد ضحك ، ولكن ذكر أنه بكى مرات ...","وكلما يقع هذا الإنسان فى خطية ، أو يُحارب بشدة فى خطية ، يظل الشيطان يزيده كآبة . و يقول له : أنت لست إبناً لله ، لأنك خاطىء ، والكتاب يقول إن « المولود من الله لا يخطىء » (١يو ٣ : ٩ : ٥ : ١٨) .",{h:"و يقول له : وليس الله فقط ، بل حتى أب اعترافك القديس لا تستحق أن تكون له إبناً . إنك عار عليه . تسىء سمعته ."},"والأفضل أن تترك هذا الأب البار ، حتى لا يعيره الناس قائلين : أنظر ، هذه هى عينة أبنائك . وأيضاً أتركه حتى لا يأخذ دينونة بسببك ، وحتى لا تحزن نفسه باستمرار ، كلما يراك هكذا .","وهكذا يبعده عن الله ، والشعور بأبوته ، و يبعده عن أب الإعتراف ."],56:["وحتى إن أمسك الكتاب المقدس ليقرأ ، يقول له : وهل تتجرأ تمسك كتاب الله بيدك هذه غير الطاهرة . إن كل كلمة فى هذا الكتاب دينونة عليك . لأن السيد المسيح نفسه يقول عنك وعن أمثالك « الكلام الذى تكلمت به هو يدينه فى اليوم الأخير » (يو ١٢ : ٤٨) . وهذا يملأ نفسه بالكآبة ، حتى يترك الكتاب بنفس مُرّة يائسة ...",{h:"وحتى الخدمة ـ إن كان خادماً ـ يبعده عنها كغير مستحق ."},"فيقول له : إن الخدمة هى عمل القديسين وليس الخطاة . وأنت خاطىء لا تستحق أن تجلس فى مكان المعلمين ، وإلا ستكون عثرة ، كما أن الخدمة ستنسيك خطاياك التى يجب أن تضعها أمامك فى كل حين ، وتكتئب عليها ليلاً ونهاراً .",{h:"حتى إن وقف يصلى ، يمنعه قائلاً : « صلاة الأشرار مكرهة للرب » (أم ١٥ : ٨ ، ٢٨ : ٩) ..."},"و يقول له : هوذا المشار وقف بعيداً ، لا يجرؤ أن يرفع نظره إلى فوق (لو ١٨ : ١٣) . وأنت بكل استهتار ولا مبالاة ، تتحدث مع الله ، وأنت كاسر لكل وصاياه . ليتك تخجل من نفسك ، وتبعد عن هذه الصلاة الأثيمة !",{h:"وهكذا يبعده بالكآبة عن كل وسائط النعمة ، لينفرد به ."},"ينفرد به وهو وحيد ، بنفس محطمة ، وليس حوله إنجيل ولا صلاة ، ولا أب اعتراف ، ولا خدمة ولا اجتماعات كنسية ، بل ربما وليس حوله أيضاً أصدقاء ، إذ بعدوا عنه بسبب كآبته ، أو بعد هو عنهم ... وهكذا يصير فريسة سهلة للشيطان .",{h:"وما أسهل أن يقول له : أترك الوسط الدينى لأنه سبب كآبتك !"},"أو ما أسهل أن يرسل له هذه العبارة على أفواه أقاربه ، أو على فم طبيب معالج . و يجذبه بالتدريج إلى وسائل من اللهو للترفيه عنه من كآبته ، ولو إلى فترة مؤقتة ، يطيلها الشيطان بحيله الأخرى ، إلى أن يبعده عن الله تماماً ...","أو أن ألشيطان يسقطه بوسيلة أخرى وهى اليأس . وتكون الكآبة ممهدة لذلك .",{h:"وحيلة الشيطان فى الكآبة ، أنه أبعد فريسته عن الرجاء والمغفرة ."},"أبعده عن وجه الله المحب ، الذى استقبل إبنه الضال بكل ترحاب ، وفرح به ، وجعل الكل يفرحون ، وألبسه الحلة الأولى (لو ١٥ : ٢٢ ـ ٢٤) . بل إن الرب يقول إنه « يكون فرح قدام ملائكة الله بخاطىء واحد يتوب » (لو ١٥ : ١٠) ... حقاً إن"],57:["القديسين بكوا على خطاياهم ، ولكن ليس بغير رجاء . بل إن الكتاب يقول :","« لا تحزنوا كالباقين الذين لا رجاء لهم » (١تس ٤ : ١٣) .","الحزن على الخطية ، لا يفصلنا عن الله ، بل يقربنا منه . و يزيد محبتنا له ، لأنه على الرغم من خطايانا ، غفر لنا . بل قال بالأكثر « لأنى أصفح عن إثمهم ، ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) . والله لا يسر بموت الشرير ، بل بأن يرجع ويحيا (حز ١٨ : ٢٣) .",{h:"مشكلة الذى فقد الرجاء بالكآبة ، أنه أخذ مشورة الحية ، الشيطان ."},"أما كلمة الله ، فإنها مملوءة عزاءً . وقلب الله باستمرار مملوء حباً . والكآبة جُعلت لكى تقود إلى التواضع والإنسحاق ، وليس إلى اليأس والإنفصال عن الله . أما إذا استخدم الشيطان هذه الكآبة بطرقه الشريرة ، فإنه لا شك يضيع صاحبها .","ها هو بطرس الرسول بعد أن أنكر المسيح ، ومع أنه بكى بكاءً مراً ، إلا أن السيد المسيح المجد ظهر له ، وقال له « إرعَ غنمى . إرعَ خرافى » (يو ٢١ : ١٥ ، ١٦) . أى رجاء يمكن أن يقال أكثر من هذا . لذلك فإن كآبة الوجه التى تصلح القلب ، ينبغى ألا تنفصل عن الحب وعن الرجاء .","ننتقل إلى نقطة أخرى من حروب الشياطين ، وهى :",{h:"٨ ـ السرعة"},"أعمال الشيطان تتصف بالسرعة ، أو بما يسمونه فى العامية ( جة ) ... بعكس أعمال الله التى تتميز بالهدوء والروية وطول الأناة . وقد تأخذ وقتاً ، ولكنها تكون متئدة وهادئة ، كقصة الخلاص ، ووعود الله ...",{h:"الشيطان يقدم لك فكراً ، ويظل يلح ويلح على تنفيذه بسرعة ..."},"وتشعر حينما يكون الفكر الشيطانى فى داخلك ، بحماس شديد للتنفيذ ، وبنار تتقد فى داخلك ، وحافز يدفعك دفعاً للتنفيذ ، الآن ، وبلا إبطاء ، ودون أن يأخذ الفكر فترة حضانة داخلك ، تناقشه وتفحصه وتبحثه ، وتنظر إليه من جميع الزوايا الأخرى ، وتراجع رأيك فيه ..."],58:[{h:"إنه يقصد بالسرعة أنك لا تفكر ، وأيضاً لا تستشير ."},"يريد بالسرعة أن ينفرد بك ، دون أن يدخل أحد بينكما ، تستشيره وتستفيد برأيه وخبرته وروحياته ، لا صديق ولا قريب ، ولا أب اعتراف ، ولا مرشد روحى ، ولا أى إنسان صاحب خبرة ، إنما بسرعة عليك أن تنفذ ...",{h:"وهو يريد بالسرعة أيضاً ، عدم عرض الأمر على الله بالصلاة ."},"لا يريد أن يعطيك فرصة تصلى فيها من أجل هذا الموضوع ، وترى ماذا يقول الله فيه ، ولا فرصة ترفع فيها قداساً من أجل الموضوع ، أو تصوم طالباً إرشاد الرب ... إنما يلح عليك بالفكر إلحاحاً ، ويقنعك به كأنه بديهية لا تقبل النقاش ... ولذلك قال الآباء :",{h:"كل فكر ، يلح عليك أن تنفذه بسرعة ، هو من الشيطان ."},"وطبعاً لا يقصد بهذا الرغبة فى التوبة والرجوع إلى الله ، والإلتصاق به بالحب ، بل الأفكار الأخرى التى تحتاج إلى مناقشة ، وليست عاجلة (كإنقاذ غريق أو إطفاء حريق) ... وكم من أمور أسرع الإنسان فى تنفيذها . وحينما رجع إلى نفسه ندم على ذلك جداً . وأحياناً تكون أفكار الخطية والشهوة ملحة جداً ، لا تعطى صاحبها فرصة للتفكير وتغيير مجرى مشاعره ...",{h:"الشيطان يقصد بالسرعة أيضاً ، أنه لا ينكشف ..."},"ربما تكون وراء فكرته أو اقتراحه كذبة أو حيلة لا يريد لها أن تنكشف بالتفكير أو بالإستشارة أو بالصلاة . فيلح على إتمامها بسرعة قبل كشفها . ولذلك فإن وجود أب الإعتراف مفيد هنا فى كشف حيل العدو . وقد قيل « الذين بلا مرشد ، يسقطون مثل أوراق الشجر » . لأنهم ينفذون بسرعة قبل أن يستشيروا . يلح عليهم الشيطان إلحاحاً ، فينمرمون فكره ، قبل أن تنكشف حيلته .",{h:"أما أولاد الله ، فإنهم لا يطيعون كل فكر يأتيهم ..."},"مثال ذلك الفكر الذى جاء للقديس مقاريوس لكى يذهب إلى البرية الجوانية ليرى الآباء السوّاح . يقول القديس « فبقيت مقاتلاً لهذا الفكر ثلاث سنوات ، لأعرف هل هو من الله أم لا » ... ما أعجب هذا الأمر ، بالنسبة إلى قديس عظيم كالقديس مقاريوس الكبير ، وبالنسبة إلى فكر روحى كزيارة السوّاح ... !"],59:[{h:"لم ير القديسون فى الإبطاء ضرراً ، بل فيه فائدة ..."},"إنهم لا ينفذون بسرعة لئلا يكون الفكر من الشيطان . وإبطاؤهم فى التنفيذ يعطيهم فرصة للتأكد ، ينتظرون فيها إلى أن يعلن الله رأيه فى الموضوع . وهم فى ذلك يقولون تلك العبارة الجميلة :",{h:"الذى من عند الله يثبت . والذى ليس من الله يزول ."},"وهكذا نرى أن القديس الأنبا غاليون لما ظهر له الشيطان فى هيئة راهب ، وقال له إنه أحد السوّاح ، وأن زملاءه السواح قد ضموه إلى صحبتهم ، ودعاه للسير معه . وأطاعه الأنبا غاليون ، دون أن يأخذ فرصة لعرض الأمر على الله وعلى أب الإعتراف ... حدث أن الشياطين الذين ظهروا فى هيئة سواح أتاهوه فى البرية ، ثم تركوه وهم يهزأون . وقالوا له « ستموت هنا وحدك ، فى هذا القفر » لولا أن الله أنقذه ...","هناك حيلة أخرى للشيطان غير السرعة ، أو هى عكسها . وهى :",{h:"٩ ـ التدرج الطويل"},"تتعدد وسائل الشيطان فى حروبه . وقد يبدو أحياناً شىء من التناقض بين أسلوب وآخر . ولكن يجمعها كلها هدف واحد ، وإن كانت الوسيلة تختلف بحسب نوعية الحالة ... وعموماً فالشيطان لا يحب الوتيرة الواحدة لئلا يألفها الناس .",{h:"فهو أحياناً يضرب ضربة سريعة فجائية ، لا يكون الشخص مستعداً لها . وأحياناً يسير فى تدرج طويل ، بحيث لا يشعر به صاحبه ..."},"والتدرج يلزمه وقت قد يطول . ولكن الشيطان لا يهمه الوقت ، إنما يهمه السقوط . والتدرج يصلح غالباً للأشخاص الذين لا يقبلون خطية معينة بسهولة . ولكنه يوصلهم إليها تدريجياً فى هدوء ، بجرعات قليلة ، أو قليلة جداً ، تزداد بالوقت ، حتى تقضى عليهم .",{h:"وقد يقسم الخطية إلى مراحل . كل مرحلة تثبت أقدامها بالوقت ."},"وربما تكون الخطوة الأولى إلى الخطية ، ليست خطية على الإطلاق ، ولا تتعب الضمير . فالمرحلة الأولى فى سقوط داود النبى ، كانت فى عدم خروجه إلى الحرب"],60:["بنفسه : يرسل الجيش و يبق هو فى بيته . والمرحلة الثانية كانت شيئاً من الترف دخل إلى حياته ، بعد أن كان مشرداً من برية إلى برية أيام مطاردة شاول الملك له ... وهاتان المرحلتان عبرهما داود دون أن يشعر بخطأ .",{h:"ولكن عوامل نفسية كانت تأخذ مجراها داخله وتفقده حرارته الروحية ."},"ثم دخل فى مرحلة ثالثة وهى الإكثار من الزوجات . وكان محللاً فى أيامه ، ولكنه بلا شك هبط به إلى مستوى الجسد . وإن كان مستوى الحلال ، ولكن ليس مستوى الكمال . وصار للجسد سيطرة عليه شعر أو لم يشعر .","المرحلة الرابعة ، أنه صعد إلى السطح ، يتمشى و يتفرج ، ولا مانع من أن ينظر إلى مساكن غيره ، و يبصر خصوصيات الناس . وهنا بدء إنحراف .","المرحلة الخامسة ، كانت ضربة شديدة من الشيطان أوقعت رجل المزامير العظيم فى خطية الشهوة ، ثم فى خطية الزنا .","المرحلة السادسة ، كانت التورط ، الذى أراد به إخفاء خطيئته بجملة من الخطايا أفقدته روحانيته ، وهبطت به من سىء إلى أسوأ .",{h:"وربما هذه المراحل ، كان الشيطان يعد لها منذ زمن ..."},"إنه يحب ـ حينما يضرب الضربة ـ أن تصيب مقتلاً . وهذا يتطلب منه أحياناً تمهيدات طويلة المدى . بحيث حينما يأتى ، يجد البيت مزيناً مفروشاً ، مهيئاً لعمله ، ويجد الضحية جاهزة بلا مقاومة ... وحتى إن قاومت تكون بلا قدرة على الإطلاق ، فتسقط أمامه بسهولة !",{h:"قصة يعقوب المجاهد :"},"إنها تشبه قصة سقوط داود ، فى أنها مثلها تعطينا فكرة واضحة عن خطة الشيطان فى أسلوب التدرج الطويل . وفيها استطاع أن يسقط ناسكاً عظيماً ، وقديساً له موهبة إخراج الشياطين . ولكن الشيطان هنا أمكنه أن يضرب القديس ثلاث ضربات قاتلة ، وكاد يهلكه لولا أن رحمة الله إقتادته إلى التوبة . فكيف حدث ذلك ؟","فتاة ( إبنة ملك ) ، صرعها روح نجس . وعجز الكل عن إخراجه ، فأتوا بها إلى"],61:["القديس يعقوب المجاهد . فصلّى عليها فخرج الروح النجس . ولكن ما أن رجعت إلى بلدها حتى عاد إليها مرة أخرى . فسافروا وأتوا بها إلى القديس ، فصلى عليها فخرج الروح . ولكن ما أن رجعت إلى بلدها حتى عاد إليها . فسافروا إلى القديس مرة ثالثة .",{h:"وتكررت لعبة الشيطان مرات عديدة ، حتى يئسوا من كثرة الأسفار ."},"وأخيراً ، قرر الملك أن تبقى الأميرة إلى جوار القديس . فبنوا لها حجرة . وكان الشيطان كلما يصرعها يدخلونها إليه . وتطور الأمر إلى أن أبقوها معه . ولما اطمأنوا على هدوئها تركوها معه . ومضوا ...","وبمرور الوقت تكونت دالة بينهما ، تطورت إلى الخطيئة . ثم حملت الفتاة منه . ورأى أن الخطية ستنكشف وتضيع سمعته ، وربما يقتله الملك . فوسوس له الشيطان أن يقتلها ، فقتلها ودفنها فى مكان بعيد فى الصحراء .","ومرت شهور ، وجاء رسل الملك للإطمئنان عليها . ولما سألوا القديس ، أخفى جريمته الثانية بالكذب . وقال لهم صرعها الشيطان مرة ، فانطلقت بسرعة هاربة فى الجبل ولم أستطع اللحاق بها ، واختفت ... وصدقوه لأنه لم يكن موضع شك .",{h:"وهكذا ضربه الشيطان ثلاث ضربات ، وأوقعه فى الزنا والقتل والكذب ."},"كل ذلك فى تدرج طويل ، ما كان أوله يوحى مطلقاً بآخره . ولكنها حيل الشيطان الذى يسبك مكيدته فى صبر عجيب .","وسياسة التدرج هذه لها حكمة كبيرة وهى :",{h:"فى كل خطوة يقترب الإنسان إلى جو الخطية ، ويعتاده ، ويضعف . إرادته تكون قوية جداً ، وهو خارج مجال الخطية . وقد يكون نافراً جداً من كل مجالاتها . وبالوقت يألفها ، ولا تصبح غريبة عليه . وبالتدريج تدخل إلى فكره ، ثم إلى مشاعره . وفى كل خطوة تضعف إرادته عن المقاومة أحسّ أو لم يحسّ ..."},{h:"ومن أمثلة التدرج الطويل موضوع العادات ."},"كل عادة مسيطرة على الإنسان ، لم تبدأ هكذا مطلقاً . وربما كان هو المسيطر عليها أولاً و يستطيع إبطالها . ولكن بالتدرج الطويل فقد سيطرته ، ثم سيطرت هى عليه . وربما الشيطان فى أول خطوة ، قال له عبارة واحدة وهى جرّب أو إختبر ... الحياة كلها خبرات . والأمر كله بيدك ، تستطيع أن تمتنع وقتما تشاء . وظل به هكذا إلى أن أتى"],62:["الوقت الذى فيه سلّم إرادته بالتمام ولم يعد يقاوم ، بل لا يشاء أن يقاوم !!",{h:"على أن التخلص من العادات ممكن لمن يريد ."},"الشيطان قد يقول لك لن تستطيع . وإن استطعت ستعود إليها مرة أخرى . إنها ضمن حرب اليأس . ولكن لا تستسلم . فإن العادة تكونت نتيجة عمل إرادى متكرر . و يمكن أن تتخلص منها بعمل إرادى عكسى متكرر ، أى تثبت فيه .","ونصيحتنا لمقاومة سياسة التدرج هذه من جانب الشيطان ، أن تبعد عن الخطوة الأولى ، بكل حزم ، مهما كانت تبدو بريئة ، أو يقنعك الشيطان بأنها بريئة .",{h:"واحترس من كذبه ، إن قال لك إنها خطوة واحدة ولن تتطور ."},"إن الشيطان لا يقبل على نفسه أن يتركها عند حدود الخطوة الواحدة ، دون أن يتقدم بها باستمرار نحو أغراضه البعيدة ... فاحترس منه .","بل احترس حتى من الخطوة الأولى ، وليس فقط من تطورها ، مهما بدت هذه الخطوة فى نظرك من الأمور الصغيرة . وهنا أحذرك من حيل شيطان ماكر ، هو شيطان الأمور الصغيرة .",{h:"١٠ ـ الأمور الصغيرة"},"هذا يحذرنا منه سفر النشيد قائلاً « خذوا لنا الثعالب ، الثعالب الصغيرة ، المفسدة للكروم » (نش ٢ : ١٥) . وهنا نجد تحذيراً هاماً وهو :",{h:"مع أنها صغيرة ، إلا أنها مفسدة للكروم ."},"أول خطر لهذه الثعالب الصغار أنها تستطيع الدخول إلى النفس . الثعالب الكبيرة ربما لا تجد فتحة مناسبة لها فى سياج البستان تدخل منها . أما الصغيرة فدخولها سهل .","الخطايا الكبيرة ربما يحترس منها الإنسان جداً ، و يبتعد عنها ، و ينفر منها ، لذلك فالشيطان قد يؤجل محاربته بها ، مادام هو متنبهاً لها . أما الأمور الصغيرة ، فيحاربه بها :",{h:"يحاربه بها ، لأنه لا يحترس منها ، ولا يهتم بها ."},"تقول لإنسان مثلاً : إحذر من العثرات . فيقول لك فى استغراب : « عثرات ؟!"],63:["وهل مثلى يخاف من هذه الأمور الصغيرة ؟! إنها قد تحارب الصغار أو المبتدئين . أما نحن فقد كبرنا عن أمثال هذه الأمور » ... لهذا يحاربه الشيطان بها ...","من كان يظن أن أبانا إبراهيم حبيب الله ، يخاف و يقول عن زوجته ساره إنها أخته ، فيأخذونها و يستبقونه ؟! لا شك أن الخوف والكذب من الأمور الصغيرة بالنسبة إلى رجل روحانى عظيم مثل أبينا إبراهيم أبى الآباء والأنبياء ... !",{h:"إن تنجيس الإنسان لا تلزمه خطية كبيرة مثل الزنا ، إنما يكفى لذلك خطية من اللسان الذى « يدنس الجسم كله » (يع ٣ : ٦) ."},"إنه « عضو صغير » ولكنه « عالم الإثم » ، « شر لا يُضبط ، مملوء سماً مميتاً » (يع ٣ : ٥ ـ ٨) . إنه ينجس الإنسان ، كما قال الرب « ليس ما يدخل الفم ينجس الإنسان ، بل ما يخرج من الفم ينجس الإنسان ... أما ما يخرج من الفم ، فمن القلب يصدر . وذاك ينجس الإنسان » (متى ١٥ : ١١ ، ١٨) . والعجيب أن خطية اللسان يقنعك الشيطان أنها من الأمور الصغيرة .",{h:"حقاً إن شيطان الأمور الصغيرة ، يمكن أن يهلك الإنسان ."},"فيمكن أن تغرق سفينة بسبب ثقب صغير فى قاعها ...","والإنسان لا يشترط أن يكون موته بواسطة وحش كبير يفترسه ، إنما يكفى لموته ميكروب صغير لا يُرى بالعين المجردة ... لقد قال السيد الرب فى عظته على الجبل :","« ومن قال يا أحمق ، يكون مستوجب نار جهنم » (متى ٥ : ٢٢) .","ما أسهل أن يقنعك الشيطان بأن كلمة ( أحمق ) وأشباهها هى من الأمور الصغيرة ! وربما كان حنانيا وسفيرا يظنان أن خطيتها أيضاً هى من الأمور الصغيرة ، وقد هلكا بها (أع ٥ : ١ ـ ١١) . وربما ظن سليمان أن زواجه بالأجنبيات هو من الأمور الصغيرة ، وقد رأينا نتائجه الخطيرة جداً على خلاص سليمان نفسه (١مل ١١ : ١-١١) .",{h:"إن « الأمور الصغيرة » قد لا تكون صغيرة فعلاً ."},"الشيطان يسميها هكذا ، ولكنها قد لا تكون كذلك ... وربما توصل إلى أخطر النتائج ، كما حدث مع سليمان وداود وحنانيا . وقد تتحول هذه الأمور الصغيرة إلى أشياء خطيرة جداً ..."],64:["إن الله يختبر إرادتنا بأى اختبار مهما بدا بسيطاً ، لكنه يكشف نفسيتنا من الداخل ، كما اختبر آدم وحواء بثمرة من ثمار الجنة .",{h:"فما هى هذه الأمور الصغيرة ؟ ما أمثلتها ؟"},"ربما تكون مثل تمسك الإنسان برأيه ، وعدم إستشارته لأحد . وقد يقول له الشيطان « وماذا فى ذلك ؟ أى خطأ فيه ؟ وهل لا بد أن تستشير ؟ وهل عقلك لا يكفى ؟! » . وقد تكون الأمور الصغيرة مثل قليل من التساهل مع الحواس والقراءات والسماعات ... أو عدم التدقيق فى الكلام ، أو عدم لوم النفس فى كل أخطائها .",{h:"طريقة الخلاص من شيطان الأمور الصغيرة هى حياة التدقيق ."},"كذلك التمسك بفضيلة « الأمانة فى القليل » فالرب يقول « الأمين فى القليل ، أمين أيضاً فى الكثير » (لو ١٦ : ١٠) .","تحدثنا عن الأمور الصغيرة . ومن حيل الشيطان أيضاً :",{h:"١١ ـ التأجيل"},"إن الشيطان يريد بكل جهده أن يمنعك عن العمل الروحى .",{h:"أما إن وجدك مصراً على العمل ، فإنه يدعوك إلى التأجيل ."},"يقول لك : لماذا الإسراع ؟ الأمر فى يدنا نستطيع أن نعمله فى أى وقت . ربما التريث يعطينا فكرة لفحص الأمر أكثر ، أو لاختيار أسهل السبل الموصلة إليه ، أو يعطينا مزيداً من الإقتناع ... على أية الحالات عندنا بعض أمور هامة فى أيدينا ، ننتهى منها أولاً . ثم نأتى إلى هذا الموضوع .",{h:"والمقصود بالتأجيل هو إضاعة الحماس للعمل ، أو إضاعة الفرصة ، أو ترك الموضوع فترة لعلك تنساها ، أو يحدث ما يغطى عليه ..."},"كأن تأتيك مشغولية كبيرة تأخذ كل اهتمامك ووقتك ، أو يحدث حادث يعطلك ، أو تحدث عوائق معينة تضع صعوبات أمامك فى التنفيذ ، أو يلقى الشيطان فى طريقك بخطية تفتر بها حرارتك الروحية ، فلا تنفذ ما كنت قد نويت عليه وأجلته ...","نتذكر أن الإبن الضال لما أتاه الشعور أن يقوم ليذهب إلى أبيه ، قام فعلاً وذهب"],65:["(لو ١٥ : ١٨ ، ٢٠) . ولو أنه أجّل ، ما كنا نضمن كيف تنتهى قصته .",{h:"ومن أمثلة مضار التأجيل ما حدث لفيلكس الوالى والملك أغريباس :"},"بينما كان القديس بولس الرسول يتكلم عن البر والتعفف والدينونة العتيدة أن تكون ، إرتعب فيلكس وقال للقديس بولس « أما الآن فاذهب . ومتى حصل لى وقت أستدعيك » (أع ٢٤ : ٢٥) . وبالتأجيل ضاع التأثر الذى كان عند فيلكس هذا . ولم يحصل له وقت ، ولم يستدع بولس .","كذلك أغريباس الملك ، بينما كان القديس بولس يترافع أمامه ، قال له : أتؤمن أيها الملك أغريباس بالأنبياء ؟ أنا أعلم أنك تؤمن . فقال أغريباس لبولس « بقليل تقنعنى أن أصير مسيحياً » . وبالتأجيل ، لم يحصل أغريباس على هذا القليل ليقتنع . ولم يذكر الكتاب أنه آمن .",{h:"ربما إحدى زيارات النعمة تدعوك ، فإن أجّلت ضاع تأثيرها ."},"إن الفرصة فى يدك ، والحماس فى قلبك ، فاعمل عمل الرب ولا تتهاون ولا توّجل ، لأن التأجيل ربما يكون خطوة إلى الإلغاء . والشيطان يقصد به ذلك . إنه لا يريد أن يمنعك فى صراحة . ولكنه فى لباقة يمنعك فعلاً ... بالتأجيل . فاحترس منه .",{h:"لا توّجل التوبة ، ولا الصلاة ، ولا عمل الخير جملة ."},"والكتاب يقول « لا تمنع الخير عن أهله ، حين يكون فى طاقة يدك أن تفعله . لا تقل لصاحبك : أرجع فأعطيك غداً ، وموجود عندك » (أم ٣ : ٢٧ ، ٢٨) .","هذا عن عمل الخير من نحو الغير . وكذلك من نحو نفسك . فكلما يتكلم روح الله فى داخلك ، لا توّجل الإستجابة لنداله . فالرسول يقول أكثر من مرة « إن سمعتم صوته ، فلا تقسوا قلوبكم » (عب ٣ : ٧ ، ١٥) .",{h:"إذن التأجيل لون من ألوان قساوة القلب ."},"والشيطان يدعوك إلى هذه القساوة ، فيما يدعوك إلى التأجيل ، أو هو يجعلك تعتاد قساوة القلب لتستمر بعيداً عن الله .","ومن ضمن الوسائل التى يقدمها الشيطان كسبب للتأجيل : المشغولية ."],66:[{h:"١٢ ـ المشغولية"},"بمشغوليات كثيرة يريد الشيطان أن يعطلك عن أى عمل روحى تعمله . هو لا يريدك مطلقاً أن تجلس مع الله ، أو أن تجلس مع نفسك . لأنه يخشى أن هذا الأمر يفصلك عنه و يلصقك بالله ، وهذا أخشى ما يخشاه ...","فإن رآك الشيطان سواظباً على صلواتك وقراءاتك ، ومواظباً على الإجتماعات الروحية وكل وسائط النعمة التى تنمى محبة الله فى قلبك ، حينئذ يحاربك بالمشغولية . وتكون إما مشغولية مؤقتة لتعطيل عمل معين ، أو مشغولية دائمة ، وهذه أخطر ...",{h:"قد تكون المشغولية عملاً إضافياً ، يأتيك منه ربح مادى ."},"بحيث لا توجد معه وقتاً تتفرغ فيه لله . و يقنعك أن هذا العمل لازم جداً لمعيشتك ولا يمكنك الإستغناء عنه . ومثل ذلك أيضاً ما يعرضه على البعض من دراسات عليا ، أو بحوث ، لتحسين مستواه العلمى ، بحيث ينتهى من بحث ليجد آخر أمامه ...",{h:"وقد تكون المشغوليات التى يقدمها خدمات كنسية تعطل وقت الصلاة ."},"الذى يرفض المشغوليات المادية ، يقدم له خدمات كنسية ، ويقنع ضميره بأهميتها . ونحن لا نعارض الخدمة ، إنما المفروض أن تكون فى حدود معينة بحيث لا تعطل الصلاة ولا التأمل ولا القراءة الروحية ، ولا الصلة الخاصة بالله .",{h:"ليس فقط من أجل روحانية الخادم ، بل أيضاً لنجاح الخدمة ."},"فالخادم إذا كثرت مشغولياته بحيث تفتر معها روحياته ، لا تكون خدمته ناجحة ولا يكون لها تأثير قوى . لأن جفاف حياة الخادم الروحية ، يجعل خدمته روتينية أو عقلانية ، لا تدخل إلى أعماق القلب ، ولا تخاطب الروح ...","وما أكثر الخدام الذين تجدهم مشغولين كل الوقت بأنواع أنشطة لا تنتهى ، ولا يجدون وقتاً يصلون فيه صلاة ، أو مزموراً ، أو ينفردون فيه مع الله . يعيشون على الرصيد الروحى القديم الذى كان لهم ، دون جديد يضيفونه إليه . وحياتهم مهددة بالضياع ...",{h:"هنا الشيطان لا يحارب العمل الروحى . ولكن لا يعطيه وقتاً ."},"لا يمنعك من الصلاة ولا من التأمل والقراءة ، ولا من الترتيل والتسبيح ، ولا من"],67:["المطانيات ولا من محاسبة النفس ، بل قد يجعلك تلقى دروساً ومحاضرات عن هذه الوسائط الروحية وفائدتها . ولكنه لا يترك لك وقتاً لممارستها . وتصبح ـ كما قال أحد الأدباء الروحيين ـ مثل الأجراس التى تدعو الناس إلى دخول الهياكل ، دون أن تدخل هى إلى الهياكل ! حقاً ما أجمل قول أحدهم « قضيت عمرك فى خدمة بيت الرب ، فمتى تخدم رب البيت ؟! » ...",{h:"هذا بالنسبة إلى الخدام . أما الأشخاص العاديون ، فما أكثر مشاغلهم ."},"هناك مشغوليات الزيارات ، والأحاديث والجدل والمناقشات . ومشغوليات الجرائد والمجلات ، والأخبار والتعليق عليها . ومشغوليات التسلية وهى كثيرة تشمل الكبار والصغار . أنظر إلى مباريات الكرة مثلاً ، وتأمل كم تأخذ من وقت الناس ومن مشاعرهم ومن حماسهم ومن تعليقاتهم ... ! وهناك أيضاً المشغوليات الفكرية ، والإجتماعية ، ومشغوليات المشاكل وهموم العالم الحاضر ، والمشغوليات المالية والإقتصادية ...","حتى الأطفال تشغلهم برامج التلفزيون ، ورواياته ، وقد تعطلهم عن الكنيسة . والكبار أيضاً تشغلهم هذه البرامج وتعطلهم !",{h:"إن الله يطل من سمائه على العالم ، فيجده عالماً مشغولاً ."},"إنه عالم يجرى بسرعة ، لا يجد وقتاً يتوقف فيه ليفكر إلى أين هو ذاهب ... ! وهو أيضاً عالم صاخب ، كله أحاديث وضوضاء ومناقشات وانفعالات ... وأين الهدوء اللازم للعمل الروحى ؟ غالباً ما تبحث عنه فلا تجده ... !","حتى أن كثيراً من رجال الإكليروس الذين كرسوا أنفسهم للرب ، وأصبحوا « نصيب الرب » ، تجدهم أيضاً مشغولين عن الرب بأمور كثيرة ! إن حرب ( مرثا ) حرب قائمة ودائمة ، كما يبدو فى عالمنا الحاضر « أنت تهتمين وتضطربين لأجل أمور كثيرة ، والحاجة إلى واحد » (لو ١٠ : ٤١ ، ٤٢) . أما أنت يا إبن الله وصورته ، فينبغى أن يكون لك الطابع الروحى .",{h:"ليكن الله فى مقدمة مشغولياتك ، إن لم يكن شاغلك الوحيد ."},"عملك الروحى ، وصلتك بالله ، وحياتك الروحية ، ينبغى أن تكون باستمرار فى مقدمة مشغولياتك وفى توزيع وقتك ، وبعد ذلك كل شىء . ضع خلاص نفسك أولاً ،"],68:["وأبديتك أولاً . ثم رتّب باقى مسئولياتك مهما كانت أهميتها . وتذكّر فى ذلك قول الرب :",{h:"ماذا ينتفع الإنسان ، لو ربح العالم كله وخسر نفسه ! » (متى ١٦ : ٢٦) ."},"وإن خسرت نفسك ، ماذا تعطى عوضاً عن نفسك ؟! وكل أولئك الذين ماتوا وتركوا هذا العالم ، بماذا نفعتهم مشغولياتهم ؟! ولما تركوا هذه المشغوليات بموتهم ، هل ارتبك العالم ؟ كلا ، طبعاً . هذا العالم قال عنه الحكيم :",{h:"« الكل باطل وقبض الريح . ولا منفعة تحت الشمس » (جا ٢ : ١١) ."},"إبدأ صباحك بالله ، قبل أية مشغولية أخرى . ليكن الله « فى البدء » . قل له « يا الله أنت إلهى . إليك أبكر . عطشت نفسى إليك » (مز ٦٣ : ١) . ونظم وقتك ، بحيث لا تطغى أية مشغولية على الوقت الذى تقضيه مع الله . ولا تخرج من منزلك قبل أن تقوم بكل واجباتك الروحية . ولا تجعل شيئاً يفوق روحياتك مهما كان ربحه ، ومهما كانت قيمته أو أهميته ...",{h:"إن الشيطان دائماً يضخّم فى أهمية المشغوليات التى تعطلنا ."},"أو يضخم فى إغراءنا بهذه المشغوليات . ولكن لا يوجد مطلقاً ما هو أهم من الله فى حياتك . ولا يصح أن تضحى بعلاقتك مع الله من أجل أى شىء ، أو أى شخص ، أياً كان . هوذا الرب يقول « من أحب أباً أو أماً ... أو إبناً أو إبنة أكثر منى ، فلا يستحقنى » (متى ١٠ : ٣٧) . فكم هى أقل ، باقى الأمور !",{h:"لذلك إن أتتك مشغولية جديدة ، فكّر كثيراً قبل قبولها ."},"لأن الشيطان قد لا يكتفى بمشغولياتك الحالية التى تعطلك ، فيحاول أن يضيف إليها مشغوليات أخرى ، لكى ترتبك ... ويقدم لك فى كل يوم عروضاً ربما تكون سخية ، ليشغلك بها . أما أنت فكن محترساً . وضع روحياتك أمامك ، قبل كل المشغوليات ...","إن كانت المشغولية حيلة من حيل الشياطين ، لتبعدك عن الله ، فهناك حيلة أخرى أكثر مكراً ، وهى :",{h:"١٣ ـ الفهم الخاطىء لمحبة الله"},"لا يناقش أحد فى محبة الله لنا ، وفى أهمية محبتنا له . ولكن الشيطان قد يقدم"],69:["مفهوماً خاطئاً لهذه المحبة . بحيث أنه يمكن للإنسان أن يخطىء كما يشاء ، معتمداً على محبة الله ورحمته ومغفرته ، ومعتمداً على الخلاص الذى قدمه على الصليب !",{h:"وكأن محبة الله تقود إلى الإستهتار وإلى التراخى !"},"حاشا ، فإن الكتاب يقول « أم تستهين بغنى لطفه وإمهاله وطول أناته ، غير عالم أن لطف الله إنما يقتادك إلى التوبة . ولكنك من أجل قساوتك وقلبك غير التائب ، تذخر لنفسك غضباً فى يوم الغضب ... » (رو ٢ : ٤ ، ٥) . و يقول أيضاً « هوذا لطف الله وصرامته . أما الصرامة فعلى الذين سقطوا . وأما اللطف فلك إن ثبتّ فى اللطف ، وإلا فأنت أيضاً ستقطع » (رو ١١ : ٢٢) .",{h:"إن الشيطان يقدم محبة الله ، بأسلوب يضيع مخافته !"},"و يستغل إلى أبعد الإستغلال ـ بتفسير خاطىء ـ قول القديس يوحنا « لا خوف فى المحبة . بل المحبة الكاملة تطرح الخوف إلى خارج » (١يو ٤ : ١٨) . وهكذا يحاول أن ينزع مخافة الله من قلوب الناس باسم المحبة ، بينما الكتاب يقول « رأس الحكمة مخافة الرب » (مز ١١١ : ١٠) .","هنا وأستأذنكم فى طبع كتاب لى عن ( مخافة الله ) ، وعلاقة هذه المخافة بالمحبة . كنت قد جهزته منذ أكثر من عام ، وأعلنت عنه ، ثم أرجأت طبعه . وفى صميمى أرى نشره لازماً ، لأن كثيرين يستغلون محبة الله إستغلالاً خاطئاً يبعدون به عن الحرص الروحى ، وربما يقعون به فى اللامبالاة . وكل هذا من حيل الشياطين !!",{h:"حقاً إن الله محب جداً وغفور ، ولكنه أيضاً عادل وقدوس ."},"وإن كان الله غير محدود فى محبته ، فهو أيضاً غير محدود فى عدله ، وغير محدود فى قداسته . وقداسة الله لا تقبل الخطية . وعدله يعاقب عليها ...","هذا من جهة محبة الله لنا . وماذا عن محبتنا نحن لله ؟",{h:"الشيطان يصوّر محبتنا لله ، كمجرد مشاعر ، لا أكثر !"},"بينما محبتنا لله هى فى مفهومها السليم ، المحبة العملية « لا نحب بالكلام ولا باللسان ، بل بالعمل والحق » (١يو ٣ : ١٨) . ومن يحب الله ، لا يخالفه ، لا يعصاه ، لا يفعل ما يغضبه . ولذلك إرتبطت محبتنا لله بطاعته وحفظ وصاياه . والرب قد قال"],70:["« إن حفظتم وصاياى ، تثبتون فى محبتى » (يو ١٥ : ١٠) ، « إن أحبنى أحد يحفظ كلامى » (يو ١٤ : ٢٣) . وقد قال القديس يوحنا الحبيب « هذه هى محبة الله ، أن نحفظ وصاياه » (١يو ٥ : ٣) . ومحبتنا لله ، معناها أننا لا نحب العالم وكل شهواته . لأن الكتاب يقول « إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) . و يقول أيضاً « محبة العالم عداوة لله » (يع ٤ : ٤) .",{h:"فلا يخدعنك الشيطان ويقول لك : يكفى أن تحب الله ، وإفعل ما تشاء !"},"و يقصد تفعل ما تشاء من الأخطاء أو التقصيرات ! إن هذا فكر شيطانى ، يقصد به أنك لا تلوم نفسك على أخطائك ، وبالتالى تبقى فيها غير شاعر بأهميتها ! كما أنه يصور المحبة بمفهوم خاطىء ، كأنها مجرد مشاعر ، بلا عمل يدل عليها . وهو بهذا يهز القيم الروحية فى نظرك ...","حيلة أخرى من حيل الشياطين هى :",{h:"١٤ ـ هز المبادىء والقيم"},"الشيطان يشن على العالم الآن حرباً فكرية ، يريد بها أن يقدم مبادىء جديدة ومفاهيم جديدة ، تخدم أغراضه التى يريدها .",{h:"وفى هذه الحرب يحاول أن يهدم القيم والتقاليد ، وكل المسلّمات ."},"يشكك الناس فيها كلها . و يتهم كل من يتمسك بالتقاليد القديمة ، بأنه رجعى أو متخلف ، أو « دقة قديمة » غير متحضر !! كما لو كان القديم سُبّة ينبغى التخلص منها !",{h:"إنها ثورة من الشيطان على القيم ، وعلى العقائد أيضاً ."},"يريد الشيطان أن يكوّن تياراً عاماً خاطئاً ، كل من لا يسلك بمفاهيمه ، يهاجمه المجتمع و يتهكم عليه ! حتى أصبح كثير من المسلمات موضع جدل ونقاش ! ما هى الفضيلة ؟ وما هو الدين ؟ وما هى الحقوق وما هى الواجبات ؟ بل ما هى العلاقة بين الأب وإبنه فى مفهوم الحرية ؟",{h:"لقد أعطى الشيطان فى جيلنا مفهوماً منحرفاً للحرية ..."},"أراد فى هذا المفهوم أن يقنع الإنسان بأنه حرّ يفعل ما يشاء ، و يعتنق ما يشاء من"],71:["أفكار أو عقائد ، و ينشرها ، بلا أى قيد على الإطلاق ، مهما كانت آراؤه أو معتقداته أو تصرفاته خاطئة ، ومهما كانت خطرة على المجتمع ... !","والمعروف أن الحرية المطلقة لا يوافق عليها أحد ...",{h:"فالإنسان له أن يمارس حريته ، بحيث لا يعتدى على حريات وحقوق الآخرين ، وبحيث لا يسىء إلى المجتمع ، ولا يحطم ما فيه من قيم وأخلاقيات ."},"أما أن يمارس حرية بلا شروط ولا تحفظات ، فإن الحرية حينئذ ستكون مجالاً للإباحية والإستهتار ، ومجالاً للإنحراف الفكرى ، دون ضوابط !","وإن كان الله قد منح الإنسان حرية ، فإنه وضع له إلى جوار هذه الحرية وصايا ينفذها . كما أن الله سيحاسب الإنسان على مدى استخدامه لهذه الحرية ، و يعاقبه إن كان قد أساء بها إلى نفسه أو إلى غيره .",{h:"والحرية المطلقة التى يدعو إليها الشيطان ، لها أخطار سلوكية وعقائدية :"},"فالأخطار السلوكية نذكر كمثال لها الحرية التى أراد أن يسلك بها الهيبز والبيتلز وبعض الوجوديين الملحدين . بحيث لا مانع من أن يسيروا عراة فى الطريق العام ، أو أن يمارسوا الجنس بلا خجل ، ويخدشوا حياء المجتمع ... !","ومثال هذه الأخطاء أيضاً كل المناهج الإباحية ، وكل العثرات التى يصادفها المجتمع ، وتدفعه دفعاً إلى الفساد . ولا مانع عند الشيطان من ذلك ، باسم الحرية . وفى الواقع هذا خداع . فهناك مفهوم سليم للحرية من الناحية الروحية ...",{h:"فالحرية الحقيقية هى أن يتحرر الإنسان من الداخل ، من الأخطاء :"},"يتحرر من الشهوات والرغبات الخاطئة ، ومن العادات المسيطرة عليه التى تفقده حرية إرادته . أما إن حقق الإنسان رغباته ونزواته بكل ما فيها من انحراف ، واستمر مستعبداً لها ، خاضعاً للجسد وللمادة التى تقوده ، فماذا ستكون النتيجة إذن ؟!",{h:"حتماً إن العالم المستعبد لنزواته سيصل إلى كراهية الله الذى يقف ضد هذه النزوات . وهذه هى خطة الشيطان الماكرة !"},"أن يسعى إلى أن يكره الناس الله ، و يعتبرونه عدواً لهم ، لأنه يضيّع حرياتهم ، ويلغى وجودهم ، ويقف ضد رغباتهم ... ! وبدلاً من أن يصححوا رغباتهم ويصيروا أنقياء ، فإنهم يتمسكون بهذه الرغبات ويعادون الله بسببها !"],72:[{h:"والشيطان أيضاً ينشر حرية بلا قيد فى الفهم اللاهوتى ."},"بحيث أن كل إنسان يفسر الكتاب كما يشاء ، ويفهم منه ما يشاء ، وينشر ما يفهمه . وبهذا تتبلبل الأذهان وسط مفاهيم خاصة . وأمكن بهذه الحيلة أن توجد مئات المذاهب داخل المسيحية . سببها هذه الحرية الخاطئة التى يقولون فيها إن كل إنسان له حرية الإعتقاد دون الخضوع لسلطة دينية !!",{h:"إن الكنيسة لها إيمان واحد . وليست هى مجموعة متناقضات ."},"هذا الإيمان الواحد علّم به الكتاب المقدس ، فقال « رب واحد ، إيمان واحد » (أف ٤ : ٥) . وللجمهور المؤمنين « قلب واحد ، ونفس واحدة » (أع ٤ : ٣٢) . والكنيسة هى جسد واحد ، مهما تعددت أعضاؤه ، وهذا الجسد رأسه المسيح (أف ٥ : ٢٣) . ومادام رأسها هو المسيح ، فباستمرار لها فكر المسيح (١كو ٢ : ١٦) . وفكر المسيح واحد لا تناقض فيه .",{h:"فماذا إذن عن حرية الإعتقاد ؟ ما حدودها ؟"},"نحن لا نعارض أن كل إنسان له حرية الإعتقاد . ومحال أن يعتقد شيئاً على الرغم منه . فالذى له اعتقاد الكنيسة يصير عضواً فى الكنيسة . ومن ليس له اعتقادها يبق خارجاً عنها ، بكامل حريته . ويبق للكنيسة إيمانها الواحد .","والكنيسة لا تعتدى على حرية أحد ، ولا ترغمه على الإيمان . ولكن :",{h:"ليس لأحد أن يدعى عضويته فى كنيسة لا يؤمن بمعتقداتها ."},"وهنا يكون دفاع الشيطان عن الحرية لا معنى له . فالحرية موجودة . ولكن كل من يقبل أن يكون عضواً فى كنيسة عليه أن يلتزم بعقائدها . وهذا أمر بدهى . فإن لم يلتزم بعقائدها ، يكون قد خرج منها بإرادته . و ينطبق عليه قول القديس يوحنا الحبيب « منا خرجوا . ولكنهم لم يكونوا منا . لأنهم لو كانوا منا ، لبقوا معنا » (١يو ٢ : ١٩) .","نقول هذا ، لأنه باسم حرية الإعتقاد ، نجد أنه فى بعض كليات اللاهوت ، فى جهات كثيرة من العالم ، يدرس المحاضرون ما يشاءون دون الإلتزام بعقيدة الكنيسة التى ينتمون إليها ، أو التى يدرسون عقائدها . فيدخل الأستاذ إلى المحاضرة ، ويقول الذى يعجبه !",{h:"وهكذا وُجد فى بعض الكليات أساتذة لاهوت ملحدون !!"}],73:["وأفلح الشيطان ، باسم الحرية الزائفة ، أن يضرب ضربته و ينجح !!","أما الكنيسة المقدسة الجامعة الرسولية ، الملتزمة « بالإيمان المسلّم لنا من القديسين » (يه ٣) ، فلم تسمح بهذا مطلقاً ، بل كانت تحكم بحرم المبتدعين والمنحرفين وإخراجهم ، لكى تبقى الكنيسة بإيمان واحد ، تسلمه سليماً للأجيال المقبلة . وهكذا قال القديس بولس الرسول فى قوة :",{h:"« إن بشرناكم نحن ، أو ملاك من السماء ، بغير ما بشرناكم به ، فليكن أناثيما » (غل ١ : ٨) ."},"وقال القديس يوحنا الحبيب « إن كان أحد يأتيكم ، ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) . إنه حزم شديد من أكثر الرسل حديثاً عن المحبة .","لذلك كانت الكنيسة حريصة على الإيمان ، تدافع عنه ضد أى إنحراف . ولا تقبل مطلقاً أى إنحراف إيمانى يدخل إلى الكنيسة باسم الحرية ! لينشر أفكاراً خاصة ... !",{h:"لذلك فإن الشيطان لا يقبل سلطان الكنيسة ، ويحارب السلطان الكهنوتى ."},"خذوها قاعدة ثابتة على مدى أجيال التاريخ : كل من ينحرف فى عقيدته ، إذا لم يتب ، لابد أن يحارب السلطان الكهنوتى ، أى يحارب القوة التى تحكم على إنحرافه بسلطان من الله (متى ١٨ : ١٨ ، يو ٢٠ : ٢٣) .","ولما كان الشيطان ينشر أفكاره وانحرافاته فى كل ميدان ، وليس فى محاربة الكنيسة وحدها ، لذلك فقد لجأ الشيطان إلى حيلة معروفة وهى :",{h:"الوقوف ضد السلطة عموماً ، فى كل مجالاتها ..."},"و يقصد طبعاً أن يقف ضد كل سلطة سوف لا تقبل الإنحراف أو الخطأ ، بل تحاربه وتمنعه أو تعاقبه ، وذلك لكى يستمر الخطأ ...","فهو يحارب سلطة الأب فى الأسرة ، دفاعاً عن شخصية الأبناء !","وهو يحارب سلطة المعلم فى الكلية أو المدرسة ، لخلق جيل قوى !","وهو يحارب سلطة الدولة ، باسم الديمقراطية وحقوق الشعب !","وهو أيضاً يحارب سلطة الله ، لكى يشعر الإنسان بوجوده هو !","و بالتالى يحارب سلطة الإكليروس ، كوكلاء الله على رعيته (تى ١ : ٧) ."],74:[{h:"الشيطان لا يريد وجود رقيب يضبط الأخطاء ويقوّمها ."},"بينما الله يقول « قد جعلتك رقيباً ... فاسمع الكلمة من فى ، وانذرهم من قبلى » (حز ٣ : ١٧) . يريد الشيطان أن تبقى كل الأمور ، بلا ضابط ، بلا رقيب ، بحرية طائشة ، كما يقول الكتاب عن عهد القضاة : ولم يكن ملك فى إسرائيل فى تلك الأيام . وكان كل واحد يفعل ما يحسن فى عينيه » (قض ١٧ : ٦) ... كل واحد يعمل ما يعجبه ، وينشر ما يعجبه من آراء ومعتقدات . وإن وقفت ضده سلطه يهاجمها ، بل يهاجم مبدأ السلطة عموماً !! وهذه خطة الشيطان ...","ومن ضمن خطط الشيطان أيضاً :",{h:"١٥ الإنقياد للتيار العـــام"},"قد يكون التيار العام كله خاطئاً ، ويدعوك الشيطان أن تخضع لهذا التيار ، وتكون مثله ! وقد يهمس فى أذنيك :",{h:"الكل هكذا ... لماذا تشذ أنت ، ويكون لك أسلوب خاص ؟!"},"والجواب أننا نتبع الحق أياً كان موقعه ، فى جانب الأغلبية أو الأقلية . فإن كانت أغلبية الناس فى خطأ ، فإننا لا نتبعها . وهكذا فعل أبونا نوح : كانت كل الناس فى عهده أشراراً ، وكان هو وحده البار مع أسرته .",{h:"ما أسهل أن تكون الغالبية كلها مخطئة ، أو الجيل كله ."},"الغالبية فى وقت الصلب كانت مخطئة وصاحت أصلبه أصلبه (لو ٢٣ : ٢١) . بل الجيل كله ، قال عنه السيد المسيح « جيل فاسق وشرير » (متى ١٢ : ٣٩) . وغالبية الناس أيام آخاب الملك ، كانت تعبد الأصنام ، إلا سبعة آلاف ركبة فقط من بين مئات الآلاف (١مل ١٩ : ١٨) . وفى أيام موسى النبى ، حكم الرب على الشعب كله بأنه متمرد وصلب الرقبة ، ولم يدخل منه إلى أرض الموعد إلا إثنان فقط هما يشوع بن نون ، وكالب بن يفنة (عد ١٤ : ٢٠ - ٣٠) .","وإن رجل الله الثابت فى وصاياه ، هو الذى ينشد قائلاً :",{h:"سأطيع الله حقّ لو أطعت الله وحدى"}],75:[{h:"ولكن الشيطان يدفع دفعاً فى التيار العام بطرق شتى :"},"أحياناً يجعل الناس يجارون الخطأ من باب المجاملة ، أو من باب الخجل ، أو من باب التقليد ، أو خوفاً من تهكم الناس ومن تعييرهم ، أو نتيجة لضغط الظروف الخارجية وإلحاح الآخرين . أو أن يقول لهم الشيطان « هذه المرة فقط ، ولن تتكرر » ! ثم تتكرر طبعاً ... أو أن شخصاً قد يجارى التيار خضوعاً لسلطة أقوى منه أو خضوعاً لرئاسة ... وقد يجارى التيار جهلاً . وقد يقول له الشيطان :",{h:"هل من المعقول أن يكون كل الناس مخطئين ، وأنت الوحيد المصيب ؟!"},"هل من المعقول أن كل هؤلاء لا يعرفون أين يوجد الخير والحق ، وأنت الوحيد الذى تعرف ؟! إتضع يا أخى ... (و يتضع) الأخ ! و ينجرف فى التيار .","وقد يسير فى التيار نتيجة لصداقة أو صحبة خاطئة إستطاعت أن تؤثر عليه وتجذبه إلى طريقها ، كما سار سليمان الحكيم فى طريق نسائه (١مل ١١ : ٤) .",{h:"وقد يخضع الإنسان للتيار نتيجة لضعف شخصيته ..."},"وهكذا لا يقدر على المقاومة ، أو يقاوم قليلاً ولا يثبت . والعجيب أن أهل العالم يكونون أقوياء جداً فى دفاعهم عن طريقهم الخاطىء ، وفى سخريتهم من أولاد الله الذين لا يجارونهم . ويظلون ينعتونهم بشتى النعوت ، حتى يضعف هؤلاء ويخضعون ... ! يا للأسف ...","إن أولاد الله يجب أن يكونوا أقوياء فى مبادئهم ، ثابتين راسخين ، لا يتزعزعون أمام تهكمات الأشرار . وليتذكروا قول الكتاب :",{h:"« لا تشتركوا فى أعمال الظلمة غير المثمرة ، بل بالحرى وبخوها » (أف ٥ : ١١) ."},"فإن لم يستطيعوا أن يوبخوا أعمال الظلمة ، فعلى الأقل لا يشتركون فيها ... وليكن لهم أسلوبهم المميز فى الحياة ، الذى قال عنه القديس يوحنا الحبيب « بهذا أولاد الله ظاهرون ، وأولاد إبليس (ظاهرون) » (١يو ٣ : ١٠) . وكما قيل « من ثمارهم تعرفونهم » (متى ٧ : ١٦) . وقيل أيضاً « لغتك تظهرك » (متى ٢٦ : ٧٣) . وقد قال القديس بولس الرسول عن عدم الخضوع للتيار العام :",{h:"« لا تشاكلوا هذا الدهر » (رو ١٢ : ٢) ."},"أى لا تصيروا شكله . لا تصيروا مثله . لأن شكلكم معروف ، فأنتم صورة الله"],76:["ومثاله . وما أجمل قول الله فى ذلك « نعمل الإنسان على صورتنا ، كشبهنا » (تك ١ : ٢٦) . فكيف تتنازل عن صورتك الإلهية ، لتصير كصورة عالم ساقط منحرف .",{h:"إن دانيال والثلاثة فتية ، كانوا أقوى من التيار العام ."},"ليس فقط فى انفرادهم عنه بعبادة إلههم ، حتى لو أدى الأمر أن يلقى دانيال فى جب الأسود ، و يلقى الثلاثة فتية فى أتون النار ... بل حتى منذ بدء تعيينهم فى قصر الملك ، إذ رفضوا الطعام الملكى ، ولم يأكلوا مع سائر الفتيان . وما أجمل قول الكتاب « أما دانيال فجعل فى قلبه أن لا يتنجس بأطايب الملك ولا بخمر مشروبه » (دا ١ : ٨) .","صمم دانيال والثلاثة فتية على هذا الأمر ، مع أنهم كانوا أسرى حرب ، وتحت سلطان ، يخدمون وهم عبيد فى قصر الملك . ولكن قلوبهم وأرواحهم كانت حرة طليقة ، لا تخضع للتيار العام ، بل لمشيئة الرب .",{h:"لذلك كن شجاعاً ، وصاحب مبدأ ، وقاوم التيار العام إذا أخطأ ."},"لا تخضع للشيطان وكل نصائحه ، بل وكل مخاوفه . وارفض الخطأ مهما رأيت كباراً يسيرون فيه ! وإن وجدت الذين يسيرون فى طريق الحق قليلين ، فلا يضعف قلبك . فهذه هى القلة المختارة . وقد قال الرب « ما أضيق الباب وأكرب الطريق الذى يؤدى إلى الحياة . وقليلون هم الذين يجدونه » (متى ٧ : ١٤) . واعلم أنه :",{h:"لو وقعت الغالبية فى الخطأ ، فهذا لا يجعل الخطأ صواباً ."},"الخطأ هو الخطأ . ووقوع الأغلبية فيه لا يبرره . والمعروف أن الصواب طريقه صعب ، وقد لا يستطيعه كل الناس ، بل القلة المتميزة بمبادئها . فإن وجدت الشيطان قد ألقى الكل فى الخوف ، لا تخف أنت . وإن وجدت الغالبية تعلمت التملق والرياء ، فلا تكن أنت كذلك . وإن وجدت الكل قد استعملوا أساليب العالم فى لهوه وترفيهاته ورفاهيته وأزيائه ، فلا تكن كذلك . وإن وجدت لغة الناس قد تغيرت ، وأصبحت ليست كذى قبل ، فلتكن أنت بنفس لغتك الأولى .","وإن ضعفت مقاومتك للتيار ، فقل مع المرتل فى المزمور :",{h:"نجنا يارب من هذا الجيل ، وإلى الأبد آمين » (مز ١٢ : ٧) ."},"والرب قادر أن ينجيك من التيار العالم ، فلا يجرفك .","حيلة أخرى من حيل الشياطين لإسقاط أولاد الله ، وهى :"],77:[{h:"١٦ الإغـــراءات"},"منذ الخطية الأولى ، والشيطان يقدم إغراءات ليسقط ضحاياه . وكان أول إغراء قدمه لأبوينا الأولين هو « تصيران مثل الله ، عارفين الخير والشر » (تك ٣ : ٥) . واستمر يقدم إغراءات للبشر « شهوة الجسد ، وشهوة العين ، وتعظم المعيشة » (١يو ٢ : ١٦) . وقدم هذه كلها لسليمان الملك (جا ٢ : ١ - ١٠) .","وعلى الجبل قدم للسيد المسيح ثلاثة إغراءات : الخبز ، حمل الملائكة له على أجنحتها ، وكل ممالك الأرض ومجدها (متى ٤) . ورفض السيد كل هذا ، وأخزى الشيطان وطرده .",{h:"إن إغراءات الشيطان لا تسقط إلا قلباً يميل إليها ..."},"أو يمكن أن يميل إليها ... أما القلب القوى فإنه يرفض تلك الإغراءات ، أو قل إنها لا تغريه . إن الملكة إيزابل أرادت أن تؤثر على ياهو الملك وتغريه ، كما كان آخاب الملك تحت سيطرتها من قبل « فكحلت بالإثمد عينيها ، وزينت رأسها » (٢مل ٩ : ٣٠) . أما ياهو ، فلم يغره هذا الجمال الزائف ، بل احتقره وأمر بقتلها ...",{h:"والشيطان أحياناً ينتقى إغراءاته ، وأحياناً يجس النبض ..."},"يجس النبض لكى يرى هل محاربه يضعف أمام هذا الإغراء أم لا . فإن وجده لا يهتم ولا يتأثر ، يجرب إغراء آخر ، كما فعل مع السيد المسيح ، فوجده قوياً أمام كل إغراءاته . ومن خبرة الشيطان الطويلة ، أنه ينتقى لكل نوع من الناس ما يرى أنه يناسبه ...",{h:"وقد يغرى بالشىء الذى يرى الشخص محتاجاً إليه ."},"كما قدم للسيد المسيح تجربة الخبز ، حينما قيل عنه إنه « جاع أخيراً » (متى ٤ : ٢ ، ٣) . وقدم تجربة العرافة لشاول الملك فى الوقت الذى رآه فيه محتاجاً الى مشورة ولم يجد (١صم ٢٨ : ٤ - ٧) . وقدم تجربة العجل الذهبى لبنى إسرائيل فى وقت رآه مناسباً ، وقد غاب عنهم موسى النبى ، وغاب معه الإرشاد الروحى وهيبة النبوة (خر ٣٢ : ١ - ٤) ."],78:[{h:"والشيطان يقدم الإغراء قوياً مؤثراً ، يمنع التوبة والعمل الروحى ."},"فإن وجد إنساناً قد عزم على التوبة بكل عزم وقوة ، يقدم له خطية كان يشتهيها منذ زمن ، ويبحث عنها فلا يجدها . فيضعها أمامه فجأة تسعى بنفسها إليه من حيث لا يدرى ، فيغريه بها ليسقط ... وإن كان إنسان قد أبطل قراءة كتب معينة معثرة ، لا مانع فى هذا اليوم من أن يرسل إليه صديقاً ، يهديه كتاباً كان هذا (الضحية) يشتهى شراءه شهوراً طويلة ولا يجده فى السوق . فيجد نفسه أضعف من الإغراء ، فيقرأ ويسقط .","وإن تاب شاب عن خطية الزنا ، يجد خطية سمت إليه سمياً .",{h:"بحيث يظن المسكين أنها فرصة لا تعوّض . ويقول له الشيطان :"},{h:"لا تترك هذه الفرصة ، ويمكن أن تتوب بعدها ... !"},"وهكذا إن وجد الشيطان إنساناً يبعد عن الخطية ، يأتى إليه بأكبر إغراءات للخطية بالنسبة إليه . لأنه يعرف تماماً أين يوجد الجرح الذى يدوس عليه فيؤلمه ... فإن ثبت ووجدت خطية تسعى إليك فى إغراء عجيب ...",{h:"لا تقل هذه فرصة . بل قل : هذا بلا شك فعل الشيطان ."},"ليس هذا شيئاً طبيعياً ، ولا هو أتى عن طريق الصدفة . بل هى خطة مدبرة محكمة من عمل الشيطان . ومبارك هو الرب الذى كشفها لى لأهرب منها ... وكما قال الراهب القديس عبد المسيح الأثيوبى المتوحد ببرية شيهيت « فغ يا أباقى فغ » ...","نقطة أخرى بارزة فى حرب الشياطين هى :",{h:"١٧ التخـديـر"},"حينما يكون الإنسان متيقظاً ومتنبهاً لخلاص نفسه ، صاحياً عقلاً وروحاً ، فإنه من الصعب أن يسقط ... ولذلك قال أحد القديسين : إن الخطية تسبقها إما الشهوة ، أو الغفلة ، أو النسيان . فحالة الغفلة والنسيان ، هى تخدير من الشيطان للإنسان ...",{h:"فينساق إلى الخطية ، كأنه ليس فى وعيه !"},"ولذلك حسناً قيل فى توبة الإبن الضال إنه « رجع إلى نفسه » (لو ١٥ : ١٧) ."],79:["وكلمة (رجع) تعنى أنه لم يكن فى وعيه ، أو على الأقل لم يكن فى كامل وعيه ، طوال فترة الخطية . ولهذا لما رجع إلى نفسه بدأ يفكر بأسلوب آخر ، يختلف عن أسلوبه فى الخطية .",{h:"الشيطان يخدر الإنسان بحيث ينسى كل شىء ، ما عدا الخطية ."},"تكون كل حواسه وأفكاره ومشاعره مركزة فى الخطية وحدها . أما كل ما عداها فلا يحس به الإنسان اطلاقاً ، وكأنه قد نسيه تماماً تماماً ...","ينسى أنه صورة الله . ينسى الوصية . ينسى نتائجها . ينسى وضعه الروحى . ينسى تدرايبه الروحية . ينسى عبادته واحتراسه . ينسى وعوده لله وتعهداته ونذوره . ينسى إحترامه . بل قد ينسى أنه صائم ، أو أن هذه أيام مقدسة . و ينسى عقوبات الله وإنذاراته ... يكون كأنه مخدر تماماً . والشيطان قد خدره بالخطية ، بحيث أصبح لا يعى شيئاً غيرها ...",{h:"ولا يفيق إلا بعد السقوط ، حينما يكون كل شىء قد انتهى ."},"هكذا كان داود النبى مخدراً ، حينما أخطأ ، وجرته الخطية إلى خطية . ولم يفق من هذا التخدير إلا على صوت ناثان النبى يقول له « أنت هو الرجل » (٢صم ١٢ : ٧) . حينئذ فقط أفاق ، وأحس كم كانت أعماق خطيئته !","لعل قايين كان أيضاً مخدراً حينما قام على أخيه وقتله . ولم يفق إلا على قول الرب له « أين هابيل أخوك ؟ » (تك ٤ : ٩) . حينئذ فقط أفاق ، وشعر ببشاعة ما قد فعل ونتائجه وقال « ذنبى أعظم من أن يحتمل » (تك ٤ : ١٣) .",{h:"قد يفيق الإنسان بعد الخطية مباشرة ، وربما بعد مدة طويلة ."},"الإبن الضال لم يفق من تخديره ، إلا بعد أن أنفق كل ماله واعتاز ، وشعر بسوء حالته (لو ١٥ : ١٦ ، ١٧) . والغنى الذى عاصر لعازر المسكين لم يفق إلا فى الجحيم . ولكن هناك من يفيق بعد الخطية مباشرة ، مثل القديس بطرس الذى بعد إنكاره بكى بكاءً مراً (متى ٢٦ : ٧٥) . ويهوذا لم يفق إلا بعد فوات الفرصة .",{h:"هناك من يفيق من تخديره فيتوب . وهناك من يفيق فييأس ."},"الإبن الضال ، وداود النبى ، وبطرس الرسول ، لما أفاقوا تابوا ."],80:["أما يهوذا فلما أفاق ، أسلمه الشيطان إلى اليأس « فمضى وخنق نفسه » (متى ٢٧ : ٣ - ٥) . ومات فى خطيئته فهلك ...",{h:"لذلك هناك نصيحتان أقدمهما لك ، إذا خدّرك الشيطان :"},"الأولى ، أن تفيق بسرعة . كما قال المرتل « أنا أستيقظ مبكراً » (مز ٥٧ : ٨) . واحذر من أن تستمر مخدراً بالخطية إلى أن تصبح عادة ، أو يصير من الصعب عليك أن تفيق ، أو أن تصحو من تخديرك بعد أن تكون قد وصلت إلى نتائج سيئة جداً ...","النصيحة الثانية : هى أنك حينما تفيق ، إنما تفيق إلى توبة حقيقية وسريعة ، وليس إلى يأس أو صغر نفس ... واستغل الندم والإنسحاق لنفعك الروحى .","نقطة أخرى أقولها لك فى حروب الشياطين وهى :",{h:"١٨ تحـويـل الدين الى فلسـفة"},{h:"السيد المسيح أراد أن يكون الدين روحاً وحياة ."},"ولذلك قال « الكلام الذى أكلمكم به هو روح وحياة » (يو ٦ : ٦٣) . نفهم روح الكلمة ، ونحولها إلى حياة فينا . وهكذا يصير الدين طريقاً لتنقية القلب ، ومرشداً إلى الإلتصاق بالله ، ولكى تكون للإنسان حياة أبدية . ولعل هذا ما أراده الرب بقوله « أتيت لتكون لهم حياة ، وليكون لهم أفضل » (يو ١٠ : ١٠) .",{h:"ولكن الشيطان يريد أن يحول الدين إلى جدل ومناقشات ..."},"يريد أن العقل يحل محل الروح ، والجدل يحل محل الممارسة . وتصبح الحياة الدينية هى مجرد عقلانية . وكأن المسيحية هى فلسفة تُدرّس وتُحلّل ، وتصبح مجرد منهج للتعليم ، وليس حياة نحياها . والعقل لا يضر الشيطان فى شىء إن بقى مجرد عقل لا تحركه الروح . وهذا ما يريده الشيطان ...",{h:"بودى أن أترجم لكم كتاب ( ضد الأكاديميين ) للقديس أوغسطينوس ."},"إسم كتابه Contra Acadimos ليتنى أستطيع أن أترجم لكم بعض فقرات منه كمثال . والمعروف عن القديس أوغسطينوس أن له منهجاً روحياً عميقاً .",{h:"والمنهج العقلى الذى يريده الشيطان ، حاربه القديس بولس الرسول ."}],81:["وهذا واضح جداً فى الأصحاحين الأولين من رسالته الأولى إلى أهل كورنثوس ، فهو يقول « أتيت ليس بسمو الكلام أو الحكمة » ، « وكلامى وكرازتى لم يكونا بكلام الحكمة (الإنسانية) المقنع ، بل ببرهان الروح والقوة » (١كو ٢ : ١ ، ٤) ، « لا بحكمة كلام ، لئلا يتعطل صليب المسيح » (١كو ١ : ١٧) . فالتركيز على صليب المسيح عمل روحى ، يعطله الإنشغال بالفكر والجدل .",{h:"إن الهرطقات كانت لعبة شيطانية عقلية لتعطيل العمل الروحى ."},"العمق الروحى الذى عاشته الكنيسة فى عصر الإستشهاد ، طوال القرون الثلاثة الأولى ، وفى أوائل القرن الرابع ، والعمق الروحى الذى كان قد بدأ بالرهبنة منذ أواخر القرن الثالث ، وازدهر فى القرنين الرابع والخامس ، بكل ما فيه من حب لله ، وبكل ما فيه من الإرشاد الروحى من أقوال الآباء ... كل ذلك أثار حسد الشيطان ، فأراد أن يشغل العالم بالجدل والنقاش على مدى قرنين طويلين ... وهكذا ظهرت هرطقات أريوس ، وأبوليناريوس ، وسابيليوس ، ومقدونيوس ، ونسطور ، وأوطاخى ، وغيرهم ... كل ذلك فى فترة مركزة جداً دوّخت العالم فكرياً . وأصبح النقاش حول لاهوت الإبن وطبيعته يدور فى الشوارع حتى بين العامة . وألهم الشيطان مفاهيم للهراطقة وتفاسير لآيات الكتاب . وانشغل آباء الكنيسة فترة طويلة بالرد على البدع والهرطقات .",{h:"والشيطان يتمنى أن يشغلنا طول العمر بالحوار الفكرى والردود ..."},"ومازالت هذه هى خطته ، يرسل لنا فى كل جيل من يحاول أن يحوّل الدين إلى نقاش وجدل وفكر وحوار وآراء وردود ... مريداً بهذا أن يعطل العمل الروحى من جهة ، ويثير الإنقسام والخصومات من جهة أخرى ، ولو باسم الدين ، وباسم الدفاع عن العقيدة ، وتصبح الكنيسة مذاهب وشيعاً ، ويفرح الشيطان بهذا . من يسقطون فى الهرطقات مكسب له ، ومن يتعبون من الشكوك مكسب آخر . ومن ينشغلون عن العمل الروحى بهذه السلبيات وإضاعة جهودهم فى الردود ، كل ذلك مكسب أيضاً .",{h:"ونشكر الله أن الآباء الذين ردوا على الهرطقات كانوا روحيين ."},"تقرأ مثلاً كتاب (تجسد الكلمة) للقديس أثناسيوس فتجده كتاب روح كما هو كتاب لاهوت وعقيدة ... ولكن كثير ين انشغلوا بالفكر ... ونحن نشكر الله أيضاً أن حركة الهرطقات والرد عليها فى القرنين الرابع والخامس ، سارت معها جنباً إلى جنب"],82:["حركة الرهبنة وإرشادها الروحى . فأقامت توازناً مع الدوامات الفكرية .","كان الرد على الهراطقة لازماً جداً لحفظ الإيمان . ولكن كان الإنشغال بذلك تعطيلاً للكنيسة . ولكن الله حوّله إلى خير بتعميق الإيمان فى القلوب وبإزالة الشكوك .",{h:"وحتى فى الروحيات البحتة ، يحاول الشيطان تحويلها إلى فلسفة ."},"يمكن أن يجعل حتى الصلاة مثلاً منهجاً فكرياً له قواعده العقلية . وكذلك يمكن أن يفعل ذلك بالرهبنة ويحولها إلى مدارس تتصارع فكرياً بين الوحدة والعمل ، والتأمل والخدمة . ويتحول الأمر إلى نقاش وإلى صراع ، يسر به الشيطان ويفرح !",{h:"حتى صلاة « أبانا الذى » يحولها إلى صراع حول الترجمات ."},"وإذا بالناس وهم يصلون يقول أحدهم « خبزنا كفافنا » ويصيح آخر بصوت عال « الذى للغد » . وتتصارع الترجمات وتتبلبل الأفكار ، وبدلاً من التأمل فى الصلاة يدور الجدل والنقاش أية الترجمات أصح !!","ونفس الوضع قد يدور فى القداس الإلهى أيضاً : يريد الشيطان أن يقضى على التأمل والروحيات ، فيثير حرباً من الترجمات .",{h:"وفى داخل الكنيسة ما أسهل أن يثير أفكاراً جديدة ..."},"يجعل البعض يشغف بالجديد ، فيقدم تفسيراً جديداً ، أو معتقداً مغايراً للمفاهيم العامة . ويقول صاحبه وناشره إن كل من سبقوه قد أخطأوا . وبدلاً من استخدام الفكر الدينى للحب ولنقاوة القلب ، يحوله الشيطان إلى صراع وإلى حرب بين المتدينين بسبب الفكر والفهم الخاص ، وادعاء كل فريق أنه يدافع عن العقيدة ! وأنه الوحيد الصادق فى إيمانه ...","أو على الأقل يعطل الروحيين عن عملهم بالإنشغال بالسلبيات والرد عليها . وإن لم يفعلوا ذلك ، يملأ الجو شكوكاً وبلبلةً .","حرب أخرى من حروب الشيطان وهى :",{h:"١٩ فتـرة راحـة من الخطيــة"},"إنه لا يحارب باستمرار ، إن وجد للحرب الدائمة أضراراً ..."],83:["فهو قد يبطل الحرب فترة ، ليس إشفاقاً منه على من يحاربه ، وإنما لكى يجره إلى التهاون وعدم الحرص ، ثم يعود إليه بأسلوب أكثر قساوة فيسقطه . وبهذا يشعره على الدوام بعدم ثقة فى القدرة على حياة البر ، ويقنعه بأنه مهما تاب ، لابد سيعود إلى الخطية مرة أخرى .",{h:"أو قد يبعد الخطية عنه فترة ، ليشتاق إليها ."},"ربما كثرة ممارسة الخطية تولد الملل منها وكراهيتها . فتكون خطة الشيطان أن يبعدها فترة . ثم يعيدها بعد حين بأسلوب أكثر تشويقاً ، أو أكثر حدة ، أو بأسلوب غير متوقع ، لكى يسهل السقوط فيها .",{h:"وهكذا يستخدم أسلوب المنح والمنع فى المحاربة بالخطية ."},"إنه بهذا يلعب بمشاعر النفس البشرية ... ويجعلها باستمرار فى حالة عدم استقرار ، ما بين علو وهبوط . وأولاد الله يدفعهم ذلك إلى مزيد من الحرص والتدقيق ، وإلى مزيد من الإتضاع . ولكن الشيطان يريد أن يجعلهم فى جو من الخوف وعدم الثقة ، والشعور بأن البر فوق مستواهم .","ثم يتدرج من الهجوم الفكرى إلى هجوم عام يقول فيه : إن المسيحية ديانة سمو وكمال . ولكنه سمو غير عملى ، ليس فى مستوى قدرة الإنسان أن يناله . ويخفى فى كل ذلك الأمثلة التى قدمتها لنا سير الأبرار فى كل زمان ...","حرب أخرى من حروب الشيطان هى :",{h:"٢٠ الفضـائل الظـاهرة الجسـدية"},"يغرى الإنسان بالفضائل الظاهرة الجسدية ، بدلاً من الفضائل الروحية الخفية .","ونقصد بالظاهرة ، الظاهرة لصاحبها ، وليس فقط الظاهرة للآخرين . وهذه الفضائل الظاهرة يمكن أن يلقيه بها فى الإعجاب بالنفس والغرور ، أو يلقيه فى احتقار الآخرين الذين لم يصلوا إلى نفس المستوى .",{h:"وهذه الحرب يحارب بها الرهبان كما يحارب بها العلمانيين أيضاً ."}],84:["فإذا بدأ الراهب جهاده ، يجعله الشيطان يهتم بالصوم ، وبالمطانيات ، والسهر ، والصمت ، والإعتكاف . وكلها أمور ظاهرة ... وفى نفس الوقت لا يهتم بفضائل القلب من الداخل مثل الفرح والسلام والنقاوة والوداعة والهدوء ... الخ",{h:"وفى الصوم يحارب بالأسلوب الجسدانى ويترك الروحى ."},"فيجعل كل اهتمام الصائم بفترة الإنقطاع وكم تكون ، وبنوع الأكل ووجوب الإمتناع عن بعض مشتهيات ، والإقلال من كمية الماء التى يشربها . وكل هذه أمور جسدية ، ولا يشغل نفسه أبداً بالفضائل الروحية التى فى الصوم مثل : انسحاق القلب ، وسمو الروح ، وضبط النفس فى كل الأمور .","والشيطان يعرف أن مثل هذا الصوم الجسدى قد لا يفيد الإنسان روحياً . ويستغل هذا الأمر فيا بعد ، لكى يبعده عن الصوم كلية .",{h:"ونفس الوضع بالنسبة إلى المطانيات ."},"المهم هو عددها ، ونمو هذا العدد باستمرار . أما أن الإنسان فيا يسجد ، تلصق بالتراب نفسه (مز ١١٩) كما تلصق رأسه بالتراب ، فهذا ما لا يجعله يفكر فيه ! كذلك لا يجعله يهتم بالمشاعر الروحية التى تصحب المطانيات ، وما تصحبها أيضاً من صلوات ... وكل ما يقصده هو أن تتحول هذه المطانيات - على الرغم من كثرة عددها - إلى عمل جسدانى يمكن أن يرهقه دون أن يفيده ، كما يلقيه به فى المجد الباطل !",{h:"والوحدة أيضاً يهتم بمظهرها وليس بروحياتها ."},"كإنسان يحيا الوحدة كطقس ، وليس كمنهج روحى يتميز بفضائل معينة ، فيها يكون الفكر منفرداً بالله فى حب ، ويكون القلب قد مات كلية عن العالم . ولكن كثيراً ما يجعل الشيطان هذا المتوحد يقنع بمجرد سكنى المغارة والبعد عن الدير ، ويملأ قلبه بالكبرياء والسخط على الدير ومن فيه ، دون الإهتمام بالعمل الروحى داخل المغارة . وكما قال ماراسحق « يوجد إنسان قد يسكن فى القلاية خمسين سنة وهو لا يعرف طريقة الجلوس فى القلاية » .",{h:"وما ينطبق على الوحدة ، ينطبق على الصمت أيضاً ."},"فالمفروض أن هدف الصمت ، هو أن الإنسان يبعد عن أخطاء اللسان ، ويعطى نفسه فرصة للحديث مع الله . أما أن يقنع الإنسان بمجرد الصمت ، فهذا عمل جسدانى"],85:["ظاهر . إذ أن كل الأخطاء التى يقع فيها بلسانه ، يمكن أن يقع فيها بفكره مثل الإدانة والغضب والشتيمة والحدة ... الخ . فإن كان قلبه خالياً فى نفس الوقت من الحديث مع الله . يكون صمته بعيداً عن العمل الروحى .",{h:"وبنفس الطريقة قد يقنع الإنسان باختيار البتولية ."},"ويظن أن البتولية هى ذلك العمل الظاهر الذى هو عدم الزواج . وقد تكون نفسه غير بتولة ، وأفكاره دنسة . والعنصر الإيجابى فى البتولية الذى هو توجيه الحب كله نحو الله ، قد لا يكون موجوداً أيضاً . وهكذا يكون قد أخذ من البتولية ظاهرها ، دون روحها ودون فاعليتها داخل القلب ...",{h:"المفروض فينا أن نهتم بالعمل الروحى الداخلى ، فهو الأهم ."},"والرب قد قال « يا إبنى أعطنى قلبك » (أم ٢٣ : ٢٦) . فيبدأ الإنسان بنقاوة القلب ، وبمحبة الله ، وبالفضائل الداخلية . ثم من القلب النقى تخرج الصلاة النقية ، والمطانيات الظاهرة ، والصوم الروحانى ، وكل فضيلة أخرى ...","والعجيب أن المهتم بالفضائل الظاهرة ، كثيراً ما يصطدم بأب اعترافه ، وربما يفكر فى تغييره ، بينما حياته هو من الداخل ليست نقية أمام الله !",{h:"٢١ العنـــف"},{h:"إنها حرب يوجهها الشيطان إلى الروحيين كما إلى الخطاة ."},"يدرب الإنسان على العنف تجاه كل خطأ . وبالتالى يجعله عنيفاً فى مقابلة كل من يخالفه فى الرأى . وقد تختفى وراء هذا العنف كبرياء وقساوة قلب .","وربما كثير من أهل العالم يتميزون بالوداعة والهدوء ، بينما نجد من المتدينين من يكونون عنفاء جداً ، باسم الدين ، ساخطين على كل شىء ، شاعرين أنهم هم وحدهم الذين يعرفون الله ويسيرون فى طرقه . وبهذا العنف يسقطهم الشيطان فى عديد من الأخطاء التى لم يقع فيها العلمانيون . وينسيهم فضائل الوداعة واللطف التى هى من ثمار الروح القدس (غل ٥ : ٢٢) .","من حروب الشيطان أيضاً :"],86:[{h:"٢٢ المعطـــلات"},{h:"كل عمل روحى معرض لمعطلات عديدة من الشيطان ."},"فقد يعزم الإنسان من كل قلبه على عمل روحى . ويقف ضده الشيطان بكل قوة لكى يعطله عن تنفيذ ما يريد . وكما يقول الرسول « الإرادة حاضرة عندى . ولكن أن أفعل الحسنى لست أجد » (رو ٧ : ١٨) . وهذه المعطلات إما أن تكون ظروفاً خارجية ، أو من نسيان ، أو من عدم توافر الوقت ، أو من مقاومات من أعداء ، أو من أخوة كذبة ... ثم يأتى الشيطان ليقول :",{h:"قطعاً هذا العمل ليس من الله . وإلا كان قد سهل سبله !"},"أو قد يقول للناس عن هذا الإنسان الخير : لو كان هذا الإنسان من الله ، لكان الله قد وفقه فى عمله . ويضرب عصفورين بحجر واحد .","من حيل الشيطان أيضاً لإيقاع الإنسان : الخجل .",{h:"٢٣ الخجـــل"},"الخجل فضيلة إن أحسن الإنسان استخدامها . ولكن الشيطان كثيراً ما يستخدم الخجل بطريقة تساعد على السقوط ...","كإنسان كان جالساً وسط أناس يتكلمون كلاماً رديئاً من الناحية الخلقية ، أو يتحدثون بالسوء فى سيرة إنسان له مكانته ويشهرون به ، أو يسردون قصصاً غير لائقة ... وهذا الإنسان البار الجالس وسطهم ، الذى لم يكن يتوقع كل هذا ، يفكر أن يتركهم وينسحب ... ولكن يأتيه شيطان الخجل ، ويرغمه على البقاء ... فيستمر جالساً ويمتلىء عقله بأفكار ما كان يحب مطلقاً أن تجول بذهنه .",{h:"وعن طريق الخجل قد يوقع على تزكية لا يوافق عليها ضميره ."},"أو يوقع على أى بيان أو قرار ، هو فى داخله غير راض عليه ، أو يشترك فى مديح إنسان لا يستحق ذلك ... وإن حاول أن يمتنع يقف أمامه الخجل !",{h:"وقد يجعل الشيطان فتاة تخجل من ملابسها المحتشمة ."}],87:["وذلك إن كان التيار العام غير ذلك ... أو يجعلها تخجل من تدينها بوجه عام . تخجل من الصلاة ومن الصوم ، أو من معرفة ذلك عنها ... بل قد تخجل من تعليق صليب على صدرها . أو تخجل من رفض دعوة إلى حفل معين لا تستريح له روحياتها .","وبالمثل قد يخجل شاب متدين من رفض سيجارة تقدم له من زميل أو من أستاذ ... وكم من خطايا يقع فيها البعض بسبب شيطان الخجل !",{h:"والمفروض أن يرفض المتدين هذا الخجل ويبعد عن مجالاته ."},"أو يجد له سبباً يخرج به من الإحراج بلباقة . أو أن يكون قوى الشخصية يستطيع أن يدافع عن موقفه الروحى بإقناع الآخرين ... أو على الأقل يبعد عن الصحبة التى تحرجه وعن المناسبات التى يتعرض فيها لحرب الخجل .","عجيب أن المتدينين يخجلون من تدينهم ، بينما الخاطئون تكون لهم جرأة وجسارة فى أخطائهم وفى انتقادهم للأعمال الروحية .","حرب أخرى من حروب الشيطان هى :",{h:"٢٤ الوقـت الضـائـع"},"كما أن المؤمن قد يحارب أحياناً من شيطان الخجل ، كذلك يحاربه فى أحيان أخرى شيطان الوقت الضائع .",{h:"حياة الإنسان هى وقت ، يحاول الشيطان أن يضيعه ."},"والوقت الضائع هو الوقت الذى يمر بك بلا أدنى فائدة : لا فائدة روحية ، ولا فائدة عقلية أو صحية ، ولا فائدة للآخرين .","لا يهم الشيطان أن يجعلك فيه ترتكب خطية ... بل يكفيه أن هذا الوقت يضيع ، كجزء من حياتك بلا ثمر لك أو لغيرك .",{h:"والأمثلة كثيرة لهذا الضياع ، وهى متنوعة أيضاً ."},"منها أحاديث قد تطول بالساعات فى موضوعات لا فائدة منها ، وتكون بلا نتيجة . ومجادلات ومناقشات لا جدوى منها سوى تعب الأعصاب وضياع الوقت . وزيارات وسهرات ، وترفيهات زائدة عن الحد . ومسليات تأخذ كل الوقت وتعطل إيجابيات هامة"],88:["فى حياتك . ومثل جلوس البعض فى المقاهى للعب والكلام ، وقتل الوقت .","إن الذى يقبل ضياع وقته ، تكون حياته رخيصة فى عينيه !",{h:"٢٥ الشيطان يستخدم أعوانـاً"},"إنه لا يعمل وحده . فله أعوان من جنده الشياطين ، وأعوان من البشر أيضاً . وربما يكون هؤلاء من أحبائك أو أقربائك أو معارفك ، أو من الغرباء عنك .","لقد تكلم الشيطان على أفواه بعض الناس عند الصليب قائلاً للرب « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{h:"وقد يستخدم أقرباءك كما قيل « أعداء الإنسان أهل بيته »"},"(متى ١٠ : ٣٦) .","فيوحى إلى أحد الأحباء إليك جداً بنصيحة تتلف حياتك . أو يجعلهم يقفون ضد عملك الروحى ، أو ضد تكريسك ، أو ضد عبادتك أو يستخدمهم للتهكم عليك ... فكن محترساً . وكل ما تسمعه من النصائح إفحصه جيداً ، وتمسك بالحسن (١تس ٥ : ٢١) . ولكن إحذر من أن تقول لأحد أقربائك (أنت من أعوان الشياطين) .",{h:"وقد يكون أعوان الشيطان بالنسبة إليك صحبة شريرة ."},"وكما يقول الكتاب « المعاشرات الرديئة تفسد الأخلاق الجيدة » (١كو ١٥ : ٣٣) . لذلك ضع أمامك باستمرار المزمور الأول . فلا تسلك فى مشورة المنافقين ، وفى طريق الخطاة لا تقف ، وفى مجلس المستهزئين لا تجلس (مز ١) . إن كل هذه هى مجالس الشيطان ، هو يقودها ويدبرها ...",{h:"لا تظن أن الشيطان يتراءى لك بروُى العين لكى يحاربك ."},"فهذه درجة عالية جداً من الحروب لا يسمح بها الله إلا للقديسين الذين يحتملونها . فإن أراد مثلاً أن يشيرك ، يرسل اليك من يشيرك . ويكون هذا الذى أثارك من أعوان الشيطان ، على الأقل فى هذه النقطة بالذات . وهكذا كل من يعثرك : كل من يقودك إلى الخطية ، أو يساعدك عليها ، أو يوقعك فيها ...",{h:"والأشرار عموماً هم من أعوان الشياطين ."}],89:["كل أجهزة العبث وكل مسببات العثرات . وكل الفلاسفة الملحدين وكل دعاة الإلحاد . وكل ناشرى الشكوك ... وكل مسببى الشر ... وعن هذا كان داود النبى ورجاله يصرخون قائلين : إبطل يارب مشورة أخيتوفل (٢صم ١٥ : ٣١) . وكانت مشورة ضارة جداً بداود ورجاله ، قدمها أخيتوفل لأبشالوم فى ثورته على أبيه داود ...","إن الشيطان إذا أراد مثلاً أن يوقع العالم فى البدع والشكوك ، فلا يعنى هذا بالضرورة أن يفعل هذا بنفسه ، إنما يقدم هذه البدع إلى العالم عن طريق أعوانه من البشر ، ينشرونها ويشرحونها للناس ، ويدعونهم إلى اعتناقها ..",{h:"فعلينا أن نصلى كل حين ، أن ينجينا الرب من أعوان الشياطين ."},"وليس فقط من الشيطان وحده . بل من الشيطان وكل ملائكته وكل جنوده ، وكل أنصاره وأعوانه ، وكل منفذى مشيئته على الأرض ... كل قوات العدو ...",{h:"ملاحظــــة :"},"أ - من جهة حروب المناظر المخيفة ، وحروب الرؤى والأحلام والضلالات الشيطانية ، فقد تحدثنا عنها فى الفصل الثانى الخاص بصفات الشيطان وحروبه ، تحت صفة (قاس) وصفة (كذاب) .",{h:"ب - وهذه النقاط التى ذكرناها ليست هى كل حيل الشيطان ."},"ولا كل ما نعرفه عنها . فإن جعبة الشيطان لا تفرغ . وحيله لا تنتهى : القديمة والحديثة ، وما يمكن أن يخترعه الآن وفيا بعد . ولا شك أنه مجدد فى حيله ، رحمنا الله منه ومنها .","من أجل هذا ، نحن نصلى كل يوم فى تحليل الغروب :",{h:"« نجنا من حيل المضاد . وإبطل سائر فخاخه المنصوبة لنا » آمين ."}],90:[{h:"الفصل الرابع"},{h:"كيفية الإنتصار على حروب الشياطين"}],91:["كل ما ذكرناه قبلاً من صفات الشيطان وتنوع حيله ، إنما كتبناه لكم ، لا لكى تخافوا منه ، إنما لكى تحترسوا منه . وعلى الرغم من عنف الشيطان ومكره ، إلا أن الإنتصار عليه ممكن جداً ، بل إنه سهل أيضاً .",{h:"١ الإنتصـار ممكـن"},"إذا وضعت أمامك أن الإنتصار فى حروب الشياطين أمر صعب أو مستحيل ، ستخور قواك وتضعف وتستسلم ، وبالتالى ستسقط . أما أنت فإن حاربك الشيطان ، تأكد تماماً أنه فى إمكانك أن تنتصر ، وإلا ما كان الله يسمح بحرب غير متكافئة ...",{h:"تأمل باستمرار فى سير القديسين الذين انتصروا ."},"ضع أمامك قصة يوسف الصديق الذى انتصر على الرغم صعوبة التجربة التى تعرض لها . أما داود وشمشون فى سقوطها ، فخذ درساً من قصة كل واحد منها . إعرف ما هى أسباب سقوطه وتحاشاها . إن كل قصة سقوط أعطيت لنا ، إنما لفائدتنا ، لكى نحترس ونتعلم ...",{h:"الكتاب والتاريخ قدما لنا العديد من قصص الإنتصار ."},"نعرف أن التوبة ممكنة جداً ، مهما كانت الحالة سيئة ، وذلك من قصة توبة مريم القبطية ، وبيلاجية ، وبائيسة ، وأوغسطينوس ، وموسى الأسود . وكذلك توبة سليمان الحكيم ، وشمشون . لذلك إن حاربنا الشيطان باليأس من سوء ما وصلنا إليه نتذكر كل هذا لنتعزى ونتشجع .","ونعرف من قصة القديس الأنبا أنطونيوس ، كيف يمكن الإنتصار على الرغم من شدة الحروب وتنوعها وكثرتها . وكذلك من سير باقى القديسين ."],92:[{h:"كذلك علينا أن نتذكر باستمرار كيف أن الله بارك طبيعتنا ."},"إنه لما تجسد وأخذ هذه الطبيعة ، باركها . ولذلك نقول له فى القداس الغريغورى « وباركت طبيعتى فيك » . وأصبحت هذه الطبيعة قادرة جداً على قهر الشيطان . يكفى أننا صرنا هياكل للروح القدس ، وروح الله يسكن فينا (١كو ٣ : ١٦) . كما صرنا أبناء لله ، بطبيعة مولودة من فوق ، من الماء والروح (يو ٣ : ٣ ، ٥) .",{h:"وكما نتذكر القوة التى أعطيت لنا ، نتذكر القوى الروحية المحيطة بنا ."},"نتذكر أننا لسنا وحدنا فى حرب الشيطان . فروح الله القدوس يعيننا ، ويبكتنا على خطية (يو ١٦ : ٨) ، ويعلمنا كل شىء (١يو ٢ : ٢٧) ، ويرشدنا إلى كل الحق (يو ١٦ : ١٣) . فكيف يمكن أن ينتصر الشيطان علينا ، ونحن لنا شركة الروح القدس (٢كو ١٣ : ١٤) . وكذلك نعمة ربنا يسوع المسيح معنا (١كو ١٦ : ٢٣) . ولذلك نحيا ، لا نحن ، بل المسيح الذى يحيا فينا (غل ٢ : ٢٠) ... يضاف إلى هذا ملائكة كثيرون محيطون بنا ، أرسلوا لخدمتنا لنرث الخلاص (عب ١ : ١٤) . كما أن سحابة من الشهود الذين انتصروا (من القديسين) محيطة بنا أيضاً « لنطرح كل ثقل والخطية المحيطة بنا بسهولة » (عب ١٢ : ١) .",{h:"ولنتذكر أيضاً وعود الله لنا ، لكى نتشجع ..."},"إنه يقول « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . « وإن كان الله معنا فمن علينا » (رو ٨ : ٣١) . إنه يقول لكل منا « لا أهملك ولا أتركك ... تشدد وتشجع . لا ترهب ولا ترتعب ، لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٥ ، ٩) ، « أنا معك ، ولا يقع بك أحد ليؤذيك » (أع ١٨ : ١٠) .",{h:"ولنتذكر وعود الله للغالبين ، لكى تحمسنا فى جهادنا ."},"لذلك إقرأ وعود الله مثلاً لرعاة الكنائس السبع التى فى آسيا « من يغلب فسأعطيه أن يجلس معى فى عرشى ، كما غلبت أنا أيضاً وجلست مع أبى فى عرشه » ، « وسيلبس ثياباً بيضاً ... وسأعترف بإسمه أمام أبى وأمام ملائكته » (رؤ"],93:["٣ : ٢١ ، ٥) ، « سأعطيه أن يأكل من المن المخفى » ، « وأعطيه كوكب الصبح » ، « وأعطيه إكليل الحياة » (رؤ ٢ : ١٧ ، ٢٨ ، ١٠) ... حقاً من له أذنان للسمع فليسمع هذه الوعود التى تملأ القلب حماساً وقوة ...",{h:"كذلك فلنثق تماماً أن الله هو الذى يحارب عنا ."},"فمهما كان الشيطان قوياً ، من هو أمام قوة الله التى لا تحد ؟ وإن كان الشيطان كأسد يزأر ، فإن الله يرسل ملاكه ليسد أفواه الأسود (دا ٦ : ٢٢) . حقاً « إن الحرب للرب » (١صم ١٧ : ٤٧) . هو « يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٤) . مادام الرب هو الذى يقاتل عنكم ، إذن لا تخافوا مطلقاً من الشيطان .",{h:"٢ لا تخـــافـــوا"},"لا تخافوا مطلقاً من الشيطان . فهو على الرغم من كل مواهبه وقوته وحيله ، كائن ضعيف أمام أولاد الله . قال عنه الرب :",{h:"« رأيت الشيطان ساقطاً مثل البرق من السماء » (لو ١٠ : ١٨) ."},"لقد داسه الرب على الصليب ، ولم يعد « رئيس هذا العالم » كما كان . بل قال عنه الرب قبيل الصليب « الآن دينونة هذا العالم . الآن يُطرح رئيس هذا العالم خارجاً » (يو ١٢ : ٣١) ، « رئيس هذا العالم قد دين » (يو ١٦ : ١١) . لذلك قال الرب :",{h:"« ها أنا أعطيكم سلطاناً لتدوسوا الحيات والعقارب وكل قوة العدو »"},"(لو ١٠ : ١٩) . إن وعد الرب لنا أن ندوس كل قوة العدو ، هو وعد كله قوة وعزاء ، ينزع الخوف من أى قلب ... ومن محبة الكنيسة لهذا الوعد الإلهى ، وضعته لنا فى آخر صلاة الشكر ، نذكره فى صلواتنا كل يوم بل كل ساعة ، حتى لا نخاف من الشيطان ولا من كل قوة العدو .",{h:"إذن ليس للشيطان سلطان علينا ، بل لنا سلطان عليه ."},"حتى الشياطين تخضع لنا باسم الرب (لو ١٠ : ١٧) . بل جعل الرب إخراج"],94:["الشياطين فى مقدمة الآيات التى تتبع المؤمنين (مر ١٦ : ١٧) . وطبعاً موهبة إخراج الشياطين لابد أن يسبقها الإنتصار أولاً فى حروب الشياطين . فالذى ينتصر على الشيطان فى تجاربه وإغراءاته ، ويجده الشيطان صلباً ، يبدأ أن يخافه . ويصير لهذا الإنسان سلطان عليه .",{h:"هناك محاضرة جميلة للقديس أنطونيوس عن ضعف الشياطين ..."},"سجلها القديس أثناسيوس الرسولى فى كتابه عن حياة القديس أنطونيوس ، يمكن أن تقرأوها ، لكى تتقوى قلوبكم فلا تخافوا الشياطين .","وكم من رهبان بسطاء ، لم ينالوا من العلم كثيراً ولا قليلاً ، إستطاعوا أن يحطموا الشيطان فى البرية . ومنهم القديس بولس البسيط .","كذلك فإن الشهداء والمعترفين استطاعوا أن يحطموا جميع إغراءاته وكل قوته وأسلحته .",{h:"والشيطان لا يسيطر إلا على الذى يخضع نفسه له ..."},"وعلى رأى المثل « إن العبيد هم الذين يخلقون السادة » ، أى أن ما فى العبيد من ذل وخضوع ، هو الذى يساعد السادة على السيطرة والتعالى . كذلك الحال مع الخاضعين للشيطان . أما الذين حررهم الإبن ، فبالحقيقة هم أحرار (يو ٨ : ٣٦) .",{h:"أكثر شىء يحبه الشيطان ، أن يجعلك تخاف منه ."},"لأنك فى خوفك تضعف أمامه وتضطرب ، وتظن أنك لا بد واقع فى يديه ، فتخور معنوياتك ، وتستسلم له ، عاجزاً عن المقاومة ... وهذا عين ما يريده منك ، لأن الخوف يعطيه ساطة عليك . ولكن السيد المسيح نصحنا ألا نخاف مطلقاً ، بقوله :",{h:"أنا هو . لا تخافوا . لا تضطرب قلوبكم ولا تجزع (متى ١٤ : ٢٧ ، يو ١٤ : ٢٧) ."},"لا تخف إذن . لأن قوة الله العاملة فيك ، هى أعظم بما لا يقاس من قوة الشيطان الذى يحاربك من الخارج . وثق أن خوفك فى داخلك هو أكثر ضرراً عليك من حرب الشيطان الخارجية .","إن الذين خافوا من جليات الجبار ، ضعفوا أمامه ولم يستطيعوا أن يقاوموه . أما داود الذى لم يخف ، فقد تقدم إليه بجسارة قلب ، معتمداً على معونة الرب ، وانتصر"],95:["عليه . وقصة داود وجليات تصلح رمزاً لحروب الشياطين . ولعلك تسأل داود عن السر فى عدم خوفه فيقول :",{h:"« الرب نورى وخلاصى ممن أخاف ؟! الرب عاضد حياتى ممن أرتعب ؟!"},"(مز ٢٧ : ١) ، ويستطرد « إن يحاربنى جيش فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » . لذلك أدخل حروب الشياطين بقلب مطمئن ، وحارب حروب الرب وأنت واثق أنك ستنتصر بمعونته . ما أصعب وما أخطر ما قيل فى سفر الرؤيا عن الخوف : « وأما الخائفون وغير المؤمنين والرجسون والقاتلون والزناة والسحرة وعبدة الأوثان وجميع الكذبة ، فنصيبهم فى البحيرة المتقدة بنار وكبريت » (رؤ ٢١ : ٨) .",{h:"وهكذا وضع الخائفين قبل غير المؤمنين وقبل القتلة والزناة !"},"ولعلك تسأل لماذا ؟ ربما لأن الذى يخاف من الشيطان ويستسلم له ، يقع فى كل هذه الخطايا . أو لأن الذى يخاف من الشيطان ويخضع له ، يكون خائفاً فى اليوم الأخير ، لأنه لم يجاهد ويغلب مثل المؤمنين المختارين .",{h:"ليتك تقرأ سير القديسين الذين لم يخافوا الشياطين ."},"إقرأ عن القديس الأنبا أنطونيوس الذى كانت الشياطين تظهر له على هيئة أسود ونمور ووحوش مفترسة ، تصيح بأصواتها المرعبة لتخيفه فيترك البرية ، ولكنه لم يخف ، وكان يجيبها بهدوء . أو إقرأ عن القديس مقاريوس الكبير الذى نام فى مقبرة ، وقد وضع جمجمة تحت رأسه . فكلّم الشياطين صاحبة هذه الجمجمة بصوت مسموع لكى تقوم معهم . فلم يضطرب القديس ، بل رفع رأسه قليلاً عن الجمجمة ، وقال لها « إن أردتِ ، قومى واذهبى معهم إلى الجحيم » ...","أما أنتم فلا تخافوا . لن تحاربكم الشياطين بهذه المخاوف التى حاربت بها القديسين . وهوذا الرسول يطمئنكم قائلاً :",{h:"الله أمين ... لا يدعكم تجربون فوق ما تستطيعون (١كو ١٠ : ١٣) ."},"إن الله لا يسمح للشيطان أن يجربكم بما هو فوق احتمالكم « بل سيجعل مع التجربة المنفذ لتستطيعوا أن تحتملوا » (١كو ١٠ : ١٣) . لهذا لا تخافوا مطلقاً من الشياطين وحروبهم ، سواء كانت بمخاوف أو بخطايا . إن الشيطان قد يثير ضجة ليخيف ، ولكنه لا يستطيع أن يعمل شيئاً للمؤمن الصامد ."],96:[{h:"إنى أشبّه ضجيج الشيطان بقصة الثعلب والطبلة ."},"كانت هناك طبلة معلقة على شجرة ، تعصف بها الريح فتحدث صوتاً مهولاً . ومرّ عليها ثعلب وراءه هذا الصوت الضخم فخاف أولاً . ثم تجرأ وهجم عليها ، فرآها فارغة من الداخل ، فضحك واحتقرها . يشبه ذلك أيضاً البالونة الكبيرة التى تبدو ضخمة ، ولكن شكّة دبوس صغير ، تجعلها كلا شىء ...","هكذا الشيطان فى حروبه : ضجيج بلا قوة . يحاول أن يخيف ، ولكنه لا يملك قوة . والشيطان ليس كائناً مطلق الحرية يفعل ما يشاء .",{h:"هناك الله ضابط الكل ، يمنع الشيطان حسبما يشاء ."},"وفى قصة أيوب الصديق ، ما كان الشيطان يتصرف حسب هواه ، بل إنه لا يحارب إلا فى النطاق الذى يسمح به الله (أى ١ ، ٢) .","إنه ليس قوياً بالشكل الذى تخافه . بل مجرد علامة الصليب فى إيمان ، تجعله يهرب من أمامك .",{h:"يريد الشيطان أن يوهمك بأنه قوى . ولكن لا تصدقه ."},"وتذكر باستمرار إنهزاماته المتكررة فى قصص القديسين . وتذكر أولئك الذين كانت لهم قوة أن يخرجوه ممن صرعهم . وكيف كان يصيح فى خوف أمام أولاد الله ويهرب .","إن عرفتم ضعف الشيطان ، قاوموه فى شجاعة .",{h:"٣ قـــاومـوه"},"ما أجمل أن نتذكر قول القديس يعقوب الرسول :",{h:"« قاوموا إبليس ، فيهرب منكم » (يع ٤ : ٧) ."},"وهنا عبارة « يهرب منكم » تدل على ضعف الشيطان . فالرسول لم يقل قاوموه فيتركككم ، إنما قال قاوموه فيهرب منكم ...","إن الشيطان يجس نبض الإنسان ، ليعرف ما هو ممدنه . فإن وجده من النوع الذى يخاف ، يبدأ أن يتسلى به ويجعله لعبته . أما إن وجده قوياً ويقاوم ، ولا يقبل الهزيمة ، حينئذ يخافه الشيطان ويهرب منه ... لذلك قاوموه ولا تغركم قوته . فالقديس بطرس الرسول لما قال « إبليس خصمكم كأسد زائر يجول ملتمساً من يبتلعه هو » قال بعدها مباشرة :"],97:[{h:"« فقاوموه راسخين فى الإيمان » (١بط ٥ : ٩) ."},"أى أن زئيره كأسد لا يخيفكم ، بل قاوموه . ليكن لكم قلب أسد أقوى منه . إن تذكرتم أن الشيطان يزأر كأسد ، تذكروا قول دانيال « إلهى أرسل ملاكه فسد أفواه الأسود » (دا ٦ : ٢٢) . قفوا أمام الشيطان إذن فى قوة وصمود ، بكل مقاومة ...",{h:"لا تستسلم ، بل اصمد فى الحرب ، كجندى صالح للمسيح ."},"حارب بكل قوتك ، واطلب معونة الرب . وهنا يعجبنى ما قيل فى سفر النشيد « تخت سليمان حوله ستون جباراً ... كلهم قابضون سيوفاً ومتعلمون الحرب . كل رجل سيفه على فخذه من هول الليل » (نش ٣ : ٨) . كن إذن متعلماً الحرب فى كل ما يثيره عليك الشيطان . وليكن سيفك على فخذك . بل كما يقول المرتل فى المزمور « تقلد سيفك على فخذك أيها الجبار ... إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{h:"إن حاربك الشيطان بفكر أو شعور ، لا تستسلم بل قاوم ."},"لا تقبل كل ما يعرضه عليك . لا تفتح له قلبك ، ولا تفتح له عقلك ، ولا تسلّم له إرادتك ، ولا تتساهل معه ، بل قاومه بكل عنف . قاوم كل أفكاره وكل إغراءاته وكل شهواته وكل تجاربه . واحذر أن تتراخى ، لئلا تسمع تأنيب الرسول :",{h:"« لم تقاوموا بعد حتى الدم ، مجاهدين ضد الخطية » (عب ١٢ : ٤) ."},"حتى الدم ... حتى لو أدى الأمر أن تستشهد فى حربك ضده . كما يقال عن الضابط فى الجيش إنه « يحارب إلى آخر طلقة وآخر رجل » . وثق أنك لو فتحت للشيطان ولو ثقب إبرة فى فكرك أو فى إرادتك ، سيظل يتمادى ويوسع نطاقه حتى يتعبك . لذلك قاومه واطرده عنك . ومهما أراد أن يتفاهم معك فى شرح الخطية ، فلا تقبل .",{h:"لا تفاهم مع الشيطان فى الخطية . ولا نقاش ولا جدال ."},"وكما قال أحد القديسين « لا تأخذ وتعطِ مع إنسان يقاتلك به العدو » . إن الشيطان عندما يعرض عليك الخطية ، إنما يريد أن يتفاهم معك فيها ، أى يريد بقاءك فى مجال الخطية أطول مدة لتتأثر بها . وفى هذا أنت الخاسر .",{h:"لذلك قاومه من أول خطوة ، حينما تكون إرادتك فى يدك ."},"لأنك إن تأخرت فى مقاومته ، سيزداد تأثيره عليك ، وستقل إرادتك شيئاً فشيئاً ."],98:["وكلما طالت المدة معه تضعف مقاومتك ، مثلما حدث لشمشون مع دليلة ، لأنه لما كثر إلحاحها عليه ضاقت نفسه وأخبرها بسره (قض ١٣ : ١٥ - ١٧) .",{h:"لا تقل أنتظر على هذا الفكر حتى أعرف نهايته !"},"صدقنى ، أنت تعرف تماماً ما هى نهايته . فلا تخدع نفسك . مجرد فتح أبواب فكرك للشيطان هى خيانة للرب . لذلك إبعد كل البعد عن الشيطان وكل طرقه وكل جنده ، ولا تتساهل مع حيله ، ولا تتأخر . بل ارفضه بحزم وقل له « إذهب يا شيطان » (متى ٤ : ١٠) . فيعرف الشيطان أنك جاد فى رفضك له .",{h:"وبرفضك الحازم لكل أفكاره ، تصير لك هيبة عند الشيطان ."},"الشيطان يدرك تماماً بذكائه ما هى المقاومة الجادة ، وما هو التمريج بين الفرقتين (١مل ١٨ : ٢١) . يعرف من هو الذى يرفضه بقلب نقى ، ومن هو الذى يرفض من الخارج بينها قلبه متجاوب مع الشيطان . نعم إن الشيطان يمكنه أن يستنتج من الذى سيقاومه حتى الموت ومن الذى إذا ضغط عليه قليلاً يستسلم . فقاوم بجدية ، وبكل قوة ، ومن قلبك .",{h:"لست أحب أن يقول عنك الشيطان أنك إنسان طيب ."},"لا أريد أن يقول عنك : إنه إنسان طيب ، يثور علىّ جداً فى أول الأمر . ومع ذلك فإن قلبه أبيض سرعان ما يتصافى . ومع أنه يعارض كثيراً ، إلا أن الأمر ينتهى أخيراً بالموافقة والرضى ، مثل كل مرة ... !",{h:"والمقاومة هى رفض الخطية بكل صورها ، ورفض التنازل عن الكمال ."},"والإصرار القلبى على السير فى الطريق الروحى ، ورفض كل مقترحات الشيطان ، بل ومراقبة كل أفكاره من بعيد ، وعدم التفاوض مع شىء منها ، بل طردها من أول وهلة . وغلق كل أبواب النفس والفكر والقلب أمامها . وعدم التساهل فى شىء ، بحجة أن هذا الأمر بسيط ، أو أن هذه العثرة لا تؤثر فىّ !","المقاومة لازمة ولكن كيف ؟ يقول الرسول : قاوموه راسخين فى الإيمان ."],99:[{h:"٤ بالإيمــــــان"},{h:"أنت تغلب الشيطان بالإيمان . ولكن أى إيمان ؟ إنه :"},"الإيمان بعمل الله معك . الإيمان بأن الله يستطيع أن يبطل قوة العدو وكل فخاخه المنصوبة لنا . الإيمان بأن الله « لا يترك عصا الخطاة تستقر على نصيب الصديقين » (مز ١٢٥ : ٣) . الإيمان بأن الله أقوى من كل حيل العدو . وهو الذى يحارب عنا .","الحرب للرب (١صم ١٧ : ٤٧) ، الرب يقاتل عنكم وأنتم تصمتون (خر ١٤ : ١٤) .","تؤمن أن الحرب للرب . فلست أنت الذى تحارب الشيطان ، بل الله هو الذى يحاربه فيك ومعك . هو الذى يعطيك القوة التى تحارب بها ، والسلاح الذى تستخدمه ، وهو الذى يعطيك الخبرة فى مقاتلة الشياطين ، كما قال داود النبى :","« مبارك الرب ... الذى يعلم يدىّ القتال وأصابعى الحرب » (مز ١٤٤ : ١) .","فهل أنت أدخلت الله معك فى حروبك وفى تجاربك ومشاكلك ؟ إن كنت مهزوماً ، فربما لأنك لم تدخل الله معك . والله قادر تماماً أن يغلب بك ويتمجد فيك ، مهما كانت قوتك ضئيلة ومقاومتك لا شىء . فالكتاب يقول :","« ليس للرب مانع أن يخلص بالكثير أو بالقليل » (١صم ١٤ : ٦) .","إن حزقيا الملك لما وصله خطاب تهديد من ملك سنحاريب بجيشه الجبار ، وضع الخطاب أمام الله فى بيت الرب . وسكب نفسه أمام الله لكى يتصرف . وتدخل الله وأرسل ملاكه فضرب جيش سنحاريب (٢مل ١٩ : ٣٥) .",{h:"ونلاحظ كيف أن داود النبى كان ينتصر بالإيمان فى حروبه ."},"إنه يقول « لولا أن الرب كان معنا حين قام الناس علينا ، لابتلعونا ونحن أحياء ... نجت أنفسنا مثل العصفور من فخ الصيادين ... عوننا من عند الرب الذى صنع السماء والأرض » (مز ١٢٤) ، « عيوننا إليك يارب ... إحفظنى من الفخ الذى نصبوه لى ومن شكوك فاعلى الإثم » (مز ١٤١ : ٩) ، « ... ضاع المهرب منى ، وليس من يسأل عن نفسى . فصرخت إليك يارب . وقلت أنت هو رجائى وحظى فى أرض الأحياء » (مز ١٤٢ : ٤ ، ٥) ."],100:[{h:"بهذا الإيمان إنتصر داود فى حروبه كما انتصر على جليات ."},"مهما كان عدوك قوياً ، آمن أن الله سيخلصك منه . رتّل مع داود النبى وقل : صوت الرب يقطع لهيب النار . صوت الرب يزلزل القفر » (مز ٢٩ : ٧ ، ٨) . وفى إيمان قوى ، قاوم الشيطان مردداً قول بولس الرسول :",{h:"« أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) ."},"وكن راسخاً فى هذا الإيمان ، واثقاً تماماً أن الله سيقف إلى جوارك وينصرك فى كل حروب الشيطان ، وأنه لن يتخلى عنك . وكما كان مع آبائنا وقادهم فى موكب نصرته ، سيكون معك أيضاً ، ولن يسمح أن يقع بك أحد ليؤذيك (أع ١٨ : ١٠) .",{h:"هذا الإيمان سيعطيك قوة قلب فى الداخل ، وقوة على الشيطان فى الخارج ."},"ولذلك نرى أن الرسول حينما يتكلم عن قتالنا مع الشياطين يقول « أخيراً يا إخوتى ، تقووا فى الرب وفى شدة قوته . البسوا سلاح الله الكامل لكى تقدروا أن تثبتوا ضد مكايد إبليس » (أف ٦ : ١٠ ، ١١) .","إذن الأمر لا تصلح له قوتنا الشخصية ، بل « تقووا فى الرب » . ولا تصلح له أسلحتنا البشرية ، بل علينا أن نلبس سلاح الله الكامل . ونشعر بقوة الله العاملة معنا .",{h:"وبهذه القوة ، لا تكون لنا روح الفشل ولا روح الإستسلام ."},"ولا تكون لنا روح التخاذل ، ولا روح اليأس ، لأن الله الذى نعتمد عليه قادر أن يحمينا فى كل حروب الشياطين . بهذه القوة استطاع القديس بولس الرسول أن يقول « حاربت وحوشاً فى أفسس » (١كو ١٥ : ٣٢) . وبهذه القوة إستطاع أن يقول « إن الله لم يعطنا روح الفشل بل روح القوة » (٢تى ١ : ٧) . لذلك أولاد الله لا يضعفون أبداً فى حروبهم .",{h:"إنهم جبابرة بأس ، لا يقوى عليهم الشيطان ولا الخطية ."},"ما أجمل التقرير الذى كتبه القديس يوحنا الرسول عن أولاد الله « كل من وُلد من الله لا يخطىء ، بل المولود من الله يحفظ نفسه ، والشرير لا يمسه » (١يو ٥ : ١٨) . كلهم لهم روح الغلبة ونيل المواعيد كما شرح الرب فى سفر الرؤيا (رؤ ٢ ، ٣) .","أنظروا إلى أيوب الصديق وشهادة الرب عنه « ليس مثله فى الأرض ، إنه رجل كامل ومستقيم ، يتقى الله ويحيد عن الشر . وإلى الآن هو متمسك بكماله » (أى ٢ :"],101:["٣) . هل مثل هذا يقدر عليه الشيطان ؟! كلا ، بل إن الله تحدى به الشيطان .",{h:"دائماً فى الحرب ضع أمامك الإنتصار وليس الفشل ."},"قل : أنا لا يمكن أن أفشل ، مادمت ألجأ إلى الله ، وهو يحارب عنى . أنا لا أخاف الشيطان ، بل أقول للرب « إن سرت فى وادى ظل الموت ، لا أخاف شراً ، لأنك أنت معى » (مز ٢٣) . إننى فى يمين الرب ، نقشنى على كفه (أش ٤٩ : ١٦) . وقال عن خرافه « أنا أعطيها حياة أبدية ، ولن تهلك إلى الأبد ، ولا يخطفها أحد من يدى ... ولا يقدر أحد أن يخطف من يد أبى » (يو ١٠ : ٢٨ ، ٢٩) .","بهذا الإيمان يمكن أن تنتصر . كذلك تنتصر بالإتضاع .",{h:"٥ بالإتضــــــاع"},"كان القديس الأنبا أنطونيوس يغلب الشياطين بالإتضاع :","فحينما كانوا يتكاثرون عليه ، كان يقول لهم باتضاع « أيها الأقوياء ، ماذا تريدون منى أنا الضعيف ؟! » وكان يصلى قائلاً « إنقذنى يارب من هؤلاء الذين يظنون أننى شىء ، مع أنى أضعف من أن أقاتل أصغرهم » . ولما كان الشياطين يسمعونه وهو يصلى هذه الصلاة المملوءة اتضاعاً ، ما كانوا يحتملون ، بل كانوا ينقشعون كالدخان .",{h:"والقديس مقاريوس الكبير كان يغلب الشيطان أيضاً بالإتضاع ."},"فى إحدى المرات ظهر الشيطان للقديس مقاريوس وقال له « ويلاه منك يا مقاره ! أى شىء أنت تعمله ونحن لا نعمله ؟! أنت تصوم ونحن لا نأكل . أنت تسهر ونحن لا ننام . أنت تسكن البرارى والقفار ونحن كذلك . ولكن بشىء واحد تغلبنا » فسأله القديس ما هو؟ فأجاب : باتضاعك تغلبنا .",{h:"الإتضاع يغلب الشيطان لأسباب كثيرة منها :"},"أولاً : لأن الشيطان غير متضع . والإتضاع يذكره بكبريائه التى أسقطته .","ثانياً : لأن الإتضاع يذكره بصورة المسيح الذى أخلى ذاته وأخذ شكل العبد ، لكى يخلص البشرية . ومجرد هذه الذكرى تتعبه ، فيذهب ."],102:["ثالثاً : لأن المتضع إذ هو معترف بضعفه يستعين بقوة الله لتعينه فى حروب الشيطان . وهذا أخوف ما يخافه الشيطان .","ولهذا كتبت مرة فى مذكرتى العبارة الآتية :",{h:"قال الشيطان لله : أترك لى الأقوياء فإننى كفيل بهم . أما الضعفاء فإننى لا أقوى عليهم . فإذ يرون أنه ليست لهم قوة ، يحاربونى بقوتك ."},{h:"إن قصة أنبا صرابامون أبى طرحه تثبت إخراج الشياطين بالإتضاع ."},"كانت زهرة إبنة الحاكم عليها شيطان ، فجاءوا إلى البابا ليصلى عليها ليخرج . فقال لهم البابا فى اتضاع « أنا ليست لى هذه الموهبة . إذهبوا إلى الأنبا صرابامون أبى طرحه » . فذهبوا إليه . فقال لهم فى اتضاع « صلاتى لأجلها لا تكفى » . وطلب صليب البابا ليرشمها به ، قائلاً إنه « ببركة هذا الصليب تشفى » . وكان يريد بهذا أن ينسب شفاءها إلى البابا وليس إلى نفسه . وهكذا شفيت ، لأن الشيطان لم يحتمل هذا الإتضاع .","تحدثنا عن أهمية الإتضاع فى حروب الشياطين ، مع بعض قصص من سير القديسين . وبقى أن نعرض لسؤال هام وهو :",{h:"ما هو الأثر العملى للإتضاع للإنتصار فى حروب الشياطين ؟"},"١ - المتضع يعترف دائماً بضعفه ويطلب من الله المعونة فتأتيه بقوتها . وهكذا ينتصر لأنه لم يعتمد على ذراعه البشرى ، بل على معونة الله .","٢ - المتضع يحترس من أقل الخطايا ، ويخاف السقوط فيبعد عن جميع العثرات . وبالتالى لا يلقى نفسه فى تجربة ولا يتهاون ، وبهذا الحرص الناتج عن الإتضاع ينتصر على الشيطان .","٣ - المتضع يكشف حروبه وضعفاته . فيمكن علاجها . وبهذا ينتصر .","٤ - المتضع دائماً يصلى . بل إن أصغر خطية يجعلها موضوعاً لصلاته . وهكذا يُدخل الله معه فى حروبه . وبهذا ينتصر .","٥ - نفس الإتضاع : فضيلة لا يحتملها الشياطين فيهربون .","وكما ينتصر الإنسان على الشياطين بالإتضاع ، ينتصر أيضاً بالحكمة والإفراز ."],103:[{h:"٦ بالحكمة والإفـراز"},"إن أتاك فكر ، لا بد أن تفحصه جيداً : هل هو من حروب الشياطين ؟ وأين الحق فيه ، وأين الباطل ؟ وهكذا تفعل مع الرؤى والأحلام ، ومع نصائح الآخرين ... ومع كل ضلالات الشياطين ... ومن أجل هذه المعرفة أو التمييز أو الإفراز ، ينبهنا الرسول بقوله « لا تصدقوا كل روح . بل امتحنوا الأرواح هل هى من الله ؟ ... » (١يو ٤ : ١) .",{h:"فما هى مصادر الحكمة هذه والمعرفة والإفراز ؟"},"هناك إنسان حكيم بطبيعته . خلقه الله هكذا ، ومنحه الذكاء والحكمة والمعرفة ، ويستطيع أن يكتشف حرب الشيطان ويميزها ، ويفرزها عن الفكر الروحى . وهناك من يقتنى الحكمة عن طريق القراءة فى الكتاب المقدس وفى الكتب الروحية وسير القديسين . ونوع ثالث يقتنى الحكمة بالخبرة . وفى كل سقوط يأخذ درساً ويعرف حيلة العدو ، فلا يسقط مرة أخرى . وفى ذلك قال أحد القديسين :",{h:"لا أتذكر أن الشياطين أطفوني فى خطية واحدة مرتين ."},"وقد يقتنى الإنسان الحكمة عن طريق المشورة والإسترشاد والتعلم .","وإذ يميز حرب الشيطان ويكشفها ، يبعد عنها ، فلا يخدعه العدو .","نقول هذا عن الذى يريد أن ينتصر . لأن هناك إنساناً يعرف أن هذه حرب من حروب العدو ، ومع ذلك يستمر فيها لأسباب داخل نفسه ، أو لإنحراف ، أو لأنه غير قادر على المقاومة ...",{h:"والحكمة كما تكشف حيل الشياطين ، تعطى أيضاً وسيلة للتصرف ."},"فالإنسان الحكيم يعرف كيف يفلت من حيل الشيطان : كيف يهرب من فخاخه ، وكيف يقوم إذا سقط . وكيف يبعد عن كل سبل الخطية .","وإذا لم يعرف ، تدعوه الحكمة أن يستشير ..."],104:[{h:"٧ بالمشـــورة والإعتـراف"},{h:"الإرشاد الروحى يكشف حيل الشياطين ، ويشرح كيفية النجاة منها ."},"كما أن المرشد يصلى من أجل النفس التى تكشف أفكارها لتنجو . وفى هذا قال القديس بولس الرسول « أطيعوا مرشديكم واخضعوا . لأنهم يسهرون لأجل نفوسكم كأنهم سوف يعطون حساباً ... لكى يفعلوا ذلك بفرح ... » (عب ١٣ : ١٧) . ولهذا فإن الذى يسلك فى الطريق الروحى بهواه ، يمكن أن يسقط فى فخاخ الشياطين . وقد قيل :",{h:"الذين بلا مرشد يسقطون مثل أوراق الشجر ."},"من أجل هذا كانت أهمية أب الإعتراف فى الكنيسة . تكشف له ما فى قلبك وتخجل وتنسحق نفسك أمام الله فى حضرته . ويرشدك إلى ما ينبغى أن تفعله . والإعتراف يكشف حروباً ربما المبتدئون لا ينتبهون لها .",{h:"وكثير من الخطايا يخلص منها المعترف بسبب فضيلة الإعتراف ."},"شياطينها لا تحتمل إنسحاق المعترف فى مذلة فتهرب . كما أن الشياطين تحب أن تعمل فى الظلمة ، والإعتراف يكشفها . كذلك الإرشاد يكسر فخاخها . والتحليل يضيع تعبها . وهكذا نرى أن الإنسان المعترف بخطاياه والمطيع للإرشاد ، يسلك فى طريق التوبة ، وينجو من حروب الشياطين . وحتى إن لم تتركه الخطية تماماً ، فإن قوتها تضعف فى مهاجمته .",{h:"لهذا يحاول الشيطان أن يمنع الإعتراف . ويشكك فى أب الإعتراف ."},"يدخل هنا شيطان الخجل ليمنع الإعتراف . ويدخل شيطان الشهوة ليقول « ما الفائدة إن كنت سأعود إليك ؟! » . ويدخل شيطان الفكر والجدل ليناقش موضوع الإعتراف جملة . ويدخل شيطان الشك ليشككك فى الإعتراف وأب الإعتراف .","أما أنت فكن ثابتاً . واعترف بكل هذا أيضاً . فلا يجد الشيطان حيلة فيك ، ويعتبرك خصماً متعباً ، فيتركك ..."],105:[{h:"٨ بالسـهــر والحـرص"},"لا يكفى أن تعترف وتكشف نفسك وتطلب الإرشاد ، إنما ينبغى أن تكون ساهراً على خلاص نفسك (*) . وهوذا الرسول يقول :",{h:"إصحوا واسهروا ، لأن إبليس خصمكم مثل أسد زائر ... » (١بط ٥ : ٨) ."},"إسهروا لأن عدوكم متيقظ وقوى ، لئلا يأخذكم فى ساعة غفلة أو تهاون أو تراخ ، أو فى ساعة فتور ، أو فى حالة نسيان لواجباتكم الروحية وعدم اهتمام بخلاصكم .",{h:"والكنيسة توجد لنا مناسبات عديدة تنادينا أن نتيقظ :"},"هناك أصوام تقول لنا إصحوا واستعدوا . وهناك قداسات تقول لنا تعالوا تناولوا باستحقاق . وعظات وقراءات واجتماعات كلها تنادينا أن نهتم بأبديتنا ، ونحارب حروب الرب بكل اهتمام . لذلك علينا أن نتيقظ لأن الكنيسة تدعونا أن نقول للرب فى بدء صلاة نصف الليل « إنزع من عقولنا نوم الغفلة ، وأعطنا يارب يقظة ... » .",{h:"الشيطان يحب أن يكون (فريسته) متهاوناً ليسهل القضاء عليه ."},"إن المتهاون فى واجباته الروحية من السهل أن يسقط ، إذ لا يكون محصناً باستعداد روحى ، ولا بالمشاعر الروحية التى تغرسها وسائط النعمة فى القلب . لذلك فى بعض الأوقات إذا أراد الشيطان إسقاط إنسان ، يبدأ معه بسلاح التهاون ، فيكسل فى صلواته وقراءاته واجتماعاته الروحية واعترافه وتناوله . وإذ لا يكون منتبهاً لنفسه يضربه الشيطان فيسقط .","أما المهتم بواجباته الروحية ، فإن الله يكون دائماً أمام عينيه ، فيستحى من السقوط ، كما أن الله يعينه فى حروبه .",{h:"هناك نوع لا يصحو لنفسه إلا بعد السقوط ."},"مثال ذلك الإبن الضال ، الذى لم يستيقظ إلا بعد الضياع والإستمرار فيه مدة . وكذلك داود النبى حينما سقط لم يكن صاحياً لنفسه . إنما صحا حينما قال له ناثان « أنت هو الرجل » ! وكذلك سليمان الحكيم لم يكن فى حكمته حينما سقط . ولم يشعر أن الكل باطل وقبض الريح ، إلا بعد أن أغوته النساء ... !","(*) إقرأ كتابنا [ السهر الروحى ] ليشرح لك هذا الموضوع بالتفصيل ."],106:[{h:"أما أنت فمادام عدوك يزأر ، إعلن حالة التعبئة العامة ."},"قل للشيطان قف عند الحدود لا تتعداها . وجهز أنت كل أسلحتك من صوم وصلاة ، وسهر ويقظة قلب ، وتوبة واحتراس ، وتمسك بالرب . وكن متنبهاً لكل حركة من العدو ، لكل رغبة ، لكل فكر ، لكل حركة من الحواس . وكما يقول الرسول « مستأسرين كل فكر لطاعة المسيح » (٢كو ١٠ : ٥) .","وفى سهرك الروحى ، إستمع إلى قول الرسول :",{h:"« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس »"},"(أف ٦ : ١١) . كن ساهراً « وسيفك على فخذك من هول الليل » (نش ٣ : ٨) . نقصد سيف الروح ، ودرع البر ، وترس الإيمان (أف ٦) ، وكل الوسائط الروحية .",{h:"وهذا الإحتراس ، أو هذا الإستعداد ، يكون معك مدى الحياة ."},"إحترس حتى الموت . وكن صاحياً إلى آخر لحظة « لئلا يأتى بغتة فيجدك نائماً » (مر ١٣ : ٣٦) . السيد المسيح حورب حتى وهو على الصليب ، حين قيل له « إن كنت إبن الله إنزل من على الصليب » ... فكن إذن مستعداً باستمرار . ولا تقل قد كبرت ، أو قد خلصت !",{h:"واحترس من الشيطان الذى يحارب باللاهوتيات ."},"لئلا تقول « إرحمنى يارب » ، فيأتيك الشيطان وينهرك قائلاً : لا تقل إرحمنى مطلقاً . فقد رحمك الرب منذ زمان حينما فداك على الصليب وخلصك . إذن ما معنى كلمة « إرحمنى » هذه ؟! إنها هرطقة ! قل له : لقد رحمنى الرب وخلص نفسى . ولكننى لا أرحم نفسى ، بل كل يوم أضيع خلاصها ، لذلك أصرخ وأقول : إرحمنى . إسهر إذن على خلاص نفسك .",{h:"وفى سهرك أسلك بكل جدية وبكل تدقيق ."},"وكن أميناً جداً حتى فى القليل . فإن أمانتك وتدقيقك وجديتك ، تجعل الشيطان يهرب منك ، شاعراً أن حربه معك هى حرب خاسرة .","وهناك سلاح هام للإنتصار ، وهو أهم سلاح ، أعنى الصلاة ."],107:[{h:"٩ بالصـــلاة والصــوم"},"لما عجز التلاميذ عن إخراج شيطان ، قال لهم الرب :",{h:"هذا الجنس لا يخرج بشىء ، إلا بالصلاة والصوم (مر ٩ : ٢٩) ."},"وهكذا نرى أهمية الصلاة والصوم فى الإنتصار على حروب الشياطين ، أو بمعنى آخر أهمية إدخال الله فى حياتنا وحروبنا ، صارخين إلى الله وقائلين « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » .",{h:"إننا نفشل فى حروبنا إن واجهنا الشيطان وحدنا ، بدون الله ."},"إنما نحن نقول لله : عدونا هذا القوى الذى يجول كأسد يزأر ، عدونا هذا الماكر الواسع الحيلة ، نحن يارب لا نقدر عليه بمهارتنا وذكائنا ، إنما النجاة هى من عندك أنت . نحن على قدر إمكاننا نميز الأرواح ، ونعرف الفكر الذى من عنده ونحترس منه . ولكن القوة تأتى من عندك .",{h:"بقدر إمكاننا نجاهد . ولكن أنت الذى تقودنا فى موكب نصرتك ."},"فى كل خطية كبيرة أو صغيرة ، لا نريد أن نقف وحدنا تجاه الشيطان ، إنما لابد أن يقف الله معنا . ولذلك نقول له فى بدء صلاة باكر « نسألك أن تحفظنا فى هذا اليوم بغير خطية » ، ونقول له فى ختام هذه الصلاة « هب لنا فى هذا اليوم الحاضر أن نرضيك فيه ، واحرسنا من كل شىء ردىء ، من كل خطية ، ومن كل قوة مضادة » ، « أحطنا بملائكتك القديسين ، لكى نكون بمعسكرهم محفوظين ومرشدين » ...",{h:"والمفروض أن نطلب معونة الله من أول الطريق ."},"كثيرون لا يلجأون إلى الله إلا بعد أن تضيق بهم السبل جداً ، كالذى لا يلجأ إلى الطبيب إلا بعد أن يشتد عليه المرض ويصل إلى حالة سيئة للغاية . أما نحن ، فإن الكنيسة تعلمنا أن نصلى من أجل النجاة قبل أن تأتى الحروب ...",{h:"وهكذا تكون صلاة وقائية ، قبل اللجوء إلى الصلاة العلاجية ."},"إننا نطلب من الله أن يبطل كل فخاخ الشيطان المنصوبة لنا . ولا ننتظر حتى نقع فى تلك الفخاخ ، ثم نطلب من الله أن يخرجنا منها ! وهكذا فى صلاة الشكر نطلب من"],108:["الله أن يبعد عنا « كل تجربة ، وكل فعل الشيطان ... وقيام الأعداء الخفيين والظاهرين » ... يبعدها عنا قبل أن تجىء ... « ولا يدخلنا فى تجربة » .",{h:"نحن لا نضطرب أمام حروب العدو ، إنما نطلب معونة الله ."},"هذا الشيطان الذى له خبرة ٧٠٠٠ سنة فى محاربة البشر ، أنا لا أقدر عليه . أما أنت يارب فأزلى ، كائن قبل أن يكون هذا الشيطان . وهو صنعة يديك من قبل أن يسقط . وتعرف كل حيله . وتستطيع أن تربطه وتقيده وتضع له حدوداً ، بل وتطرده طرداً . لذلك نجنى منه .","هكذا إلجأ إلى الصلاة . لأنك بدونها لا تخلص .",{h:"وإن فشلت فى محاربة العدو ، إعرف أنك فاشل فى صلواتك ."},"ولو كانت لك صلاة قوية ، لانتصرت حتماً . وتأكد أن الله إن سمع صراخ المساكين ، لابد أن يستجيب . إنه نفسه يقول « من أجل صراخ المساكين وتنهد البائسين ، الآن أقوم - يقول الرب - أصنع الخلاص علانية » (مز ١٢ : ٥) . لذلك قل له : « قم أيها الرب الإله ، وليتبدد جميع أعدائك ، وليهرب من قدام وجهك كل مبغضى إسمك القدوس » (عد ١٠ : ٣٥) . قم يارب « فإن البار قد فنى ، وقلت الأمانة من بنى البشر » (مز ١٢ : ١) . قم إصنع الخلاص علانية « إستل سيفك على فخذك أيها الجبار . إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{h:"إن الشياطين هم أعداؤك يارب ، قبل أن يكونوا أعدائى ."},"إنهم يحاربون ملكوتك فىّ وفى غيرى ، فحاربهم عنى وعن الجميع . ولا تتركنا وحدنا فى حروب الشياطين ، لأننا بدونك لا نستطيع أن نفعل شيئاً (يو ١٥ : ٥) .","إن داود الذى اختبر نصرة الرب فى حروبه قال فى المزمور :",{h:"« يمين الرب صنعت قوة . يمين الرب رفعتنى » (مز ١١٨ : ٥ ، ٦) ."},"فهل جربت يمين الرب فى حياتك ؟ هل جربت خلاص الرب ، الذى قال عنه موسى النبى « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) . لو أنك اختبرت هذا ، لاستطعت أن تقول مع داود النبى « الرب لى معين وأنا أرى بأعدائى » (مز ١١٨) ، « يسقط عن يسارك ألوف ، وعن يمينك ربوات ، وإليك لا يقتربون » (مز ٩١ : ٧) ."],109:["إنك جربت تفكيرك وذكاءك وعزيمتك وتدبيرك ، ومعونات الناس لك ، ولكن هل جربت خلاص الرب ؟ هل جربت مفعول الصلاة القوية الممسكة بقرون المذبح ؟ ليتك تفعل ... لا تكن كإنسان يقول للرب :",{h:"أتركنى يارب أن أعمل . وإن وقعت ولم أقدر أن أقوم ، سأطلبك ."},"ولماذا تنتظر إلى أن تقع ولا تقدر أن تقوم . أطلبه من الآن ، تجد قوته إلى جوارك لكى لا تقع . طبعاً إن وقعت وطلبت الله سيقيمك ، لكنك ستقوم وأنت مجروح ومكسور ! إلجأ إلى اليد الحصينة التى تحميك ، واصرخ إلى الرب قائلاً « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » ، وحينئذ يتدخل الله لإنقاذك . وحينئذ تغنى مع المرتل :",{h:"« الفخ انكسر ونحن نجونا . عوننا من عند الرب الذى صنع السماء والأرض »"},"(مز ١٢٤ : ٧ ، ٨) . أطلب من الرب إذن أن ينصرك كما نصر المجاهدين قبلك ، وأن يعطيك قوة كما أعطاهم ، وأن يعطيك نعمته وفعل روحه القدوس ، لكى تكون محصناً بقوته الإلهية ... واطلب إليه أن ينتهر الشيطان كما انتهره من قبل ، ويقول له « إذهب يا شيطان » (متى ٤ : ١٠) .",{h:"١٠ إذهـب يـا شيـطـان"},"عبارة (إذهب يا شيطان) التى بها إنتهر الرب الشيطان ، لم تكن للتجربة على الجبل فقط ، إنما أيضاً لكل حروب الشيطان مع البشر ...","فليتك تختبر قوة هذه العبارة فى حياتك ، حينما يتدخل الرب ويطرد الشيطان ، فلا يشتد فى حربه عليك ، أو على الأقل يفعل كما فعل فى التجربة على الجبل ويتركك إلى حين (لو ٤ : ١٣) .","فإن وجدت أن الحرب قد رفعت عنك ، ووجدت أن الأفكار والشهوات لا تتعبك كما كان يحدث قبلاً . وإن فارقك الفتور وأشرق عليك نور جديد ، فاعرف أن الرب قد انتهر الشيطان وطرده ... ليذهب بعيداً عنك .",{h:"إن الله لا يسمح أن نكون محاربين باستمرار من الشيطان ."},"ولا يسمح أن يمسكنا الشيطان بقبضته . وإن كان الله يترك الشيطان أحياناً"],110:["ليجربنا ، فذلك لكى ننال الفوائد الروحية التى فى هذه الحروب . وعندما يضغطنا الشيطان باليأس أو بالإضطراب ، ينتهره الله قائلاً : إذهب يا شيطان .",{h:"قد تمر على الإنسان أوقات راحة من حروب الشياطين ."},"ويجد نفسه طليقاً فى مجال الله ، فرحاً بعشرته ، بل يتعجب كيف كان يخطىء قبلاً ويسقط . وفى وسط هذا الجو الروحى والجو المريح ، يشعر أن المسيح له المجد الذى جرب حروب الشياطين ، قد انتهر الشيطان من أجله ... وكأنه يقول للشيطان : أنا قد أعطيتك حرية التجربة والإختبار ، ولكن ليس إلى هذا الحد . فاذهب يا شيطان ...",{h:"صدقونى يا إخوتى إن الخطايا التى نقع فيها هى شىء قليل من حروب الشياطين التى كان يمكن أن تضغط علينا بعنف . ولكن الله منعها عنا قبل أن تصل إلينا . ولم يسمح للشيطان أن يجربنا بها . أما الحروب التى سمح الله بها ، فهى التى تقدر أن تقاومها . ولو سمح بالأخرى ما كنت تحتمل ..."},"وقد تتعرض أحياناً لحرب قاسية ، وتكون على وشك السقوط ...",{h:"ثم تجد أنك نجوت من هذه الحرب بدون أن تشعر ."},"وذلك لأن الله قد تدخل . وقال للشيطان إذهب ... إنك ضغطت على هذا الإنسان بعنف ... ويذكرنا هذا بأن الله كان يضع للشيطان حدوداً فى حربه مع أيوب الصديق : مرة لا يمد يده إليه (أى ١ : ١٢) ، ومرة لا يمد يده إلى نفسه (أى ٢ : ٦) .",{h:"إن عبارة « إذهب يا شيطان » فيها عزاء كبير لنا ."},"تشعرنا أن حروب الشيطان محدودة ، وأنه ليست له حرية مطلقة حتى يفعل بنا ما يشاء . وأيضاً بأن الشيطان هو أيضاً تحت قبضة ضابط الكل ، القادر أن ينتهره حينما يشاء ، ويمنعه ويضع له حدوداً وسدوداً وقيوداً ... بل ويطرده . فلنطمئن إذن أن الحروب التى نتعرض لها هى فى حدود قوتنا وطاقتنا ومقاومتنا ، وأنه بإمكاننا أن ننتصر عليها ، إن أردنا .","إن الله أعطانا سلطاناً على الشيطان ، نقول له إذهب فيذهب .",{h:"ولكننا فى أحيان كثيرة لا نشاء أن نقول له : إذهب ."},"أحياناً نتراخى فى حربه ، ونعطيه فرصة فينا ومجالاً . وأحياناً نرضخ ونتراخى"],111:["ونؤجل طرده . وأحياناً نفاوضه ونهادنه ولا نكون حازمين معه . بل أحياناً نستسلم له ، أو نتعاون معه ... ولا نشاء مطلقاً أن نقول له : إذهب ...",{h:"بل أخشى أن البعض يفتح له قلبه وحواسه ، ويرحب به !"},"كثيرون لا يستطيعون أن يطردوا الشيطان بكلمة إذهب يا شيطان . لأن بينهم وبين الشيطان صداقات ومحبة وعشرة . وهناك قيود تربطهم به وتخضعهم لإرادته . بل لو انتهره الرب وذهب عنهم ، قد يسعون هم إليه ، ويتوسلون إليه قائلين : إرجع إلينا وأعنا ... ! هم لا يريدون أن يبتعد الشيطان عنهم !","إن القلب النقى هو الذى يستطيع أن ينتهر الشيطان ويقول له : إذهب . ويفرح بانتهار الرب له . ولكن البعض له حاجة عند الشيطان يستبقيه من أجلها ، بل ويدافع عنه ! تماماً مثلما فعل أهل أفسس فى دفاعهم عن آلهتهم أرطاميس وتمثالها (أع ١٩ : ٢٨) . لذلك فإن الرب كان أحياناً - قبل أن يشفى إنساناً - يسأله أولاً : أتريد أن تبرأ (يو ٥ : ٦) .",{h:"فإن شاء الرب أن يطرد الشيطان عنك ، إستجب له ..."},"فلتتحد إرادتك مع إرادة الله فى طرد الشيطان من حياتك ، مهما كان ذلك سيكلفك ، ومهما (أتعبك) ذهاب الشيطان بعيداً عنك . لأن الكتاب يقول « أمينة هى جراح المحب . وغاشة هى قبلات العدو » (أم ٢٧ : ٦) . فقد يقبّلك الشيطان متظاهراً بالحب ، موهماً إياك أنه يسعدك ويحقق شهواتك ورغباتك ، لكى لا تطرده من حياتك ، بينما هو يعدّ لك فخاخاً لهلاكك ! فلا تصدقه .","أدخل إلى أعماق قلبك وفكرك ، وقل : إذهب يا شيطان .","وحينما ينتهر الرب هذا الشيطان ، إنتهره معه بكل صدق وبكل حزم وحسم ، مع إلغاء كل ما سبق من علاقات بينك وبينه . ولا تحاول أن تجمع بين الله والشيطان فى حياتك . لأنه « لا شركة بين النور والظلمة » (٢كو ٦ : ١٤) .","لا تصادق عدواً لله ، ولا تشترك معه فى أى عمل . واطرد كل متعلقاته فى حياتك وفى بيتك وفى مكتبتك . كل صوره ، وكل كتبه ومجلاته ، وكل ملاهيه وأغانيه وقصصه ، وكل أجهزته ، وكل أعوانه . قل له : إذهب يا شيطان ، ومعك كل ما ينتمى إليك . واقفل أمامه جميع الأبواب حتى لا يعود إليك ."],112:[{h:"وليكن طرداً ، بكل جدية ، طرداً نهائياً ، بتصميم ..."},"لا طرداً متذبذباً ، متردداً ، قلقاً ... كما يقول المثل العامى « عين فى الجنة ، وعين فى النار » ! وتأكد تماماً أن بقاء الشيطان بكل حيله ، خسارة لك . واحترس من أن تقبل ربحاً عن طريقه - لأن هذا (الربح) يكون ثمناً لحياتك وأبديتك ...","ومن الوسائل التى تساعدك فى طرد الشيطان :",{h:"١١ مقـابـلـة الخطيـة بالوصـيـة"},{h:"إحفظ عدداً من الآيات فى مواجهة الخطايا التى تحاربك ."},"فمثلاً إن حاربك الشيطان بالغضب قل له « إن غضب الإنسان لا يصنع بر الله » (يع ١ : ٢٠) . أو قول أحد القديسين « ولو أقام الغضوب أمواتاً ، فما هو مقبول عند الله ، ولا يقبله أحد من الناس » .","وإن حاربك العدو بنظرة شريرة ، ضع أمامه قول الرب « من نظر إلى إمرأة واشتهاها ، فقد زنى بها فى قلبه » (متى ٥ : ٢٨) . وإن حاربك بالزنا ، تذكر قول الرسول « ألستم تعلمون أن جسدكم هو هيكل الروح القدس » (١كو ٦ : ١٩) ، « ألستم تعلمون أن أجسادكم هى أعضاء المسيح . أفآخذ أعضاء المسيح وأجعلها أعضاء زانية ؟! حاشا » (١كو ٦ : ١٥) .","وإن حاربك الشيطان بأخطاء اللسان ، ضع أمامك آيات الكتاب « كثرة الكلام لا تخلو من معصية » (أم ١٠ : ١٩) ، « ليكن كل إنسان مسرعاً إلى الإستماع ، مبطئاً فى التكلم » (يع ١ : ٢٠) ، وأيضاً قل « ضع يارب حافظاً لفمى ، وباباً حصيناً لشفتى » (مز ١٤١ : ٣) .","وإن حاربك الشيطان بمحبة العالم الحاضر ، وما فيه من مغريات ، ضع أمام ذلك قول الكتاب « محبة العالم عداوة لله » (يع ٤ : ٤) . وأيضاً « لا تحبوا العالم ولا الأشياء التى فى العالم . إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) ، « العالم يمضى وشهوته معه » (١يو ٢ : ١٧) . وأيضاً تذكر كل ما ورد فى سفر الجامعة عن هذا الموضوع ، وبخاصة قول الكتاب « باطل الأباطيل . الكل باطل"],113:["وقبض الريح . ولا منفعة تحت الشمس » (جا ١ : ٢ ، ١٤ ، ٢ : ١١) .","وإن حاربك الشيطان بالكبرياء ، تذكر قول الكتاب « قبل الكسر الكبرياء ، وقبل السقوط تشامخ الروح » (أم ١٦ : ١٨) . وأيضاً « يقاوم الله المستكبرين . أما المتواضعون فيعطيهم نعمة » (يع ٤ : ٦ ، ١بط ٥ : ٥) .",{h:"إن أسلوب مواجهة الخطية بالوصية ، من نصائح القديس مار أوغريس ."},"وهو موجود بأسلوب واسع جداً فى ميامره عن (حرب الأفكار) ، تستطيع أن تقرأها فى مخطوطات الأديرة . ومع ذلك فأنت تستطيع أن تستخرج لنفسك من الكتاب مجموعة من الآيات تستخدمها فى حروبك ، وتحفظها جيداً فى ذاكرتك .",{h:"إن كلمة الله حية وفعالة (عب ٤ : ١٢) ولها تأثيرها ."},"وثق أنك حينما تتذكرها لا بد سيكون لها عمل رادع داخل نفسك . وهكذا قال الرب « كلمتى التى تخرج من فمى لا ترجع إلىّ فارغة . بل تعمل ما سررت به ، وتنجح فى ما أرسلتها له » (أش ٥٥ : ١١) . جرّب إذن قوة كلمة الرب فى حروب الشياطين"],114:[{h:"الفصل الخامس"},{h:"فوائد الحروب الروحية"}],115:[{h:"إن الله لا يمنع عنا حروب الشيطان . ولكنه يقف معنا فيها ، وأيضاً يجعلها لفائدتنا الروحية ."},"ومن أجل هذا ، فإن القديس الأنبا أنطونيوس ، بعد أن عاش معه القديس بولس البسيط فترة محتمياً تحت ظل صلواته ، طلب منه الأنبا أنطونيوس أن يسكن وحده ، لكى يستطيع فى الوحدة أن يجرب حروب الشياطين ويقتنى منها فائدة لنفسه .","فما هى الفوائد الروحية التى تقتنى من حروب الشياطين ؟ والتى مارسها المتوحدون فى البرارى والقفار حتى تفرغوا لمحبة الله ، وبالتالى لقتال العدو ؟",{h:"١ - الفائدة الأولى هى الإتضاع :"},"كلما تشتد حروب الشياطين على إنسان فى قوة وعنف ، يشعر بضعفه أمامها ، فيزول عنه انتفاخه ، وينسحق قلبه من الداخل ، ويرى أنه معرض للسقوط ، وأن إرادته ليست معصومة من الخطأ . ويعرف أن الخطية « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) .",{h:"٢ - الصلاة والتمسك بالله وطلب معونته :"},"الإنسان وهو مستريح ، قد لا يطلب المعونة الإلهية ، وقد لا يشعر أنه فى مسيس الإحتياج إليها . ولكنه إذا اشتدت عليه الحرب ، يصرخ إلى الله لينصره على عدو قاس . وهكذا إذ يشعر بضعفه يتمسك بالرب فى صلاة عميقة ، وفى صلوات قوية ؛ هذا الذى قال « أدعنى فى وقت الضيق ، أنقذك فتمجدنى » (مز ٥٠ : ١٥) .",{h:"٣ - الحروب الروحية تدعو إلى الإشفاق على المخطئين :"},"الذى لم تحاربه الشياطين ، قد يقسو على المخطئين ويدينهم فى سقوطهم . أما الذى حورب ، وقد جرّب عنف العدو ، فإنه يشفق على كل خاطىء ويصلى لأجله . وكما قال القديس بولس الرسول « أذكروا المقيدين كأنكم مقيدون معهم . واذكروا المذلين"],116:["كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) . وقال عن رب المجد « لأنه فيما هو قد تألم مجرباً ، يقدر أن يعين المجربين » (عب ٢ : ١٨) .",{h:"٤ - والحروب الروحية تعطى الإنسان خبرة :"},"فيتمرس بالقتال ، ويتعلم الحرب ، ويعرف حيل العدو وفنونه ، ويأخذ خبرة سواء من قيامه أو سقوطه . والمعروف أن كل ارتقاء درجة يسبقه امتحان ، من يجتازه يرتفع هذه الدرجة كما يحدث لطلاب العلم . وبهذا نرى أن الذين قد دخلوا فى حروب العدو إكتسبوا خبرة .","والخبرات الروحية هذه هى مدرسة تخرّج مرشدين روحيين ، قادرين على معونة غيرهم وتشجيعهم وكشف حيل العدو لهم .",{h:"٥ - والحروب بركة ننال بها أكاليل :"},"وكما قال أحد القديسين : لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب . وفى احتمالنا لحرب العدو ، وصمودنا فيها ، ومجاهدتنا ومقاومتنا ، فى كل ذلك تظهر محبتنا للرب ، وننال على ذلك أكاليل . وكما قال أحد الآباء : ليس الجنود المنتصرون هم فقط الذين ينالون أكاليل فى الحرب ، وإنما أيضاً الذين جرحوا وأصيبوا ، مادامو لم يستسلموا للعدو وقاتلوه .",{h:"٦ - والحروب تعطينا باستمرار روح الصحو والإستعداد :"},"وكما قال الرب « لتكن أحقاؤكم ممنطقة ، ومصابيحكم موقدة » (لو ١٢ : ٣٥) . شعور الإنسان بأنه فى حرب ، يجعله باستمرار مستعداً للقتال ، يستخدم كل الوسائط الروحية من صلاة وصوم واتضاع ومشورة روحية ، لكى ينتصر . بينما ربما لو خفت الحروب ، لقاده ذلك إلى الفتور الروحى . أما الحرب فتجعله فى حالة تأهب مستمر ، وفى حالة حرص وتدقيق . والخوف من السقوط يجعله يستعد بأكثر قوة حتى ينتصر .",{h:"٧ - والحروب الروحية تجعلنا أقوياء لا نخاف :"},"إنما يخاف الحرب ، الشخص الذى لم يدخلها ولم يقاتل . أما الذى يجرب"],117:["الحروب ، فإن ذلك يعطيه شجاعة وجسارة قلب . وما يأخذه من أكاليل يشجعه على دخول حروب أخرى ، ولا يخشى الفشل فى الحرب . هل يستطيع تلميذ أن يقول إننى من خوف السقوط لا أدخل الإمتحان ، بل ولا أدرس ولا أدخل مدارس ؟! كلا . بل هو يدخل الإمتحانات فى شجاعة قلب ، ويقول : سأنتصر على كل مصاعب العلم وامتحاناته .",{h:"٨ - والحروب الروحية هى مدرسة للإيمان :"},"نرى فيها يد الله كيف تتدخل ، وكيف تعين وتنصر ، وكيف تنتهر العدو ، وكيف تعطى داود الصغير القوة لينتصر على جليات الجبار . وهكذا تعمّق إيماننا فى محبة الله ورعايته وعمله لأجلنا .",{h:"٩ - والحروب الروحية هى مبدأ تكافؤ فرص للشيطان :"},"أخذ الفرصة التى يقاتل فيها ، وبكل قوته . لئلا يحتج الشيطان على أولاد الله ويقول : لماذا يكافئهم الرب ؟ إننى لو أخذت فرصة لأسقطتهم ، كما اشتكى أيام أيوب ، وأخذ فرصته ، وبقى أيوب محتفظاً بكماله (أى ٢) . فالله يسمح للشيطان بأن يحارب المؤمنين ، ويعطى المؤمنين قوة على الإنتصار ، ويخرج الشيطان فى خزى .",{h:"١٠ - وأخيراً فالحروب الروحية تفتح أبواب الملكوت لنا ، وتحدد درجتنا فيه :"},"وكل إنسان ينال أجرته بحسب تعبه ، وبحسب جهاده . وبهذا نرى المؤمنين يبذلون كل جهدهم لكى يعبروا لله عن حبهم . لأنه كيف يظهر حبهم دون أن يُختبر بالحروب الروحية . وكيف تتحدد درجتهم فى الملكوت بدون هذا الإختبار الروحى .","فليكن الرب معنا فى كل حروبنا الروحية ، يقودنا فى موكب نصرته ."]}}}}();